window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch01"]={"id":"ch01","title":"第一章 绪论","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"细胞学说 · 原核/真核 · 模式生物","modules":[{"i":0,"name":"模块一：细胞生物学发展简史","slides":[{"i":0,"sec":"绪论","title":"第一章 绪论 · 内容框架 (p1)","notes":"本章主线：①细胞学说基本原则(the tenets of cell theory)；②细胞的基本性质(the basic properties of cells)；③两类基本细胞——原核细胞与真核细胞；④研究常用的模式材料(model organisms)。绪论为后续各章建立框架与术语体系。","page":1,"level":"了解","img":"assets/img/ch01/p001.jpg","anim":null,"fig":null,"points":null,"check":{"q":"第一章绪论主要围绕下列哪条主线展开？","o":["A. 细胞学说基本原则、细胞基本性质、原核与真核细胞、模式材料","B. 细胞呼吸与能量代谢的生化途径","C. 神经冲动的产生与传导机制","D. 孟德尔遗传三大定律的染色体基础"],"a":"A","e":"绪论为后续各章建立框架与术语体系，主线即细胞学说、细胞基本性质、原核与真核细胞、模式材料四部分。","oe":["对：与笔记所列绪论四条主线完全一致","错：属代谢内容，非本章主线，不符合本页所学概念","错：属生理学内容，非本章主线，不符合本页所学概念","错：非绪论所列框架内容，不符合本页所学概念"],"basis":"本章主线：细胞学说原则、细胞基本性质、原核与真核细胞、模式材料"},"cards":null,"mem":"绪论四主线：细胞学说·基本性质·原核真核·模式生物"},{"i":1,"sec":"第一节 发展简史","title":"细胞生物学发展简史 (p2)","notes":"发展脉络：①细胞的发现(1665胡克)；②细胞学说的建立(1838-1858)；③细胞学经典时期(原生质理论、细胞分裂、细胞器发现)；④实验细胞学阶段(细胞遗传学/细胞生理/细胞化学)；⑤细胞超微结构学发展；⑥分子细胞生物学(分子、细胞、超微结构水平)。","page":2,"level":"掌握","img":"assets/img/ch01/p002.jpg","anim":null,"fig":null,"points":["细胞发现：1665 胡克观察软木塞命名 cell；1674 列文虎克首次观察活细胞。","细胞学说：1838–1858 Schleiden、Schwann、Virchow。","细胞学时期 1875–1900：原生质理论、受精/分裂、细胞器发现。","实验细胞学 1900–1953；分子细胞生物学 1953 至今。"],"check":{"q":"关于细胞生物学发展简史，下列说法正确的是（　）","o":["A. 分子细胞生物学阶段始于1900年","B. 细胞学说由Schleiden、Schwann和Virchow于1838—1858年间建立","C. 1665年胡克首次观察到活细胞并命名cell","D. 细胞学经典时期指1900—1953年"],"a":"B","e":"细胞生物学经历细胞发现、细胞学说建立、经典时期、实验细胞学、超微结构与分子细胞生物学等阶段；细胞学说于1838—1858年建立。","oe":["分子细胞生物学始于1953年，而非1900年。","正确，三人于1838—1858年建立细胞学说。","胡克1665年观察的是软木塞死细胞，首次观察活细胞的是列文虎克。","经典时期为1875—1900年，1900—1953年属实验细胞学时期。"]},"cards":[{"front":"细胞生物学发展简史分为哪几个主要阶段？","back":"①细胞的发现(1665胡克)；②细胞学说建立(1838-1858)；③经典时期；④实验细胞学；⑤超微结构；⑥分子细胞生物学","mnemonic":"发现—学说—经典—实验—超微—分子","type":"流程","useImg":false,"blank":"细胞学说","blank2":"经典时期"}],"mem":"发现—学说—经典—实验—超微—分子"},{"i":2,"sec":"第一节 发展简史","title":"细胞的发现——胡克 (p3)","notes":"1665年英国显微镜学家Robert Hooke(胡克)观察栎树软木塞切片，看到类似蜂巢的网状小室，借用拉丁文'cellulae'(小室)称为'cell'(细胞)。这是人类第一次发现细胞(实为死细胞的细胞壁)。名言:'appear a little porous…much like a honeycomb'。","page":3,"level":"掌握","img":"assets/img/ch01/p003.jpg","anim":null,"fig":null,"points":null,"check":{"q":"胡克在软木塞切片中看到并命名为“cell”的蜂窝状小室，其本质是？","o":["A. 生活细胞的细胞核","B. 细胞质基质","C. 死细胞的细胞壁","D. 细胞膜"],"a":"C","e":"胡克借用拉丁文cellulae命名小室，实为植物死细胞残留的细胞壁，这是人类首次观察到细胞。","oe":["错：核并非其观察到的结构，不符合本页所学概念","错：观察到的是空腔，非细胞质，不符合本页所学概念","对：笔记明确其所见实为死细胞的细胞壁","错：细胞膜不是该网状小室的本质"],"basis":"人类第一次发现细胞(实为死细胞的细胞壁)"},"cards":[{"front":"谁在何时首次发现细胞？他观察的是什么材料？","back":"1665年英国胡克(Robert Hooke)观察栎树软木塞切片，看到蜂窝状小室，命名为cell(实为死细胞的细胞壁)","mnemonic":"胡克看软木，蜂窝叫细胞","type":"例证","useImg":true,"blank":"胡克","blank2":"软木塞"}],"mem":"胡克看软木，蜂窝叫细胞"},{"i":3,"sec":"第一节 发展简史","title":"列文虎克——首次观察活细胞 (p4)","notes":"1674年荷兰布商Antonie van Leeuwenhoek(列文虎克)为检查布质量自制透镜，装配高倍显微镜(约300倍)，观察到血细胞、池塘水滴中的绿藻、原生动物、人和哺乳动物的活精子——人类第一次观察到完整的活细胞。","page":4,"level":"掌握","img":"assets/img/ch01/p004.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于列文虎克的贡献，下列说法正确的是（　）","o":["A. 他首次提出细胞学说","B. 他观察到的是死细胞的细胞壁","C. 他用自制高倍显微镜首次观察活细胞","D. 他于1665年观察软木塞切片"],"a":"C","e":"1674年列文虎克自制约300倍显微镜，观察到血细胞、绿藻、原生动物和活精子，是人类首次观察到完整活细胞。","oe":["细胞学说由施莱登和施旺建立，并非列文虎克","观察死细胞细胞壁的是胡克，不是列文虎克","正确，1674年他首次观察到完整的活细胞","1665年观察软木塞切片的是胡克"]},"cards":[{"front":"谁首次观察到活细胞？观察到了哪些活细胞？","back":"1674年荷兰列文虎克自制高倍显微镜(约300倍)，观察到血细胞、绿藻、原生动物、活精子——首次看到完整活细胞","mnemonic":"虎克看死壁，文虎克看活物","type":"例证","useImg":false,"blank":"列文虎克","blank2":"血细胞"}],"mem":"虎克看死壁，文虎克看活物"},{"i":4,"sec":"第一节 发展简史","title":"细胞学说的建立 (p5)","notes":"①1838年德国植物学家施莱登(M.J.Schleiden)：植物组织虽结构差异大但都由细胞构成，植物胚由单个细胞产生。②1839年德国动物学家施旺(Theodor Schwann)《关于动植物的结构和生长的一致性的显微研究》：地球生物都由细胞构成；所有生活细胞结构类似。③1858年德国病理学家魏尔肖(Rudolf Virchow)补充第三条：所有细胞都来自已有细胞的分裂(细胞来自细胞)。","page":5,"level":"掌握","img":"assets/img/ch01/p005.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于细胞学说的建立过程，下列叙述正确的是（　）","o":["A. 施莱登提出所有动物都由细胞构成","B. 施旺于1838年提出植物胚由单个细胞产生","C. 细胞学说由达尔文提出并完善","D. 魏尔肖于1858年补充“细胞来自已有细胞”"],"a":"D","e":"1838年施莱登研究植物，1839年施旺研究动物，1858年魏尔肖补充第三条：所有细胞都来自已有细胞的分裂。","oe":["提出植物由细胞构成的是施莱登，并非施旺","1838年施莱登研究植物，施旺1839年研究动物","细胞学说与达尔文没有直接关系，非其提出","正确，魏尔肖1858年补充细胞来自已有细胞"]},"cards":[{"front":"细胞学说由哪三位科学家建立？各自贡献是什么？","back":"1838施莱登：植物由细胞构成；1839施旺：动植物都由细胞构成；1858魏尔肖：细胞来自已有细胞的分裂","mnemonic":"登植物，旺动物，肖补分裂","type":"流程","useImg":false,"blank":"细胞来自已有细胞的分裂","blank2":"施莱登"}],"mem":"登植物，旺动物，肖补分裂"},{"i":5,"sec":"第一节 发展简史","title":"细胞学说三个基本原则 (p6)","notes":"Cell theory三大原则：①All organisms are composed of one or more cells——所有有机体都由一个或多个细胞构成(病毒除外)；②The cell is the basic unit of structure and function——细胞是所有有机体结构和功能的基本单位，是生命活动的基本单位；③Cells can arise only by division from preexisting cells——所有细胞都来自已有细胞的分裂(1858 Virchow)。","page":6,"level":"掌握","img":"assets/img/ch01/p006.jpg","anim":null,"fig":null,"points":null,"check":{"q":"依据细胞学说，下列叙述正确的是？","o":["A. 细胞可由无机物自然发生","B. 新细胞只能由已存在的细胞分裂产生","C. 病毒具有完整的细胞结构","D. 细胞是能够独立生活的唯一形态单位"],"a":"B","e":"细胞学说第三原则指出所有细胞都来自已有细胞的分裂，否定了自然发生说。","oe":["错：与细胞学说内容相违背，不符合本页所学概念","对：对应“细胞只能来自已有细胞分裂”","错：病毒无细胞结构，被学说排除","错：表述绝对，非学说三原则内容"],"basis":"所有细胞都来自已有细胞的分裂"},"cards":[{"front":"细胞学说的三个基本原则是什么？","back":"①所有有机体由一个或多个细胞构成(病毒除外)；②细胞是结构和功能的基本单位；③所有细胞来自已有细胞的分裂","mnemonic":"组成—单位—来源","type":"定义","useImg":false,"blank":"细胞是结构和功能的基本单位"}],"mem":"组成—单位—来源"},{"i":6,"sec":"第一节 发展简史","title":"细胞学说的意义 (p7)","notes":"细胞科学是实验科学，发展既依赖实验观察又有待理论升华。细胞1665年发现，但此后170年细胞学无大发展，原因是没有将发现上升为理论。细胞学说创立后，细胞学突飞猛进，19世纪最后25年(1875-1900)成为细胞学的经典时期。","page":7,"level":"理解","img":"assets/img/ch01/p007.jpg","anim":null,"fig":null,"points":null,"check":{"q":"1665年细胞被发现后约170年细胞学无大发展，其主要原因是（　）","o":["A. 细胞学尚未成为一门独立学科","B. 当时显微镜分辨率严重不足","C. 科学家未将细胞的发现上升为理论","D. 缺乏足够多样的实验材料"],"a":"C","e":"细胞科学是实验科学，既依赖实验观察又有待理论升华；170年停滞在于未把发现上升为理论，细胞学说创立后细胞学迅猛发展。","oe":["学科独立性非根本原因，关键在于缺乏理论升华。","彼时显微镜已能观察细胞，并非停滞主因。","正确，未将发现上升为理论是长期停滞的原因。","细胞材料广泛存在，不是停滞的原因。"]},"cards":null,"mem":"细胞学说：发现170年未成理论，创立后进入经典期"},{"i":7,"sec":"第一节 发展简史","title":"威尔逊名言 (p8)","notes":"美国第一位细胞生物学家威尔逊教授(Edmund Beecher Wilson)1925年提出：'一切生命的关键问题都要到细胞中去寻找答案。'英文:'the key to every biological problem must finally be sought in the cell: for every living organism is, or at some time has been, a cell.'——强调细胞作为生命基本单位的核心地位。","page":8,"level":"了解","img":"assets/img/ch01/p008.jpg","anim":null,"fig":null,"points":null,"check":{"q":"威尔逊“一切生命的关键问题都要到细胞中去寻找答案”主要强调？","o":["A. 细胞学研究仅服务于遗传学","B. 生命现象只能在离体条件下研究","C. 细胞结构与功能彼此独立","D. 细胞是生命的基本单位，生命问题需在细胞层面求解"],"a":"D","e":"该名言突出细胞作为生命基本单位的核心地位，一切生物学问题最终都要回到细胞层面研究。","oe":["错：缩小了细胞生物学的范围，不符合本页所学概念","错：该说法与威尔逊名言的含义无关","错：细胞结构功能相互关联，不符合本页所学概念","对：笔记指明其强调细胞为生命基本单位"],"basis":"强调细胞作为生命基本单位的核心地位"},"cards":null,"mem":"威尔逊：一切生命关键问题到细胞中找答案"},{"i":8,"sec":"第一节 发展简史","title":"经典时期——原生质理论 (p9)","notes":"细胞学经典时期(1875-1900)。原生质(protoplasm)理论：在动、植物细胞中均发现'肉样质'的有弹性胶状物质，命名为'原生质'。1861年Max Schultze提出：有机体的组织单位是一小团原生质，这种物质在各种有机体中相似。","page":9,"level":"理解","img":"assets/img/ch01/p009.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于细胞学经典时期的原生质理论，下列说法正确的是（　）","o":["A. 原生质仅存在于动物细胞中","B. 1861年Max Schultze提出有机体的组织单位是一小团原生质","C. 原生质是不具弹性的晶体物质","D. 原生质理论由Virchow首先提出"],"a":"B","e":"原生质理论发现动、植物细胞中均有弹性胶状“肉样质”，1861年Schultze提出组织单位是一小团原生质，且在各种有机体中相似。","oe":["动、植物细胞均含原生质，并非仅动物。","正确，Schultze 1861年提出该观点。","原生质为有弹性的胶状物质，不是晶体。","该理论由Max Schultze提出，而非Virchow。"]},"cards":null,"mem":"原生质理论：Schultze 1861，组织单位是一团原生质"},{"i":9,"sec":"第一节 发展简史","title":"经典时期——细胞分裂与细胞器 (p10)","notes":"经典时期的两大发现：①细胞受精和细胞分裂(减数分裂、有丝分裂)现象的发现；②细胞器的发现，如中心体、染色体、线粒体、高尔基体。这些发现奠定了细胞结构学的基础。","page":10,"level":"掌握","img":"assets/img/ch01/p010.jpg","anim":null,"fig":null,"points":null,"check":{"q":"细胞生物学经典时期的两大发现是（　）","o":["A. 细胞学说的提出与完善","B. 细胞分裂现象与细胞器的发现","C. 显微镜的发明与细胞命名","D. DNA双螺旋与遗传密码的阐明"],"a":"B","e":"经典时期发现了细胞受精与细胞分裂（有丝分裂、减数分裂）现象，并发现中心体、染色体、线粒体、高尔基体等细胞器。","oe":["细胞学说建立属于更早的历史时期","正确，即细胞分裂现象与多种细胞器的发现","显微镜发明与细胞命名属细胞的发现时期","DNA双螺旋与遗传密码属分子生物学时期"]},"cards":[{"front":"细胞学经典时期的两大核心发现是什么？","back":"①细胞受精和细胞分裂(有丝分裂、减数分裂)现象的发现；②细胞器的发现(中心体、染色体、线粒体、高尔基体)","mnemonic":"一分裂，二细胞器","type":"组成数字","useImg":false,"blank":"细胞分裂","blank2":"细胞器的发现"}],"mem":"一分裂，二细胞器"},{"i":10,"sec":"第一节 发展简史","title":"实验细胞学时期 (p11)","notes":"实验细胞学时期(1900-1953)：采用实验手段研究细胞学问题，即从形态结构观察深入到生理功能、生物化学及遗传发育机理。三大分支：①细胞遗传(染色体结构/功能及与细胞器关系，研究遗传变异机制，如'染色体结构与基因表达')；②细胞生理(营养、能量、代谢、生长、发育、繁殖、运动性、适应性)；③细胞化学(细胞结构化学组成及分子定位，如富尔根染色、甲基绿-派洛宁染色、紫外分光光度法)。","page":11,"level":"掌握","img":"assets/img/ch01/p011.jpg","anim":null,"fig":null,"points":null,"check":{"q":"富尔根染色、甲基绿-派洛宁染色属于实验细胞学时期的哪一分支？","o":["A. 细胞遗传","B. 细胞生理","C. 细胞化学","D. 细胞形态学"],"a":"C","e":"实验细胞学时期分细胞遗传、细胞生理、细胞化学三支，染色与分子定位方法归属细胞化学。","oe":["错：该分支研究染色体与遗传变异机制","错：该分支研究营养、代谢、生长等","对：富尔根染色等属细胞化学分支","错：不是该时期所列三大分支名称"],"basis":"细胞化学(细胞结构化学组成及分子定位，如富尔根染色)"},"cards":[{"front":"实验细胞学时期有哪三大分支？各研究什么？","back":"①细胞遗传：染色体结构与功能、遗传变异机制；②细胞生理：营养、代谢、生长、发育等；③细胞化学：结构化学组成及分子定位","mnemonic":"遗传—生理—化学","type":"对比","useImg":false,"blank":"细胞遗传","blank2":"细胞生理"}],"mem":"遗传—生理—化学"}],"mcq":[{"id":"ch01_mcq_1","mod":"模块一：细胞生物学发展简史","modI":0,"q":"1665年首次发现细胞(死细胞壁)的科学家是？","o":["A. 列文虎克","B. 胡克(Robert Hooke)","C. 施旺","D. 魏尔肖"],"a":"B","e":"1665年胡克观察栎树软木塞切片，借用拉丁文'cellulae'命名'cell'。列文虎克1674年首次观察活细胞。","kp":"ch01_s0_2","oe":["列文虎克1674年首次观察活细胞，并非1665年发现细胞者。","1665年胡克观察软木塞死细胞壁并命名cell，为首次发现者。","施旺1839年参与提出细胞学说，非首次发现细胞。","魏尔肖1858年提出细胞来自细胞，非首次发现细胞。"]},{"id":"ch01_mcq_2","mod":"模块一：细胞生物学发展简史","modI":0,"q":"细胞学说的三个基本原则不包括？","o":["A. 所有有机体由一个或多个细胞构成","B. 细胞是结构和功能的基本单位","C. 所有细胞来自已有细胞的分裂","D. 细胞都由细胞核和细胞器组成"],"a":"D","e":"细胞学说三原则：①生物由细胞构成；②细胞是基本单位；③细胞来自细胞(1858魏尔肖)。D是原核/真核区别，非细胞学说。","kp":"ch01_s0_5","oe":["生物由细胞构成是细胞学说原则①，描述正确故非答案。","细胞是结构与功能基本单位是原则②，描述正确故非答案。","细胞来自已有细胞分裂是原则③(魏尔肖)，正确故非答案。","此说非细胞学说原则，且原核细胞无核膜与细胞器，为答案。"]},{"id":"ch01_mcq_3","mod":"模块一：细胞生物学发展简史","modI":0,"q":"补充细胞学说第三条原则(细胞来自细胞)的科学家是？","o":["A. 施莱登","B. 施旺","C. 魏尔肖(Rudolf Virchow,1858)","D. 威尔逊"],"a":"C","e":"1858年魏尔肖补充：所有细胞都来自已有细胞的分裂(Omnis cellula e cellula)。","kp":"ch01_s0_4","oe":["施莱登提出植物细胞学说，未补充细胞来自细胞原则。","施旺提出动物细胞学说，并非补充第三条原则者。","魏尔肖1858年提出所有细胞都来自已有细胞的分裂。","威尔逊1925年强调细胞的重要性，非补充该原则者。"]},{"id":"ch01_mcq_4","mod":"模块一：细胞生物学发展简史","modI":0,"q":"细胞学经典时期是哪一时间段？","o":["A. 1665-1838","B. 1838-1858","C. 1875-1900","D. 1900-1953"],"a":"C","e":"19世纪最后25年(1875-1900)是细胞学经典时期；1900-1953为实验细胞学时期。","kp":"ch01_s0_9","oe":["1665-1838是细胞发现到细胞学说建立时期，非经典时期。","1838-1858是细胞学说建立与完善时期，非经典时期。","19世纪最后25年即1875-1900为细胞学经典时期。","1900-1953为实验细胞学时期，并非经典时期。"]},{"id":"ch01_mcq_5","mod":"模块一：细胞生物学发展简史","modI":0,"q":"原核细胞与真核细胞在结构上的共同点是？","o":["A. 都有核膜","B. 都有膜被细胞器","C. 都有细胞膜、DNA/RNA和核糖体","D. 都有细胞骨架"],"a":"C","e":"共同点：都有细胞膜、DNA和RNA、核糖体。核膜、膜被细胞器、细胞骨架是真核特有。","kp":"ch01_s0_0","oe":["核膜是真核细胞特有结构，原核细胞没有核膜。","膜被细胞器为真核特有，原核细胞没有。","均有细胞膜、DNA/RNA和核糖体，是原核与真核的共同点。","细胞骨架是真核细胞特有，原核无典型细胞骨架。"]},{"id":"ch01_mcq_6","mod":"模块一：细胞生物学发展简史","modI":0,"q":"关于原核细胞的描述,正确的是？","o":["A. 有核膜和核仁","B. 只有拟核,无核膜核仁,边转录边翻译","C. 有膜被细胞器","D. 进行有丝分裂"],"a":"B","e":"原核无核膜核仁只有拟核→边转录边翻译；真核分室化，核内转录、胞质翻译。原核行简单分裂。","kp":"ch01_s0_2","oe":["核膜和核仁是真核特征，原核细胞没有核膜核仁。","原核只有拟核、无核膜核仁，可边转录边翻译，描述正确。","原核细胞没有膜被细胞器，本项说法错误。","原核行简单二分裂，不进行有丝分裂。"]},{"id":"ch01_mcq_7","mod":"模块一：细胞生物学发展简史","modI":0,"q":"已知最小的细胞是？","o":["A. 蓝藻","B. 支原体(Mycoplasma,0.1~0.3μm)","C. 大肠杆菌","D. 酵母"],"a":"B","e":"支原体是已知最小细胞，0.1~0.3μm。蓝藻属真细菌；酵母是最小真核模式生物。","kp":"ch01_s0_2","oe":["蓝藻(蓝细菌)较支原体大，不是已知最小细胞。","支原体直径约0.1-0.3μm，是已知最小的细胞。","大肠杆菌约1-3μm，明显大于支原体。","酵母是最小真核模式生物，体积大于支原体。"]}],"judge":[{"id":"ch01_judge_1","modI":0,"q":"1665年列文虎克首次观察到活细胞，并借用拉丁文“cellulae”命名了细胞。","a":"错","e":"1665年胡克(Robert Hooke)观察软木塞并命名“cellulae”；列文虎克1674年首次观察到活细胞。","kp":"ch01_s0_3","oe":["易误记为列文虎克1665年观察软木塞并命名cellulae，实为胡克所为。","1665年胡克观察软木塞并命名cellulae；列文虎克1674年才首次观察到活细胞。"]},{"id":"ch01_judge_2","modI":0,"q":"细胞学说认为所有生物（包括病毒）都由细胞构成。","a":"错","e":"细胞学说第一原则为“所有有机体由一个或多个细胞构成”，病毒是非细胞形态生命体，属例外。","kp":"ch01_s0_4","oe":["易误以为病毒也是细胞，忽略其为非细胞形态生命体，故判对。","细胞学说指所有有机体由一个或多个细胞构成，病毒是非细胞形态生命体，属例外。"]},{"id":"ch01_judge_3","modI":0,"q":"魏尔肖提出“细胞来自细胞”，补充了细胞学说的第三条原则。","a":"对","e":"1858年魏尔肖(Rudolf Virchow)补充：所有细胞都来自已有细胞的分裂。","kp":"ch01_s0_4","oe":["1858年魏尔肖补充‘细胞来自细胞’，即细胞只能由已有细胞分裂产生。","误以为该原则由施莱登或施旺提出，或否认其为细胞学说第三条，故判错。"]}],"fill":[{"id":"ch01_fill_1","modI":0,"q":"1665年________(Robert Hooke)首次发现细胞；1674年________首次观察到活细胞。","a":"胡克,列文虎克(van Leeuwenhoek)","kp":"ch01_s0_2","oe":["1665年胡克用自制显微镜观察软木薄片，看到细胞壁，首次发现并命名细胞。","1674年列文虎克用显微镜首次观察到细菌、原生动物等活细胞。"]},{"id":"ch01_fill_2","modI":0,"q":"细胞学说由________和________建立(1839)，1858年由________补充第三条'细胞来自细胞'。","a":"施莱登(Schleiden),施旺(Schwann),魏尔肖(Virchow)","kp":"ch01_s0_4","oe":["1839年德国植物学家施莱登提出所有植物由细胞组成，奠定细胞学说基础。","同年施旺把细胞学说推广到动物界，认为动物也由细胞构成。","1858年魏尔肖补充细胞来自细胞，即细胞只能由已有细胞分裂产生。"]},{"id":"ch01_fill_3","modI":0,"q":"细胞学说三原则：①所有有机体由________构成；②细胞是________的基本单位；③所有细胞来自________。","a":"一个或多个细胞,结构和功能,已有细胞的分裂","kp":"ch01_s0_5","oe":["细胞学说第一原则：所有有机体都由一个或多个细胞构成。","第二原则：细胞是生命体结构和功能的基本单位。","第三原则：所有细胞都来自已有细胞的分裂，即细胞来自细胞。"]}],"short":[{"id":"ch01_short_1","modI":0,"q":"简述细胞学说的建立过程及其三个基本原则。","a":"【建立过程】\n①1838年德国植物学家施莱登(M.J.Schleiden)：植物组织虽结构差异大但都由细胞构成，植物胚由单个细胞产生。\n②1839年德国动物学家施旺(Theodor Schwann)《关于动植物的结构和生长的一致性的显微研究》：地球生物都由细胞构成；所有生活细胞结构类似。\n③1858年德国病理学家魏尔肖(Rudolf Virchow)补充第三条：所有细胞都来自已有细胞的分裂。\n\n【三个基本原则】\n1. All organisms are composed of one or more cells——所有有机体都由一个或多个细胞构成(病毒除外)；\n2. The cell is the basic unit of structure and function——细胞是所有有机体结构和功能的基本单位；\n3. Cells can arise only by division from preexisting cells——所有细胞都来自已有细胞的分裂。\n\n【意义】\n细胞1665年发现后170年无大发展，因未上升为理论。细胞学说创立后细胞学突飞猛进，1875-1900成为经典时期。","kp":"ch01_s0_5"}],"calc":[{"id":"ch01_calc_3","modI":0,"q":"论述细胞学说的建立对细胞生物学发展的推动作用。","a":"细胞学说将零散的观察上升为理论,极大推动了细胞学发展","steps":"【建立前】\n①1665年胡克发现细胞；1674年列文虎克观察活细胞；\n②但此后约170年细胞学没有大发展；\n③原因：实验观察没有上升为理论。\n\n【建立】\n①1838施莱登(植物)、1839施旺(动物)提出细胞学说前两条；\n②1858魏尔肖补充第三条(细胞来自细胞)；\n③三原则：生物由细胞构成；细胞是基本单位；细胞来自细胞。\n\n【推动作用】\n①细胞科学是实验科学，既依赖实验观察又有待理论升华；\n②细胞学说创立后，细胞学突飞猛进；\n③19世纪最后25年(1875-1900)成为细胞学经典时期：原生质理论、细胞分裂(有丝/减数)、细胞器(中心体/染色体/线粒体/高尔基体)相继发现；\n④1900-1953实验细胞学时期：细胞遗传学、细胞生理学、细胞化学；\n⑤进而发展到超微结构、分子细胞生物学。\n\n【结论】\n细胞学说的建立是细胞生物学从描述走向理论、从静态走向动态的转折点。","kp":"ch01_s0_1"}],"term":[{"id":"ch01_term_1","modI":0,"term":"细胞学说(Cell Theory)","def":"①关于细胞是生物体基本单位的学说，由施莱登(1838)和施旺(1839)建立、魏尔肖(1858)补充（定义）。②三个基本原则：所有有机体由一个或多个细胞构成(病毒除外)；细胞是结构和功能的基本单位；所有细胞来自已有细胞的分裂（内容）。③意义：使细胞学从零散观察上升为理论，推动1875-1900细胞学经典时期的到来（意义）。","kps":"踩分点:①建立者(1分)②三原则(2分)③意义(1分)","kp":"ch01_s0_5"}]},{"i":1,"name":"模块二：细胞的基本性质","slides":[{"i":0,"sec":"第二节 基本性质","title":"细胞的基本性质——结构共性 (p12)","notes":"2.1 细胞结构上的共性：①细胞表面都具有选择透性的质膜(plasma membrane)；②细胞都具有遗传物质双链DNA(原核细胞是裸露的拟核，真核包裹在细胞核中)；③都有核糖体(Ribosome)合成蛋白质；④化学组成元素基本相同(C、H、O、N、P、S等)。","page":12,"level":"掌握","img":"assets/img/ch01/p012.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列属于细胞结构上共性的是？","o":["A. 都具有选择透性的质膜和核糖体","B. 都具有膜包被的细胞核","C. 遗传物质都以拟核形式存在","D. 都含有叶绿体进行光合作用"],"a":"A","e":"所有细胞都有选择透性质膜、双链DNA和核糖体，这是细胞在结构上的共同特征。","oe":["对：质膜与核糖体为笔记所列结构共性","错：原核细胞无膜包被的细胞核，不符合本页所学概念","错：真核DNA包裹在细胞核中，不符合本页所学概念","错：多数细胞并不含叶绿体，不符合本页所学概念"],"basis":"细胞都具有选择透性的质膜…都有核糖体合成蛋白质"},"cards":[{"front":"细胞在结构上有哪些共性？","back":"①都有选择透性质膜；②都有双链DNA(原核裸露拟核，真核在核中)；③都有核糖体合成蛋白质；④化学元素基本相同","mnemonic":"膜—DNA—核糖体—元素","type":"组成数字","useImg":true,"blank":"核糖体","blank2":"双链DNA"}],"mem":"膜—DNA—核糖体—元素"},{"i":1,"sec":"第二节 基本性质","title":"HeLa细胞系与细胞增殖 (p13)","notes":"1951年从一位名叫Henrietta Lacks的黑人妇女的宫颈癌细胞分离建立了HeLa细胞系，这是首例长期保存并运用至今的人类细胞系。细胞都能进行自我增殖和遗传(一分为二)，甚至体外培养条件下仍可增殖。","page":13,"level":"理解","img":"assets/img/ch01/p013.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于HeLa细胞系，下列说法正确的是（　）","o":["A. 来自小鼠的肿瘤细胞","B. 是首例建立的人类正常体细胞系","C. 只能有限传代，不能长期保存","D. 1951年从Henrietta Lacks的宫颈癌细胞分离建立"],"a":"D","e":"HeLa是1951年从黑人妇女Henrietta Lacks的宫颈癌细胞分离建立的首例长期保存并沿用至今的人类细胞系。","oe":["该细胞系源于人类，而非小鼠的肿瘤细胞。","实为宫颈癌细胞系，并非正常体细胞系。","该细胞系可长期保存并无限增殖。","正确，1951年源自Henrietta Lacks宫颈癌。"]},"cards":null,"mem":"HeLa：1951宫颈癌，首例长期保存人类细胞系"},{"i":2,"sec":"第二节 基本性质","title":"细胞的基本性质——功能共性 (p14)","notes":"功能共性：⑤细胞都能进行物质和能量的新陈代谢，都由酶控制各种化学反应(Virtually all chemical reactions in cells require enzymes→metabolism)；细胞需要和利用能量(地球上生命所需能量几乎都来自太阳电磁辐射)；⑥细胞都具运动性——细胞内各种物质运输、细胞自身整体运动。","page":14,"level":"掌握","img":"assets/img/ch01/p014.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于细胞功能上的共性，下列叙述正确的是？","o":["A. 都能进行光合作用制造有机物","B. 所有能量均由细胞自身化学合成","C. 都不具备运动能力","D. 都能进行新陈代谢，且反应由酶催化"],"a":"D","e":"细胞都能进行物质与能量的新陈代谢，各种化学反应均由酶控制，并可进行运动。","oe":["错：仅含叶绿体的细胞能进行，不符合本页所学概念","错：能量几乎都来自太阳电磁辐射","错：细胞普遍具有运动性，不符合本页所学概念","对：新陈代谢与酶催化为功能共性"],"basis":"细胞都能进行物质和能量的新陈代谢，都由酶控制各种化学反应"},"cards":[{"front":"细胞功能共性中，新陈代谢与能量的核心要点是什么？","back":"细胞都能进行物质和能量代谢；化学反应几乎都由酶催化；生命所需能量几乎都来自太阳电磁辐射。","mnemonic":"代谢靠酶，能量靠太阳","type":"功能","useImg":false,"blank":"酶","blank2":"物质和能量代谢"},{"front":"细胞功能共性中的运动性表现在哪些方面？","back":"细胞内各种物质运输；细胞自身整体运动。","mnemonic":"内运外动","type":"功能","useImg":false,"blank":"细胞内各种物质运输","blank2":"细胞自身整体运动"}],"mem":"代谢靠酶，能量靠太阳"},{"i":3,"sec":"第二节 基本性质","title":"细胞与细胞器的大小 (p15)","notes":"2.2 细胞与细胞器大小：以微米(μm)、纳米(nm)为单位测量。1μm=10^-6 m；1nm=10^-9 m。细胞核直径5-10μm；线粒体长约2μm。多数细胞需显微镜观察。","page":15,"level":"理解","img":"assets/img/ch01/p015.jpg","anim":null,"fig":"细胞的大小以微米(μm)为单位：多数细胞 1–100μm；细菌约 1μm，人的卵细胞约 200μm。图给出从分子到细胞的尺度，帮助建立“细胞尺度感”。","points":null,"check":{"q":"关于细胞与细胞器大小的测量，下列说法正确的是（　）","o":["A. 线粒体长约20μm","B. 1μm=10^-9 m","C. 细胞大小通常以毫米为单位测量","D. 细胞核直径约5—10μm"],"a":"D","e":"细胞与细胞器以微米、纳米测量，1μm=10^-6m；细胞核直径约5—10μm，线粒体长约2μm。","oe":["线粒体长约2μm，并非20μm。","1μm=10^-6m，1nm=10^-9m。","通常以微米、纳米为单位，而非毫米。","正确，细胞核直径约5—10μm。"]},"cards":null,"mem":"大小单位μm/nm；核5-10μm，线粒体约2μm"},{"i":4,"sec":"第二节 基本性质","title":"人体卵细胞 (p17)","notes":"单个200μm的细胞——人类卵细胞(human egg)，与精子(也是单细胞)在一起。卵细胞是人体最大的细胞之一，肉眼勉强可见，是研究细胞大小的直观例子。","page":17,"level":"了解","img":"assets/img/ch01/p017.jpg","anim":null,"fig":null,"points":null,"check":{"q":"人类卵细胞是人体最大的细胞之一，其直径约为（　）","o":["A. 2μm","B. 20μm","C. 2mm","D. 200μm"],"a":"D","e":"人类卵细胞直径约200μm，肉眼勉强可见，是研究细胞大小的直观例子。","oe":["2μm为一般细胞尺度，远小于卵细胞。","20μm过小，与卵细胞实际不符。","2mm过大，卵细胞直径约200μm。","正确，人卵细胞直径约200μm。"]},"cards":null,"mem":"人卵细胞200μm，人体最大细胞之一"},{"i":5,"sec":"第二节 基本性质","title":"恐龙卵细胞 (p18)","notes":"Large single cells: fossilized dinosaur eggs——已形成化石的恐龙卵细胞。说明单个细胞可以非常大，突破'细胞都很小'的直觉。\n\n【本页英文讲解】\n本页主题是“大体积单细胞：已形成化石的恐龙卵细胞（fossilized dinosaur eggs）”。关键术语：single cell（单细胞）、fossilized（已形成化石的）、dinosaur eggs（恐龙卵）。核心概念是单个细胞可以长得非常大，从而突破“细胞都很小”的直觉。这与翟中和《细胞生物学》第4版第一章绪论中关于细胞形态、大小差异极大的论述相呼应，卵细胞正是已知体积最大的细胞类型之一。考点：细胞大小并非固定不变，卵细胞常被用作“大细胞”的典型例证。","page":18,"level":"了解","img":"assets/img/ch01/p018.jpg","anim":null,"fig":null,"points":null,"check":{"q":"已形成化石的恐龙卵细胞最能说明（　）","o":["A. 恐龙卵细胞不是单个细胞","B. 细胞都极其微小，肉眼不可见","C. 单个细胞可以长得非常大","D. 只有卵细胞才能形成化石"],"a":"C","e":"恐龙卵细胞说明单个细胞可以长得非常大，突破“细胞都很小”的直觉，卵细胞是体积最大的细胞类型之一。","oe":["卵细胞本身即为单个细胞，并非多细胞结构。","与事实相反，个别细胞可以非常大。","正确，说明单个细胞可长得非常大。","化石形成与是否为卵细胞无必然联系。"]},"cards":null,"mem":"恐龙卵化石：单细胞可非常大"}],"mcq":[{"id":"ch01_mcq_8","mod":"模块二：细胞的基本性质","modI":1,"q":"古细菌通常生活在？","o":["A. 正常土壤","B. 极端环境(热泉、浓盐水、厌氧沉积层等)","C. 人体血液","D. 植物叶片"],"a":"B","e":"古细菌出现在极端环境：浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管等，如产甲烷菌。","kp":null,"oe":["古细菌多栖极端环境，并非以正常土壤为主。","古细菌常见于热泉、浓盐水、厌氧沉积层等极端环境。","人体血液并非古细菌的典型栖息环境。","植物叶片并非古细菌的典型栖息环境。"]},{"id":"ch01_mcq_9","mod":"模块二：细胞的基本性质","modI":1,"q":"真核细胞与原核细胞在遗传物质上的区别是？","o":["A. 完全相同","B. 真核有大量DNA-蛋白染色体,原核仅一个环状裸露DNA","C. 原核有多条染色体","D. 真核DNA裸露"],"a":"B","e":"真核：大量由DNA和蛋白质组成的染色体；原核：仅一个单链、环状、裸露的DNA染色体。","kp":"ch01_s1_0","oe":["真核与原核遗传物质差异显著，并非完全相同。","真核为DNA-蛋白染色体，原核仅一个环状裸露DNA。","原核通常仅一条环状DNA，并非有多条染色体。","真核DNA与蛋白质结合成染色体，并非裸露。"]},{"id":"ch01_mcq_10","mod":"模块二：细胞的基本性质","modI":1,"q":"原核与真核鞭毛的主要区别是？","o":["A. 完全相同","B. 原核由flagellin组成,真核为9+2微管(tubulin+dynein)","C. 原核由微管组成","D. 真核由鞭毛蛋白组成"],"a":"B","e":"原核鞭毛=单一蛋白flagellin；真核鞭毛=9+2微管结构(tubulin)，马达蛋白dynein。趋同进化经典例。","kp":"ch01_s1_0","oe":["两者结构组成截然不同，并非完全相同。","原核鞭毛由flagellin组成，真核为9+2微管(tubulin+dynein)。","原核鞭毛不含微管，微管结构是真核鞭毛的特征。","真核鞭毛由微管蛋白构成，鞭毛蛋白属原核鞭毛。"]},{"id":"ch01_mcq_11","mod":"模块二：细胞的基本性质","modI":1,"q":"大肠杆菌作为模式生物的优点不包括？","o":["A. 繁殖快(20-30min一代)","B. 基因组简单,1997年测序完毕","C. 有核膜和细胞器","D. 常用作蛋白质表达系统"],"a":"C","e":"大肠杆菌是原核生物，无核膜和膜被细胞器。其优点是繁殖快、基因组简单、表达量高。","kp":null,"oe":["繁殖快、20-30分钟一代是大肠杆菌的优点之一。","基因组简单、1997年测序完毕是其优点之一。","大肠杆菌是原核生物，无核膜和膜被细胞器，此说法错误。","常作蛋白质表达系统是其优点之一。"]},{"id":"ch01_mcq_12","mod":"模块二：细胞的基本性质","modI":1,"q":"第一个完成全基因组测定的被子植物是？","o":["A. 水稻","B. 拟南芥(Arabidopsis thaliana)","C. 玉米","D. 大豆"],"a":"B","e":"拟南芥基因组小(1.2亿碱基对)，是被子植物中第一个完成全基因组测定的植物。","kp":null,"oe":["水稻基因组较大，且晚于拟南芥完成全基因组测定。","拟南芥是被子植物中第一个完成全基因组测定的植物。","玉米基因组较大，并非首个完成全基因组测定的植物。","大豆并非首个完成全基因组测定的被子植物。"]}],"judge":[{"id":"ch01_judge_8","modI":1,"q":"细胞体积越大，其相对表面积越大，物质交换效率越高。","a":"错","e":"细胞体积与相对表面积成反比：体积越大，相对表面积越小，物质交换效率越低。","kp":"ch01_s1_0","oe":["若认为体积越大相对表面积越大则判对，实则两者成反比关系。","体积越大相对表面积越小，物质交换效率越低，故原说法错误。"]}],"fill":[{"id":"ch01_fill_4","modI":1,"q":"细胞的基本共性：都具有选择透性的________、遗传物质________、合成蛋白质的________。","a":"质膜(plasma membrane),双链DNA,核糖体","kp":"ch01_s1_0","oe":["所有细胞都具有选择透性的质膜，将细胞与外界环境分隔开。","细胞遗传物质均为双链DNA，保证遗传信息的稳定传递。","所有细胞都含核糖体，是合成蛋白质的场所，体现细胞基本共性。"]}],"short":[{"id":"ch01_short_3","modI":1,"q":"简述细胞的基本性质(共性与特性)。","a":"细胞的基本性质：\n\n【结构共性】\n①都具有选择透性的质膜(plasma membrane)；\n②都具有遗传物质双链DNA(原核为裸露拟核，真核包裹在细胞核中)；\n③都有核糖体(Ribosome)合成蛋白质；\n④化学组成元素基本相同(C、H、O、N、P、S等)。\n\n【功能共性】\n⑤都能进行物质和能量的新陈代谢，都由酶控制化学反应，需要和利用能量(能量几乎都来自太阳)；\n⑥都具运动性——细胞内物质运输及细胞整体运动；\n⑦都能自我增殖和遗传(一分为二)，体外培养仍可增殖(如HeLa细胞系)。\n\n【大小】以μm、nm为单位；细胞核5-10μm，线粒体约2μm；人体卵细胞约200μm，是最大的人体细胞之一。","kp":"ch01_s1_0"},{"id":"ch01_short_6","modI":1,"q":"为什么说细胞是生命活动的基本单位？","a":"细胞是生命活动基本单位的理由：\n\n【结构上】\n①所有有机体都由一个或多个细胞构成(病毒除外)；\n②细胞具有选择透性质膜，是相对独立的结构单位；\n③细胞具有遗传物质DNA和核糖体，能自我复制和合成蛋白质。\n\n【功能上】\n①细胞能进行物质和能量的新陈代谢，由酶催化各种化学反应；\n②细胞能自我增殖和遗传(一分为二)，体外培养仍可增殖；\n③细胞具运动性，能进行物质运输和整体运动；\n④一切生命现象(生长、发育、繁殖、遗传、变异、代谢)都以细胞为基础。\n\n【理论支持】\n威尔逊名言：'一切生命的关键问题都要到细胞中去寻找答案'。细胞学说确立细胞是生物结构和功能的基本单位，细胞生物学成为生命科学的核心与汇聚点。\n\n【结论】\n细胞既是结构单位又是功能单位，是生命活动的基本单位。","kp":"ch01_s1_0"}],"calc":[],"term":[{"id":"ch01_term_6","modI":1,"term":"质膜(Plasma Membrane)","def":"①细胞表面具有选择透性的生物膜，由膜脂、蛋白质、糖类组成（定义）。②功能：屏障和半透膜，维护细胞内微环境相对稳定；细胞与外界进行物质、能量、信息交换（功能）。③进化意义：质膜的形成是非细胞生命(病毒)与细胞生物的重要分界点（意义）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)④进化意义(1分)","kp":"ch01_s1_0"},{"id":"ch01_term_8","modI":1,"term":"HeLa细胞系","def":"①1951年从黑人妇女Henrietta Lacks的宫颈癌细胞分离建立的人类细胞系（定义）。②是首例长期保存并运用至今的人类细胞系（意义）。③证明细胞在体外培养条件下仍可自我增殖和遗传（应用）。","kps":"踩分点:①定义(1分)②首例意义(2分)③体外增殖(1分)","kp":"ch01_s1_1"},{"id":"ch01_term_13","modI":1,"term":"细胞的基本性质","def":"①所有细胞共有的结构与功能特征（定义）。②结构共性：选择透性质膜、双链DNA、核糖体、相同化学元素(C/H/O/N/P/S)（结构）。③功能共性：新陈代谢(酶催化)、能量利用(来自太阳)、运动性、自我增殖和遗传（功能）。④是真核与原核细胞的共同点（意义）。","kps":"踩分点:①定义(1分)②结构共性(1分)③功能共性(2分)④共同点(1分)","kp":"ch01_s1_0"}]},{"i":2,"name":"模块三：原核细胞与真核细胞","slides":[{"i":0,"sec":"第三节 两类细胞","title":"两类基本细胞——原核与真核 (p19)","notes":"3. 两类基本细胞：原核细胞和真核细胞。细菌属于原核细胞，起源于35亿年前；原生生物、真菌、植物及动物均属于真核细胞，最早的真核细胞起源于15亿年前。原核与真核的分界是细胞生物学最重要的分类之一。","page":19,"level":"掌握","img":"assets/img/ch01/p019.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于原核细胞与真核细胞，下列说法正确的是（　）","o":["A. 细菌属于真核细胞","B. 最早的真核细胞起源于35亿年前","C. 细菌属于原核细胞，起源于35亿年前","D. 原核与真核的分界没有分类学意义"],"a":"C","e":"细菌属原核细胞，起源于约35亿年前；最早的真核细胞起源于约15亿年前，原核与真核的分界是最重要分类之一。","oe":["细菌属于原核细胞，不是真核细胞","35亿年前是原核细胞起源，真核约15亿年前","正确，细菌为原核，起源于约35亿年前","原核与真核分界是细胞生物学最重要分类之一"]},"cards":[{"front":"两类基本细胞是什么？各自起源时间如何？","back":"原核细胞和真核细胞；原核细胞起源于35亿年前；最早的真核细胞起源于15亿年前。","mnemonic":"原35，真15","type":"对比","useImg":false,"blank":"原核细胞","blank2":"真核细胞"},{"front":"细菌、原生生物、真菌、植物、动物分别属于哪类细胞？","back":"细菌属于原核细胞；原生生物、真菌、植物及动物均属于真核细胞。","mnemonic":"细菌原核，其余真核","type":"例证","useImg":false,"blank":"真核细胞","blank2":"原生生物"}],"mem":"原35，真15"},{"i":1,"sec":"第三节 两类细胞","title":"生命树三个分支 (p20)","notes":"Tree of life分成三个主要分支（三大类/域）：①古核生物(Archaea)；②细菌(Bacteria)；③真核生物(Eukarya)。古核细胞与细菌虽同属原核，但进化上分属不同分支，古核细胞更接近真核生物。","page":20,"level":"掌握","img":"assets/img/ch01/p020.jpg","anim":null,"fig":"生命三域树：古细菌、真细菌、真核生物。图显示三域的分支关系，真核生物与古细菌亲缘更近，说明原核与真核的分界。","points":null,"check":{"q":"生命树分成三个主要分支，它们是？","o":["A. 动物、植物、微生物","B. 古核生物、细菌、真核生物","C. 原核生物、真菌、病毒","D. 真细菌、蓝细菌、立克次氏体"],"a":"B","e":"生命树分为古核生物、细菌、真核生物三支，古核细胞在进化上更接近真核生物。","oe":["错：这是生物类群划分，非生命树分支","对：与笔记三域划分完全一致，与笔记原文相符","错：病毒不属细胞生物分支，不符合本页所学概念","错：三者均属细菌范围，不符合本页所学概念"],"basis":"Tree of life分成三个主要分支：古核生物、细菌、真核生物"},"cards":[{"front":"生命树分为哪三个主要分支？","back":"古核生物(Archaea)；细菌(Bacteria)；真核生物(Eukarya)。","mnemonic":"古、细、真","type":"组成数字","useImg":true,"blank":"真核生物","blank2":"古核生物"},{"front":"古核细胞与细菌、真核生物的进化关系如何？","back":"古核细胞与细菌同属原核，但进化上分属不同分支；古核细胞更接近真核生物。","mnemonic":"古核近真核","type":"对比","useImg":true,"blank":"古核细胞","blank2":"细菌"}],"mem":"古、细、真"},{"i":2,"sec":"第三节 两类细胞","title":"原核细胞的基本特点 (p22)","notes":"3.1 原核细胞：没有真正意义上的细胞核，没有核膜和核仁，只有拟核，进化地位较低。基本特点：①遗传信息量少(Most Bacteria and Archaea have 1000-4000 genes；人细胞含3×10^9核苷酸)；②内部结构简单，特别是没有分化为以膜为基础的专门结构和功能的细胞器及核膜。","page":22,"level":"掌握","img":"assets/img/ch01/p022.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于原核细胞的基本特点，下列叙述正确的是（　）","o":["A. 只有拟核，没有核膜和核仁","B. 具有真正的细胞核和核膜","C. 遗传信息量比人细胞多","D. 分化出以膜为基础的多种细胞器"],"a":"A","e":"原核细胞无核膜、无核仁，只有拟核，遗传信息量少，也没有以膜为基础分化的专门细胞器。","oe":["正确，原核只有拟核，没有核膜和核仁","原核无核膜，不具备真正意义的细胞核","原核遗传信息量少，远少于人的细胞","以膜为基础的细胞器是真核细胞的特征"]},"cards":[{"front":"原核细胞在细胞核方面有何基本特点？","back":"没有真正意义上的细胞核；没有核膜和核仁；只有拟核；进化地位较低。","mnemonic":"无核膜核仁，只有拟核","type":"定义","useImg":false,"blank":"拟核","blank2":"核膜和核仁"},{"front":"原核细胞的基本特点中，遗传信息量和内部结构如何？","back":"遗传信息量少，多数细菌和古菌有1000-4000个基因；内部结构简单，没有膜为基础的专门细胞器和核膜。","mnemonic":"基因少，结构简","type":"组成数字","useImg":false,"blank":"内部结构简单","blank2":"遗传信息量少"}],"mem":"无核膜核仁，只有拟核"},{"i":3,"sec":"第三节 两类细胞","title":"原核细胞两个亚门 (p23)","notes":"原核细胞分为两个亚门：①真细菌(含支原体)——日常生活中常见、致病或生活在土壤中，如支原体、蓝藻；已知最小的细胞是支原体(Mycoplasma)，仅0.1~0.3μm。②古细菌——通常出现在极端环境(浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管)，如产甲烷菌、硫氧化菌、盐生菌。","page":23,"level":"掌握","img":"assets/img/ch01/p023.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于原核细胞的两个亚门，下列说法正确的是（　）","o":["A. 支原体属于古细菌","B. 古细菌都生活在温和的正常环境","C. 已知最小的细胞是支原体，属于真细菌","D. 产甲烷菌属于真细菌"],"a":"C","e":"原核细胞分真细菌（含支原体，为已知最小细胞）和古细菌（多生活在极端环境，如产甲烷菌）。","oe":["支原体属于真细菌，并不是古细菌","古细菌多生活在极端环境，并非温和环境","正确，支原体是最小细胞，属真细菌","产甲烷菌属于古细菌，并不是真细菌"]},"cards":[{"front":"原核细胞分为哪两个亚门？","back":"真细菌(含支原体)；古细菌。","mnemonic":"真细菌、古细菌","type":"组成数字","useImg":false,"blank":"真细菌","blank2":"古细菌"},{"front":"已知最小的细胞是什么？大小多少？","back":"支原体(Mycoplasma)；仅0.1~0.3μm。","mnemonic":"最小支原体，0.1到0.3","type":"组成数字","useImg":false,"blank":"支原体","blank2":"0.1~0.3μm"},{"front":"古细菌通常出现在什么环境？举例说明。","back":"极端环境：浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管；如产甲烷菌、硫氧化菌、盐生菌。","mnemonic":"古菌爱极端","type":"例证","useImg":false,"blank":"极端环境","blank2":"产甲烷菌"}],"mem":"真细菌、古细菌"},{"i":4,"sec":"第三节 两类细胞","title":"真细菌与古细菌实例 (p24)","notes":"Eubacteria(细菌)如Lactococcus lactis(乳酸乳球菌，用于制作奶酪)；a mass of archaebacteria古细菌如Methanosarcina(产甲烷菌)，极端厌氧，利用CO2和H2合成甲烷产生能量，一些种群生长在牛胃中。","page":24,"level":"了解","img":"assets/img/ch01/p024.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于真细菌与古细菌的实例，下列说法正确的是（　）","o":["A. 乳酸乳球菌属于古细菌","B. 产甲烷菌属于真细菌","C. 乳酸乳球菌可用于制作奶酪","D. 产甲烷菌通过光合作用产生甲烷"],"a":"C","e":"乳酸乳球菌属真细菌，用于制作奶酪；产甲烷菌属古细菌，极端厌氧，利用CO2和H2合成甲烷。","oe":["乳酸乳球菌属真细菌，不是古细菌","产甲烷菌属于古细菌，并不是真细菌","正确，乳酸乳球菌可用于制作奶酪","产甲烷菌利用CO2和H2合成甲烷，非光合作用"]},"cards":null,"mem":"真细菌乳酸乳球菌；古细菌产甲烷嗜极端厌氧"},{"i":5,"sec":"第三节 两类细胞","title":"原核与真核的共同点 (p25)","notes":"3.2 原核细胞与真核细胞的共同点。功能上：都是生命的基本结构单位；都能进行分裂繁殖；都能遗传。结构上：都有细胞膜；都有DNA和RNA；都有核糖体。","page":25,"level":"掌握","img":"assets/img/ch01/p025.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列属于原核细胞与真核细胞共同点的是？","o":["A. 都有膜包被的细胞核","B. 都通过有丝分裂进行繁殖","C. 都有细胞膜、DNA和核糖体","D. 都含线粒体提供能量"],"a":"C","e":"两者结构上都有细胞膜、DNA和RNA以及核糖体，功能上都是生命的基本结构与繁殖单位。","oe":["错：原核细胞无核膜包被的核，不符合本页所学概念","错：原核为简单的无丝分裂，不符合本页所学概念","对：膜、DNA、核糖体为共有结构","错：原核细胞没有线粒体，不符合本页所学概念"],"basis":"都有细胞膜；都有DNA和RNA；都有核糖体"},"cards":[{"front":"原核细胞与真核细胞在功能上的共同点是什么？","back":"都是生命的基本结构单位；都能进行分裂繁殖；都能遗传。","mnemonic":"结构、繁殖、遗传","type":"对比","useImg":false,"blank":"分裂繁殖","blank2":"遗传"},{"front":"原核细胞与真核细胞在结构上的共同点是什么？","back":"都有细胞膜；都有DNA和RNA；都有核糖体。","mnemonic":"膜、核酸、核糖体","type":"对比","useImg":false,"blank":"核糖体","blank2":"细胞膜"}],"mem":"结构、繁殖、遗传"},{"i":6,"sec":"第三节 两类细胞","title":"不同特性——复杂性与基因物质 (p26-27)","notes":"(1)Complexity复杂性：原核细胞结构和功能极其简单，真核细胞复杂得多。(2)Genetic material基因物质：所有细胞都通过遗传密码(DNA)储存遗传信息。包装(packaging)：原核只有拟核区；真核有核膜包被的细胞核。原核无核膜→边转录边翻译；真核分室化、区域化(内膜系统)，分工精细——细胞核进行DNA复制、转录，成熟mRNA出核，细胞质进行蛋白质合成。","page":26,"level":"掌握","img":"assets/img/ch01/p026.jpg","anim":null,"fig":"原核与真核细胞的差异：①复杂性——原核简单、真核复杂；②遗传物质——原核无核膜、DNA 环状裸露，真核有核膜、DNA 与蛋白结合成染色体；③细胞质——真核有膜被细胞器；④分裂——原核二分裂，真核有丝分裂/减数分裂；⑤运动——鞭毛结构不同。","points":null,"check":{"q":"关于原核与真核细胞基因物质的比较，下列说法正确的是（　）","o":["A. 原核细胞转录和翻译在空间上完全分开","B. 真核细胞有核膜包被的细胞核，可边转录边翻译","C. 真核细胞没有内膜系统的区域化","D. 原核细胞无核膜，可边转录边翻译"],"a":"D","e":"原核无核膜，转录与翻译可同时进行；真核有核膜使核内转录、胞质翻译分区进行，具内膜系统区域化。","oe":["原核无核膜，转录翻译可同时进行，并未分开","真核核膜将转录与翻译分隔，不能边转录边翻译","真核具内膜系统，存在明显的区域化","正确，原核无核膜，故可边转录边翻译"]},"cards":[{"front":"原核细胞与真核细胞在基因物质包装和转录翻译上有何不同？","back":"原核只有拟核区，无核膜，边转录边翻译；真核有核膜包被的细胞核，分室化、区域化，核内复制转录，胞质翻译。","mnemonic":"原核边转边译，真核分室分工","type":"对比","useImg":false,"blank":"边转录边翻译","blank2":"拟核区"},{"front":"原核细胞与真核细胞在复杂性上有何差异？","back":"原核细胞结构和功能极其简单；真核细胞复杂得多。","mnemonic":"原简真繁","type":"对比","useImg":false,"blank":"简单","blank2":"真核细胞"}],"mem":"原核边转边译，真核分室分工"},{"i":7,"sec":"第三节 两类细胞","title":"遗传物质的形式与数量 (p28)","notes":"Form形式：真核细胞具有大量由DNA及蛋白质组成的染色体；原核细胞仅有一个单链、环状、'裸露'的DNA染色体。Amount数量：真核细胞含有的DNA/RNA远比原核多。原核细菌DNA长度0.25-3mm；最简单的真核细胞酵母4.6mm DNA，编码约6200个蛋白质；人的细胞核染色体DNA总长度达1m。","page":28,"level":"掌握","img":"assets/img/ch01/p028.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于原核与真核细胞遗传物质的形式与数量，下列说法正确的是（　）","o":["A. 真核细胞DNA与蛋白质组成染色体","B. 原核细胞具有多条线状染色体","C. 原核细胞DNA含量比真核细胞多","D. 酵母细胞编码约10万种蛋白质"],"a":"A","e":"真核DNA与蛋白质组成染色体；原核只有一个环状裸露DNA，DNA量少，酵母编码约6200种蛋白。","oe":["正确，真核细胞DNA与蛋白质组成染色体","原核为单个环状裸露DNA，并非多条线状","原核细胞DNA含量远少于真核细胞","酵母编码约6200种蛋白质，不是10万种"]},"cards":[{"front":"真核细胞与原核细胞的遗传物质形式有何不同？","back":"真核细胞具有大量由DNA及蛋白质组成的染色体；原核细胞仅有一个单链、环状、裸露的DNA染色体。","mnemonic":"真核染色体，原核裸环单","type":"对比","useImg":false,"blank":"染色体","blank2":"单链、环状、裸露的DNA染色体"},{"front":"真核细胞与原核细胞的DNA数量差异如何？举例说明。","back":"真核细胞含有的DNA/RNA远比原核多；原核细菌DNA长0.25-3mm；酵母4.6mm，编码约6200个蛋白质；人细胞核染色体DNA总长约1m。","mnemonic":"原核毫米级，真核米级","type":"组成数字","useImg":false,"blank":"DNA","blank2":"DNA/RNA"}],"mem":"真核染色体，原核裸环单"},{"i":8,"sec":"第三节 两类细胞","title":"细胞质、繁殖与运动 (p30)","notes":"(3)Cytoplasm细胞质：真核具有膜包被的细胞器及细胞骨架蛋白，原核都没有；两者都有核糖体但大小不同。(4)Cellular reproduction繁殖：真核是有丝分裂(mitosis)；原核是简单的(无丝)分裂(fission)。(5)Locomotion运动：真核具有细胞质运动及纤毛和鞭毛运动；原核虽有鞭毛，但蛋白组成、运动形式及机制不同。","page":30,"level":"掌握","img":"assets/img/ch01/p030.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于原核细胞与真核细胞的差异，下列叙述正确的是？","o":["A. 真核有膜包被的细胞器与细胞骨架，原核没有","B. 两者的核糖体大小完全相同","C. 原核细胞通过有丝分裂进行繁殖","D. 两者的鞭毛蛋白组成与运动机制相同"],"a":"A","e":"真核细胞具有膜包被的细胞器及细胞骨架蛋白，原核细胞都没有；繁殖与运动方式也各不相同。","oe":["对：笔记明确真核有而原核无，与笔记原文相符","错：两者核糖体大小不同，不符合本页所学概念","错：原核进行简单的无丝分裂，不符合本页所学概念","错：鞭毛蛋白组成与机制均不同，不符合本页所学概念"],"basis":"真核具有膜包被的细胞器及细胞骨架蛋白，原核都没有"},"cards":[{"front":"真核与原核细胞在细胞质结构上的核心区别是什么？","back":"真核有膜包被细胞器及细胞骨架蛋白；原核两者均无；两者都有核糖体但大小不同。","mnemonic":"真核有膜有骨架，原核只有小核糖体","type":"对比","useImg":false,"blank":"细胞骨架蛋白","blank2":"核糖体"},{"front":"真核与原核的繁殖方式和运动方式分别是什么？","back":"繁殖：真核有丝分裂，原核无丝分裂；运动：真核靠细胞质运动及纤毛鞭毛，原核鞭毛蛋白组成与机制不同。","mnemonic":"真核有丝，原核无丝；鞭毛同名不同源","type":"对比","useImg":false,"blank":"无丝分裂","blank2":"有丝分裂"}],"mem":"真核有膜有骨架，原核只有小核糖体"},{"i":9,"sec":"第三节 两类细胞","title":"原核与真核鞭毛的区别 (p31)","notes":"原核鞭毛：由单一蛋白flagellin(鞭毛蛋白)组成，如Salmonella(沙门氏菌)。真核鞭毛：'9+2'微管结构，由tubulin(微管蛋白)组成，马达蛋白dynein(动力蛋白)等，如人类精子鞭毛。两者在蛋白组成、运动形式及机制上完全不同——是趋同进化的经典例子。","page":31,"level":"掌握","img":"assets/img/ch01/p031.jpg","anim":null,"fig":"原核与真核鞭毛的区别：原核鞭毛由单一蛋白 flagellin 组成，靠旋转运动；真核鞭毛为“9+2”微管结构(tubulin)，靠 dynein 摆动。图对比两者结构。","points":null,"check":{"q":"关于原核细胞与真核细胞鞭毛的区别，下列说法正确的是（　）","o":["A. 两者都由微管蛋白组成","B. 真核鞭毛为“9+0”微管结构","C. 两者是趋同进化，结构完全相同","D. 原核鞭毛由单一蛋白鞭毛蛋白组成"],"a":"D","e":"原核鞭毛由单一蛋白flagellin组成；真核鞭毛为“9+2”微管结构，由微管蛋白与动力蛋白组成，二者是趋同进化。","oe":["真核鞭毛由微管蛋白组成，原核鞭毛不是","真核鞭毛是“9+2”结构，不是“9+0”","趋同进化说明结构来源不同，并非完全相同","正确，原核鞭毛由单一蛋白鞭毛蛋白组成"]},"cards":[{"front":"原核鞭毛与真核鞭毛在组成和结构上有何本质区别？","back":"原核：单一蛋白flagellin组成；真核：'9+2'微管结构，由tubulin组成，马达蛋白为dynein。","mnemonic":"原核一根蛋白丝，真核九加二微管","type":"对比","useImg":true,"blank":"flagellin","blank2":"微管结构"},{"front":"为什么说原核与真核鞭毛是趋同进化的经典例子？","back":"两者蛋白组成、运动形式及机制完全不同，却都实现运动功能，是功能相似但起源不同的趋同进化。","mnemonic":"同名不同源，功能相似是趋同","type":"例证","useImg":false,"blank":"趋同进化","blank2":"功能相似"}],"mem":"原核一根蛋白丝，真核九加二微管"},{"i":10,"sec":"第三节 两类细胞","title":"真核细胞的结构体系 (p32)","notes":"3.3 真核细胞的结构体系：①细胞骨架——由骨架蛋白组成、充满整个细胞的网络结构(细胞质骨架、细胞核骨架、细胞膜骨架)。首要作用是维持细胞形态，此外是细胞内物质运输的轨道、使基质区域化、帮助细胞移动。②生物膜体系——内部结构进一步分化：质膜、核膜、膜被细胞器(高尔基体、内质网、叶绿体、线粒体等)，实现细胞分室化、区域化。","page":32,"level":"掌握","img":"assets/img/ch01/p032.jpg","anim":null,"fig":"真核细胞的结构体系：①生物膜体系——质膜、核膜、膜被细胞器(ER、Golgi、溶酶体、线粒体、叶绿体等)；②细胞骨架——微丝、微管、中间纤维。图给出真核细胞的结构分区。","points":null,"check":{"q":"关于真核细胞的结构体系，下列说法正确的是（　）","o":["A. 细胞骨架的首要作用是维持细胞形态","B. 细胞骨架只存在于细胞质中","C. 生物膜体系与细胞分室化无关","D. 细胞骨架不能帮助细胞移动"],"a":"A","e":"真核细胞结构体系包括细胞骨架和生物膜体系；骨架首要作用是维持形态，还是运输轨道、使基质区域化并帮助细胞移动。","oe":["正确，骨架首要作用是维持细胞形态。","骨架包括细胞质、细胞核和细胞膜骨架。","生物膜体系实现细胞分室化、区域化。","细胞骨架能够帮助细胞移动，是其功能之一。"]},"cards":[{"front":"真核细胞结构体系中的细胞骨架由什么组成？首要作用是什么？","back":"由骨架蛋白组成的充满整个细胞的网络结构（细胞质骨架、核骨架、膜骨架）；首要作用是维持细胞形态。","mnemonic":"骨架撑形态，网络通运输","type":"组成","useImg":true,"blank":"细胞质骨架","blank2":"维持细胞形态"},{"front":"生物膜体系包括哪些结构？其核心意义是什么？","back":"包括质膜、核膜、膜被细胞器（高尔基体、内质网、叶绿体、线粒体等）；实现细胞分室化和区域化。","mnemonic":"膜系分房间，各室各司职","type":"组成","useImg":true,"blank":"细胞分室化","blank2":"质膜"}],"mem":"骨架撑形态，网络通运输"}],"mcq":[{"id":"ch01_mcq_13","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"秀丽隐杆线虫成体的体细胞数目是？","o":["A. 1090个","B. 959个","C. 131个","D. 6200个"],"a":"B","e":"线虫从受精卵产生1090个细胞，最终成体959个体细胞，其中131个发生凋亡。细胞命运精确可预测。","kp":"ch01_s2_0","oe":["1090是受精卵产生的细胞总数，非成体体细胞数。","线虫成体共有959个体细胞，数目精确可预测。","131是发育过程中发生凋亡的细胞数，非成体体细胞数。","6200与线虫成体体细胞数目不符。"]},{"id":"ch01_mcq_14","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"线虫相关的两次诺贝尔奖是？","o":["A. 细胞凋亡(2002)和RNAi(2006)","B. DNA复制和转录","C. 光合作用和呼吸","D. 酶学和免疫"],"a":"A","e":"线虫用于研究细胞凋亡(2002年诺贝尔奖)和RNA干扰RNAi(2006年诺贝尔奖)。","kp":null,"oe":["线虫凋亡研究获2002年、RNAi研究获2006年诺贝尔奖。","DNA复制和转录研究与线虫两次诺奖无关。","光合作用和呼吸研究与线虫诺奖项目无关。","酶学和免疫研究与线虫诺奖项目不符。"]},{"id":"ch01_mcq_15","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"控制果蝇和脊椎动物眼发育的同源基因是？","o":["A. eyeless与Pax6","B. Kit与Pax6","C. Cdc2与eyeless","D. p53与Rb"],"a":"A","e":"果蝇eyeless与脊椎动物Pax6是直系同源基因，源自同一祖先基因，控制眼睛发育。","kp":"ch01_s2_6","oe":["果蝇eyeless与脊椎动物Pax6为控制眼发育的直系同源基因。","Kit与色素细胞发育有关，并非控制眼发育的同源基因。","Cdc2与细胞周期相关，eyeless与眼发育相关，二者不配对。","p53与Rb为抑癌基因，不是控制眼发育的同源基因。"]},{"id":"ch01_mcq_16","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"人类Pax6功能不足会导致？","o":["A. 白化病","B. 无虹膜症(aniridia)","C. 镰刀型贫血","D. 色盲"],"a":"B","e":"人Pax6功能不足患遗传病aniridia(无虹膜症)；果蝇eyeless失活则缺眼。同一基因控制眼发育。","kp":"ch01_s2_2","oe":["白化病与酪氨酸酶等基因缺陷有关，与Pax6无关。","人Pax6功能不足导致无虹膜症(aniridia)。","镰刀型贫血由血红蛋白基因突变引起，与Pax6无关。","色盲与视色素基因缺陷相关，并非Pax6所致。"]},{"id":"ch01_mcq_17","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"人鼠相似白斑(Kit基因突变)说明了？","o":["A. 两者无关","B. 同一基因突变造成相同的遗传疾病,人鼠基因高度相似","C. 只有人有Kit","D. 小鼠没有色素细胞"],"a":"B","e":"人婴儿和小鼠额头相似白斑，因同一基因Kit突变，证明人鼠基因与发育机制高度相似。","kp":"ch01_s2_6","oe":["人鼠因同源Kit基因突变出现相似白斑，关系密切。","同一Kit基因突变致相似白斑，说明人鼠基因高度相似。","小鼠同样具有Kit基因，并非只有人才有。","小鼠有黑色素细胞，Kit突变影响其发育，并非没有。"]},{"id":"ch01_mcq_18","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"斑马鱼作为模式生物的特点不包括？","o":["A. 胚胎透明","B. 基因与人类相似度87%","C. 世代时间仅约3个月","D. 是无脊椎动物"],"a":"D","e":"斑马鱼是模式脊椎动物(非无脊椎)。特点：胚胎透明、基因与人类87%相似、世代约3个月。","kp":"ch01_s2_2","oe":["胚胎透明是斑马鱼作为模式生物的特点之一。","基因与人类相似度达87%是其特点之一。","世代时间仅约3个月是其特点之一。","斑马鱼是脊椎动物，本项称其无脊椎，说法错误，为答案。"]},{"id":"ch01_mcq_19","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"酵母与人类细胞周期蛋白的相似性说明了？","o":["A. 酵母是原核生物","B. 细胞周期调控机制在进化上高度保守","C. 人类没有Cdc2","D. 两者无同源蛋白"],"a":"B","e":"人Cdc2与裂殖酵母63%、与芽殖酵母58%相同→细胞周期调控从酵母到人高度保守。","kp":"ch01_s2_8","oe":["酵母是真核生物，并非原核生物。","人Cdc2与酵母同源，说明细胞周期调控在进化上高度保守。","人类存在Cdc2，与酵母细胞周期蛋白同源。","两者存在同源细胞周期蛋白，并非无同源蛋白。"]}],"judge":[{"id":"ch01_judge_4","modI":2,"q":"原核细胞没有核膜和核仁，只有拟核，且没有膜被细胞器和细胞骨架。","a":"对","e":"原核细胞无核膜核仁、无膜被细胞器与细胞骨架，DNA为单链环状裸露；这是与真核细胞的根本区别之一。","kp":"ch01_s2_2","oe":["原核细胞无核膜核仁，仅有拟核，且无膜被细胞器与细胞骨架，故正确。","误以为原核细胞有核糖体外的膜被细胞器或有细胞骨架，从而判错。"]},{"id":"ch01_judge_5","modI":2,"q":"支原体是已知最小的细胞，也是唯一没有细胞壁的原核细胞。","a":"对","e":"支原体直径仅0.1~0.3μm，是最小、最简单的原核细胞，也是唯一无细胞壁的原核细胞。","kp":"ch01_s2_3","oe":["支原体直径0.1~0.3μm，是最小、最简单的原核细胞，且唯一无细胞壁。","误以为所有原核细胞都有细胞壁，或把最小细胞记成衣原体，故判错。"]},{"id":"ch01_judge_6","modI":2,"q":"真核细胞与原核细胞的鞭毛结构相同，都由微管蛋白(tubulin)组成。","a":"错","e":"原核鞭毛由单一蛋白flagellin组成；真核鞭毛为“9+2”微管结构(tubulin+dynein)，二者不同。","kp":"ch01_s2_9","oe":["若以为鞭毛均含微管蛋白则判对，混淆了原核与真核鞭毛的组成。","原核鞭毛由flagellin组成，真核鞭毛为9+2微管(tubulin)结构。"]},{"id":"ch01_judge_7","modI":2,"q":"古细菌在系统发育上既不属于真核生物，也不属于真细菌，是一类特殊细菌。","a":"对","e":"古细菌具有原核与真核的混合特征及独有特征，被认为代表第三界生物。","kp":"ch01_s2_4","oe":["古细菌兼具原核与真核特征并有独有特征，系统发育上独立，代表第三界生物。","误以为古细菌属于真细菌，忽略其与真细菌的系统发育差异，故判错。"]}],"fill":[{"id":"ch01_fill_5","modI":2,"q":"原核细胞没有真正的细胞核，只有________；遗传信息量少，一般含________个基因。","a":"拟核,1000-4000","kp":"ch01_s2_2","oe":["原核细胞无真正细胞核，只有无膜包裹的拟核区域含DNA。","原核细胞遗传信息量少，一般含1000~4000个基因。"]},{"id":"ch01_fill_6","modI":2,"q":"原核细胞分为两个亚门：________和________；已知最小的细胞是________(0.1~0.3μm)。","a":"真细菌,古细菌,支原体(Mycoplasma)","kp":"ch01_s2_3","oe":["原核细胞分为真细菌和古细菌两个亚门，二者在遗传与代谢上有别。","古细菌是另一亚门，多生活在极端环境，细胞壁组成与真细菌不同。","支原体是最小的细胞，直径约0.1~0.3μm，且无细胞壁。"]},{"id":"ch01_fill_7","modI":2,"q":"真核细胞遗传物质由________和蛋白质组成染色体；原核仅一个________、________的DNA染色体。","a":"DNA,单链,环状裸露","kp":"ch01_s2_7","oe":["真核细胞遗传物质是DNA，与组蛋白等蛋白质结合形成染色体。","原核细胞仅一个DNA染色体，按教材表述为单链，信息量远少于真核。","该DNA呈环状、裸露，不与蛋白质结合，集中于拟核区。"]},{"id":"ch01_fill_8","modI":2,"q":"原核细胞进行________(无丝)分裂；真核细胞进行________。","a":"简单,有丝分裂","kp":"ch01_s2_0","oe":["原核细胞以简单(无丝)分裂方式增殖，无纺锤体和核膜变化。","真核细胞主要进行有丝分裂，保证遗传物质均等分配到子细胞。"]}],"short":[{"id":"ch01_short_2","modI":2,"q":"比较原核细胞与真核细胞的主要区别。","a":"原核细胞 vs 真核细胞：\n\n①细胞核：原核无核膜核仁，只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核仅一个单链、环状、裸露DNA染色体，遗传信息量少(1000-4000基因)；真核有大量由DNA和蛋白质组成的染色体，DNA/RNA多得多(人DNA总长1m)。\n③转录翻译：原核无核膜→边转录边翻译；真核分室化→核内复制转录、胞质翻译。\n④细胞器：原核无膜被细胞器；真核有膜被细胞器(内质网、高尔基体、线粒体、叶绿体等)。\n⑤细胞骨架：原核无；真核有细胞骨架(细胞质骨架/核骨架/膜骨架)。\n⑥分裂：原核简单(无丝)分裂；真核有丝分裂。\n⑦鞭毛：原核由flagellin组成；真核为9+2微管(tubulin+dynein)。\n⑧大小：原核小(支原体0.1~0.3μm)；真核大而复杂。\n\n【共同点】都有细胞膜、DNA和RNA、核糖体；都是生命基本结构单位、能分裂繁殖和遗传。","kp":"ch01_s2_0"},{"id":"ch01_short_4","modI":2,"q":"简述真核细胞的结构体系及其意义。","a":"真核细胞的结构体系：\n\n【生物膜体系】\n质膜、核膜、膜被细胞器(高尔基体、内质网、叶绿体、线粒体等)，实现细胞分室化、区域化。\n意义：核内进行DNA复制、转录，成熟mRNA出核，细胞质进行蛋白质合成——分工更精细、效率更高。\n\n【细胞骨架体系】\n由相关骨架蛋白组成的充满整个细胞的网络结构，包括细胞质骨架、细胞核骨架、细胞膜骨架。\n功能：①维持细胞的一定形态；②细胞内物质运输的轨道；③使细胞内基质区域化；④帮助细胞移动或行走。\n\n【意义】\n生物膜体系与细胞骨架体系共同支撑真核细胞高度分化的结构与功能，是真核细胞比原核细胞复杂得多的根本原因。","kp":"ch01_s2_10"}],"calc":[{"id":"ch01_calc_2","modI":2,"q":"论述原核细胞与真核细胞的分界为何是细胞生物学最重要的分类之一。","a":"原核/真核的分界反映了细胞结构与进化水平的根本差异","steps":"【结构差异】\n①核：原核无核膜核仁只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核单链环状裸露DNA；真核DNA+蛋白组成染色体。\n③细胞器：原核无膜被细胞器；真核有内膜系统(内质网/高尔基/线粒体/叶绿体等)。\n④细胞骨架：原核无；真核有。\n⑤转录翻译：原核边转录边翻译；真核分室化(核内转录、胞质翻译)。\n\n【进化意义】\n①原核细胞起源于35亿年前；真核细胞起源于15亿年前；\n②生命树分三支：古细菌、细菌、真核生物——古细菌更接近真核；\n③内膜系统的形成是真核细胞由低等到高等发展的反映。\n\n【功能意义】\n①分室化使真核细胞分工精细、效率高，能支持更大更复杂的细胞；\n②原核细胞结构简单、遗传信息量少(1000-4000基因)，但繁殖快、适应性强。\n\n【结论】\n原核/真核的分界是理解细胞结构、功能、进化、疾病的基础，故为最重要的分类之一。","kp":"ch01_s2_0"}],"term":[{"id":"ch01_term_2","modI":2,"term":"原核细胞(Prokaryotic Cell)","def":"①没有真正细胞核(无核膜核仁，只有拟核)的细胞，进化地位较低（定义）。②特点：遗传信息量少(1000-4000基因)；内部结构简单，无膜被细胞器和细胞骨架；DNA为单链环状裸露；边转录边翻译；简单分裂；鞭毛由flagellin组成（特点）。③分为真细菌和古细菌两个亚门；代表：细菌、蓝藻、支原体(最小细胞0.1~0.3μm)、产甲烷菌（分类）。","kps":"踩分点:①定义(1分)②特点(2分)③分类/代表(1分)","kp":"ch01_s2_2"},{"id":"ch01_term_3","modI":2,"term":"真核细胞(Eukaryotic Cell)","def":"①具有核膜包被的细胞核和膜被细胞器的细胞（定义）。②特点：有细胞核、大量DNA-蛋白染色体、内膜系统(分室化)、细胞骨架；核内复制转录、胞质翻译；有丝分裂；鞭毛为9+2微管结构(tubulin+dynein)（特点）。③代表：原生生物、真菌、植物、动物；最早真核细胞起源于15亿年前（分类）。","kps":"踩分点:①定义(1分)②特点(2分)③分类(1分)","kp":"ch01_s2_10"},{"id":"ch01_term_5","modI":2,"term":"细胞骨架(Cytoskeleton)","def":"①由相关骨架蛋白组成的、充满整个细胞的网络结构（定义）。②包括细胞质骨架、细胞核骨架、细胞膜骨架（组成）。③功能：维持细胞形态；细胞内物质运输的轨道；使基质区域化；帮助细胞移动或行走（功能）。④是真核细胞特有的结构（意义）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(2分)④真核特有(1分)","kp":"ch01_s2_8"},{"id":"ch01_term_7","modI":2,"term":"细胞分室化(Compartmentalization)","def":"①真核细胞内由生物膜体系将细胞分成不同区域/细胞器的现象（定义）。②基础：内膜系统(质膜、核膜、膜被细胞器)（基础）。③意义：DNA复制、转录在核内进行，成熟mRNA出核，蛋白质合成在细胞质进行——分工精细、效率高（意义）。","kps":"踩分点:①定义(1分)②基础(1分)③意义(2分)","kp":"ch01_s2_6"},{"id":"ch01_term_9","modI":2,"term":"支原体(Mycoplasma)","def":"①已知最小的细胞，直径仅0.1~0.3μm（定义）。②属真细菌（分类）。③无细胞壁，是研究最小生命单位与细胞膜结构的模型（意义）。","kps":"踩分点:①定义(1分)②大小(1分)③分类(1分)④意义(1分)","kp":"ch01_s2_3"},{"id":"ch01_term_10","modI":2,"term":"古细菌(Archaebacteria)","def":"①古核细胞(古核生物)，与原核细胞、真核生物并列为三大类，通常生活在极端环境（定义）。②环境：浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管（环境）。③代表：产甲烷菌(利用CO2+H2合成甲烷)、硫氧化菌、盐生菌（举例）。④进化上更接近真核生物（意义）。","kps":"踩分点:①定义(1分)②环境(1分)③举例(1分)④进化地位(1分)","kp":"ch01_s2_4"},{"id":"ch01_term_14","modI":2,"term":"生命树的三分支","def":"①将生物划分为三个主要分支的进化树（定义）。②分支：古核生物(Archaea)、细菌(Bacteria)、真核生物(Eukarya)（三大类/域）。③意义：古核细胞与细菌虽同属原核，但进化上分属不同分支，古核细胞更接近真核生物（意义）。","kps":"踩分点:①定义(1分)②三支(2分)③进化意义(2分)","kp":"ch01_s2_1"}]},{"i":3,"name":"模块四：模式生物","slides":[{"i":0,"sec":"第四节 模式生物","title":"模式材料总论 (p34)","notes":"4. 模式生物(model organisms)：①由共同祖先进化而来；②一些重要功能的基因在进化上高度保守，不论细胞水平还是分子水平，不同生物间都遵循共同规律；③用较易研究的生物做模型研究其基因和生物功能，获得的信息可应用于其它较难研究的生物。常用模式生物：大肠杆菌、酵母、拟南芥、线虫、果蝇、小鼠、斑马鱼。","page":34,"level":"掌握","img":"assets/img/ch01/p034.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于模式生物，下列说法正确的是（　）","o":["A. 模式生物之间没有共同祖先","B. 模式生物研究结果不能推广到其他生物","C. 重要功能基因在进化上高度保守","D. 只有细菌才能作为模式生物"],"a":"C","e":"模式生物由共同祖先进化而来，重要功能基因在进化上高度保守，其研究结果可推广到较难研究的生物。","oe":["模式生物都是由共同祖先进化而来的","研究结果可应用于其他较难研究的生物","正确，重要功能基因在进化上高度保守","常用模式生物还包括酵母、线虫、小鼠等"]},"cards":[{"front":"什么是模式生物？选择模式生物的依据有哪些？","back":"由共同祖先进化而来；重要功能基因进化上高度保守；用易研究的生物做模型，信息可推广到难研究的生物。","mnemonic":"共同祖先、基因保守、以易推难","type":"定义","useImg":false,"blank":"重要功能基因进化上高度保守","blank2":"共同祖先进化而来"},{"front":"常用的模式生物有哪些？","back":"大肠杆菌、酵母、拟南芥、线虫、果蝇、小鼠、斑马鱼。","mnemonic":"大肠酵母拟南芥，线虫果蝇鼠斑马","type":"例证","useImg":false,"blank":"大肠杆菌","blank2":"酵母"}],"mem":"共同祖先、基因保守、以易推难"},{"i":1,"sec":"第四节 模式生物","title":"大肠杆菌 (p35)","notes":"大肠杆菌(Escherichia coli)：①易培养、繁殖快，营养充足时20-30min繁殖一代，大规模培养成本低；②DNA分子简单，基因组1997年测序完毕，约4288个基因，遗传背景清楚(人类细胞DNA量是其600倍，编码5-10万种蛋白)；③表达水平通常较真核高，外源基因表达量可达总蛋白5%-30%，常用作蛋白质表达系统。细胞基本分子生物学(DNA复制、转录、翻译机制)最初都在它上面阐明。","page":35,"level":"掌握","img":"assets/img/ch01/p035.jpg","anim":null,"fig":"大肠杆菌(E. coli)作为模式生物：繁殖快(20–30min 一代)、基因组小(4.6Mb)、遗传背景清楚。图显示其结构。是分子生物学研究的基础材料。","points":null,"check":{"q":"关于大肠杆菌作为模式生物的特点，下列说法正确的是（　）","o":["A. 营养充足时约20-30分钟繁殖一代","B. 基因组约4288个基因，比人类DNA量大","C. 只能用于蛋白质表达，不能研究DNA复制","D. 其DNA量约为人类细胞的600倍"],"a":"A","e":"大肠杆菌繁殖快，约20-30min一代；基因组约4288个基因，DNA量仅为人类的1/600；DNA复制、转录、翻译机制最初在其上阐明。","oe":["正确，营养充足时20-30分钟繁殖一代","其基因组约4288个基因，DNA量远小于人类","DNA复制、转录、翻译机制最初在其上阐明","人类DNA量约是其600倍，而非相反"]},"cards":[{"front":"大肠杆菌作为模式生物有哪些优势？","back":"易培养繁殖快（20-30min一代）；基因组简单约4288个基因，1997年测序完成；外源基因表达量可达总蛋白5%-30%。","mnemonic":"快繁简基因组，高表达好工具","type":"例证","useImg":false,"blank":"基因组简单","blank2":"外源基因表达量可达总蛋白5%-30%"},{"front":"为什么说大肠杆菌是分子生物学研究的奠基模式生物？","back":"DNA复制、转录、翻译等基本分子机制最初都在大肠杆菌中阐明。","mnemonic":"分子机制先在大肠杆菌讲清楚","type":"功能","useImg":false,"blank":"大肠杆菌","blank2":"DNA复制"}],"mem":"快繁简基因组，高表达好工具"},{"i":2,"sec":"第四节 模式生物","title":"啤酒酵母 (p36)","notes":"啤酒酵母(Saccharomyces cerevisiae)/芽殖酵母：最小的真核模式生物，核中DNA量仅为大肠杆菌的2.5倍。①含大量与人细胞同源的蛋白，通常有保守功能；②基因组小，编码约6200个蛋白质，1996年完整基因组公布；③2种生活形态，单倍体、二倍体均能生长，利于基因功能研究；④具所有基因相应突变体，用于研究细胞分裂周期调控、细胞凋亡等。","page":36,"level":"掌握","img":"assets/img/ch01/p036.jpg","anim":null,"fig":"酿酒酵母(Saccharomyces cerevisiae)作为模式生物：单细胞真核生物、基因组小(12Mb)、有与人类同源的蛋白、可进行遗传操作。图显示其出芽生殖。是研究真核细胞周期、蛋白功能的好材料。","points":null,"check":{"q":"关于啤酒酵母作为模式生物，下列说法正确的是（　）","o":["A. 几乎不含与人细胞同源的蛋白","B. 其核中DNA量约为大肠杆菌的25倍","C. 只以二倍体形态生长","D. 基因组编码约6200个蛋白质，1996年完整基因组公布"],"a":"D","e":"啤酒酵母是最小真核模式生物，核DNA仅为大肠杆菌的2.5倍，含大量与人同源蛋白，编码约6200个蛋白，1996年公布全基因组。","oe":["含大量与人细胞同源的保守功能蛋白。","核DNA量仅为大肠杆菌的2.5倍，而非25倍。","啤酒酵母单倍体和二倍体均能生长，利于研究。","正确，编码约6200个蛋白并于1996年公布基因组。"]},"cards":[{"front":"啤酒酵母作为模式生物的核心优势有哪些？","back":"最小真核模式生物；含大量与人同源蛋白；基因组小约6200个蛋白，1996年公布；单倍体二倍体均可生长；具所有基因突变体。","mnemonic":"最小真核，同源人多，突变体全","type":"例证","useImg":false,"blank":"最小真核模式生物","blank2":"含大量与人同源蛋白"},{"front":"啤酒酵母常用于研究哪些细胞过程？","back":"细胞分裂周期调控、细胞凋亡等。","mnemonic":"酵母管周期，凋亡也拿手","type":"功能","useImg":false,"blank":"细胞分裂周期调控","blank2":"细胞凋亡"}],"mem":"最小真核，同源人多，突变体全"},{"i":3,"sec":"第四节 模式生物","title":"酵母与人类周期蛋白相似 (p37)","notes":"酵母细胞和人类细胞周期相关蛋白在氨基酸序列上非常相似：人类Cdc2与裂殖酵母S.pombe氨基酸相同序列63%；与芽殖酵母的58%相同。说明细胞周期调控机制从酵母到人在进化上高度保守。","page":37,"level":"理解","img":"assets/img/ch01/p037.jpg","anim":null,"fig":null,"points":null,"check":{"q":"人类Cdc2与酵母细胞周期相关蛋白的氨基酸序列高度相似，这说明？","o":["A. 人类与酵母的亲缘关系最近","B. 细胞周期蛋白仅存在于酵母中","C. 人类与酵母的基因完全相同","D. 细胞周期调控机制在进化上高度保守"],"a":"D","e":"人Cdc2与酵母周期蛋白序列高度相似，说明细胞周期调控机制从酵母到人在进化上高度保守。","oe":["错：序列相似不等于亲缘关系最近","错：人类细胞同样含相关周期蛋白","错：高度相似并非完全相同，不符合本页所学概念","对：笔记据此得出调控机制高度保守"],"basis":"细胞周期调控机制从酵母到人在进化上高度保守"},"cards":null,"mem":"Cdc2人-裂殖酵母63%、芽殖58%同源：周期保守"},{"i":4,"sec":"第四节 模式生物","title":"拟南芥 (p38)","notes":"拟南芥(Arabidopsis thaliana)：从30万种植物中选出，十字花科。①每个细胞的DNA量只有酵母细胞的3-4倍，8-10周产生大量后代，生长无明显季节性，快速繁殖；②基因组异常小(1.2亿碱基对)，单倍体染色体数目5条，线粒体和叶绿体基因组也完成测序，是被子植物中第一个完成全基因组测定的植物；③世代时间短、种子产量大、株高仅约30cm；④用于遗传筛选鉴定几乎植物生命每一方面的基因。","page":38,"level":"掌握","img":"assets/img/ch01/p038.jpg","anim":null,"fig":"拟南芥(Arabidopsis thaliana)作为模式植物：基因组小(125Mb)、世代短、易遗传转化。图显示其植株。是植物分子遗传学的模式生物。","points":null,"check":{"q":"关于拟南芥作为模式植物，下列说法正确的是（　）","o":["A. 生长具有明显的季节性","B. 单倍体染色体数目为10条","C. 基因组约含12亿碱基对","D. 是被子植物中第一个完成全基因组测定的植物"],"a":"D","e":"拟南芥基因组异常小(1.2亿碱基对)，单倍体染色体5条，是被子植物中首个完成全基因组测定的植物，世代短且无明显季节性。","oe":["拟南芥生长无明显季节性，可快速繁育后代。","单倍体染色体数目为5条，而非10条。","基因组约1.2亿碱基对，不是12亿。","正确，首个完成全基因组测定的被子植物。"]},"cards":[{"front":"拟南芥作为模式植物的优势有哪些？","back":"DNA量小（酵母3-4倍）；8-10周产生大量后代；基因组仅1.2亿碱基对，5条染色体；首个完成全基因组测定的被子植物。","mnemonic":"小基因组短世代，首测序的被子植物","type":"例证","useImg":false,"blank":"首个完成全基因组测定的被子植物","blank2":"5条染色体"},{"front":"拟南芥在植物学研究中的主要用途是什么？","back":"用于遗传筛选鉴定几乎植物生命每一方面的基因。","mnemonic":"拟南芥筛遍植物生命各面","type":"功能","useImg":false,"blank":"遗传筛选","blank2":"基因"}],"mem":"小基因组短世代，首测序的被子植物"},{"i":5,"sec":"第四节 模式生物","title":"秀丽隐杆线虫 (p39)","notes":"秀丽隐杆线虫(Caenorhabditis elegans)：①发育中从一个受精卵总共产生1090个细胞，最终成体只有959个体细胞，其中131个细胞在发育过程中发生细胞凋亡；②精确地从受精卵发育成正好有959个体细胞的成虫，细胞按可预设的严密规律分裂、分化、凋亡；③体壁透明，显微镜下不用染色即可观察体内器官；④世代时间短(25℃下胚胎发育成成虫约2.5天，寿命2-3周)，便于遗传分析。线虫中调控细胞程序化死亡的基因都能在哺乳动物中找到同源基因并以类似方式调节凋亡——凋亡机制从线虫到人类都保守。","page":39,"level":"掌握","img":"assets/img/ch01/p039.jpg","anim":null,"fig":"秀丽隐杆线虫(C. elegans)作为模式生物：成体 959 个体细胞、透明、世代短(3 天)、可追踪每个细胞的发育命运。图显示其结构。是研究细胞凋亡和发育的经典材料。","points":null,"check":{"q":"关于秀丽隐杆线虫，下列说法正确的是（　）","o":["A. 成体共有1090个体细胞","B. 发育中131个细胞发生凋亡，成体959个体细胞","C. 体壁不透明，须染色才能观察","D. 世代时间长，不利于遗传分析"],"a":"B","e":"线虫从受精卵产生1090个细胞，其中131个凋亡，成体959个体细胞；体壁透明，世代时间短，利于遗传分析。","oe":["1090个是产生的细胞数，成体为959个","正确，131个细胞凋亡，成体959个","线虫体壁透明，无需染色即可观察","线虫世代时间短，便于进行遗传分析"]},"cards":[{"front":"秀丽隐杆线虫发育中细胞数量有何特点？","back":"从受精卵共产生1090个细胞，成体仅959个体细胞，其中131个细胞发生凋亡。","mnemonic":"1090生，959留，131凋亡","type":"组成数字","useImg":false,"blank":"凋亡","blank2":"受精卵"},{"front":"线虫作为模式生物的优势及其对凋亡研究的意义是什么？","back":"体壁透明可活体观察；世代短（25℃约2.5天）；凋亡调控基因在哺乳动物中有同源基因且机制保守。","mnemonic":"透明短世代，凋亡从虫到人保守","type":"例证","useImg":false,"blank":"体壁透明可活体观察","blank2":"世代短"}],"mem":"1090生，959留，131凋亡"},{"i":6,"sec":"第四节 模式生物","title":"线虫与两次诺贝尔奖 (p40)","notes":"线虫(C. elegans)的贡献：细胞凋亡(programmed cell death)——2002年诺贝尔生理学或医学奖；RNAi(RNA干扰)——2006年诺贝尔奖。显示模式生物对重大发现的推动作用。","page":40,"level":"了解","img":"assets/img/ch01/p040.jpg","anim":null,"fig":null,"points":null,"check":{"q":"以线虫(C. elegans)为模式生物取得的重要发现包括？","o":["A. DNA双螺旋结构与半保留复制","B. 细胞凋亡与RNA干扰","C. 血液循环与免疫排斥","D. 细胞学说与原生质理论"],"a":"B","e":"线虫作为模式生物推动了细胞凋亡(程序性细胞死亡)和RNA干扰两项重大发现。","oe":["错：DNA结构研究并非线虫模型贡献","对：笔记所列线虫贡献即凋亡与RNAi","错：与线虫模式生物研究无关，不符合本页所学概念","错：细胞学说早于线虫模型建立，不符合本页所学概念"],"basis":"线虫…细胞凋亡…RNAi"},"cards":null,"mem":"线虫两诺奖：凋亡2002、RNAi 2006"},{"i":7,"sec":"第四节 模式生物","title":"线虫基因组 (p41)","notes":"A Worm's Life：线虫基因组测序完毕，全长9.7×10^4 Kb(约9700万碱基对)，约19000个基因。绝大多数线虫个体较小，体长一般不超过2.5mm，多数在1mm左右。","page":41,"level":"了解","img":"assets/img/ch01/p041.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于线虫基因组，下列说法正确的是（　）","o":["A. 约含1900个基因","B. 体长一般超过2.5mm","C. 全长约9700万碱基对，约19000个基因","D. 全长约9.7万碱基对"],"a":"C","e":"线虫基因组约9.7×10^4 Kb(9700万碱基对)，约19000个基因；个体较小，体长一般不超过2.5mm。","oe":["约含19000个基因，而非1900个。","线虫个体较小，体长一般不超过2.5mm。","正确，约9700万碱基对、19000个基因。","9.7×10^4 Kb即9700万碱基对，非9.7万。"]},"cards":null,"mem":"线虫基因组9700万bp，约1.9万基因，体长约1mm"},{"i":8,"sec":"第四节 模式生物","title":"线虫细胞分化谱系 (p43)","notes":"线虫细胞分化谱系示意图：展示从受精卵到959个体细胞的精确、可预测的分裂分化路径，是研究细胞命运决定与程序性死亡的经典模型。","page":43,"level":"了解","img":"assets/img/ch01/p043.jpg","anim":null,"fig":"线虫细胞分化谱系示意图：从受精卵到成体，每个细胞的来源和命运都被精确追踪。图显示 1090 个细胞中有 131 个凋亡。说明“细胞命运可追踪”。","points":null,"check":{"q":"线虫细胞分化谱系示意图说明（　）","o":["A. 细胞分裂分化随机进行","B. 成体体细胞数远多于产生数","C. 该谱系不能用于研究程序性死亡","D. 从受精卵到959个体细胞的分裂路径精确可预测"],"a":"D","e":"线虫从受精卵到959个体细胞的分裂分化路径精确可预测，是研究细胞命运决定与程序性死亡的经典模型。","oe":["分裂分化按严密规律进行，并非随机","成体959个少于产生的1090个","该谱系正是研究程序性死亡的经典模型","正确，该分裂分化路径精确且可预测"]},"cards":null,"mem":"线虫谱系：受精卵→959体细胞，精确可预测"},{"i":9,"sec":"第四节 模式生物","title":"果蝇 (p44)","notes":"果蝇(Drosophila melanogaster)黑腹果蝇/fruit fly：基因组测序完毕，全长1.8×10^5 Kb，约13600个基因。研究胚胎发育及幼虫发育中的遗传机制——单个受精卵如何调控分化、发育成由多种细胞类型组成的多细胞生物个体(发育生物学)。最早用于发现染色体特性，在鉴定控制胚胎发育的基因方面尤其有价值。","page":44,"level":"掌握","img":"assets/img/ch01/p044.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于黑腹果蝇，下列说法正确的是（　）","o":["A. 最早用于发现细胞膜的流动性","B. 基因组全长约1.8×10^5 Kb，约13600个基因","C. 基因组约13600 Kb","D. 对研究胚胎发育遗传机制没有价值"],"a":"B","e":"黑腹果蝇基因组测序完成，全长1.8×10^5 Kb，约13600个基因，最早用于发现染色体特性，在鉴定胚胎发育基因方面尤其有价值。","oe":["最早用于发现染色体特性，非膜流动性。","正确，全长1.8×10^5 Kb、约13600个基因。","全长1.8×10^5 Kb，而非13600 Kb。","对研究胚胎发育遗传机制极具价值。"]},"cards":[{"front":"果蝇作为模式生物的核心优势是什么？","back":"基因组已测序：1.8×10^5 Kb，约13600个基因；最早用于发现染色体特性；在鉴定控制胚胎发育的基因方面尤其有价值","mnemonic":"果蝇小，基因少，染色体先发现，发育基因它最灵","type":"功能","useImg":false,"blank":"最早用于发现染色体特性","blank2":"约13600个基因"},{"front":"果蝇主要用于研究什么生物学问题？","back":"胚胎发育及幼虫发育中的遗传机制；单个受精卵如何调控分化、发育成多细胞生物个体（发育生物学）","mnemonic":"一卵变多细胞，果蝇帮你找基因","type":"功能","useImg":false,"blank":"胚胎发育","blank2":"发育生物学"}],"mem":"果蝇小，基因少，染色体先发现，发育基因它最灵"},{"i":10,"sec":"第四节 模式生物","title":"控制眼形成的基因 (p45)","notes":"无脊椎动物和脊椎动物中控制眼形成的主要基因：eyeless(果蝇)与Pax6(脊椎动物)。两者是直系同源基因，控制眼睛发育。","page":45,"level":"理解","img":"assets/img/ch01/p045.jpg","anim":null,"fig":null,"points":null,"check":{"q":"控制眼形成的主要基因中，果蝇与脊椎动物的对应基因分别是（　）","o":["A. eyeless与Pax6","B. Pax6与eyeless","C. eyeless与Sox2","D. Pax6与MyoD"],"a":"A","e":"果蝇控制眼形成的基因为eyeless，脊椎动物为Pax6，二者是直系同源基因，控制眼睛发育。","oe":["正确，果蝇eyeless与脊椎动物Pax6同源","顺序颠倒，果蝇为eyeless，脊椎动物为Pax6","脊椎动物对应基因为Pax6而非Sox2","MyoD调控肌肉分化，与眼形成无关"]},"cards":null,"mem":"EYELESS(果蝇)与Pax6(脊椎)控制眼形成"},{"i":11,"sec":"第四节 模式生物","title":"Pax6与eyeless同源 (p46)","notes":"Pax6 and eyeless encode highly related proteins and descended from the same ancestral gene——Pax6与eyeless编码高度相关的蛋白，源自同一祖先基因。这是基因功能进化保守的经典证据。\n\n【本页英文讲解】\n本页主题是 Pax6 与 eyeless 的同源关系。关键术语：Pax6（Pax6 基因，编码调控眼发育的转录因子）、eyeless（无眼基因，果蝇眼发育的关键基因）、ancestral gene（祖先基因）。核心概念：Pax6 与 eyeless 编码高度相关的蛋白，二者源自同一祖先基因，说明眼发育的调控机制在进化上高度保守。这是基因功能进化保守的经典证据。联系翟中和《细胞生物学》第4版第一章绪论中细胞与分子进化的保守性内容，常考“基因功能保守”的证据举例。","page":46,"level":"理解","img":"assets/img/ch01/p046.jpg","anim":null,"fig":null,"points":null,"check":{"q":"Pax6与eyeless基因之间的关系是（　）","o":["A. 是完全无关的两个基因","B. 编码高度相关蛋白，源自同一祖先基因","C. 只在果蝇中存在","D. 二者均不能控制眼发育"],"a":"B","e":"Pax6与eyeless编码高度相关的蛋白，源自同一祖先基因，是基因功能进化保守的经典证据。","oe":["二者高度相关，并非无关的两个基因。","正确，二者编码相关蛋白且同源。","Pax6也存在于脊椎动物等，并非仅果蝇。","Pax6与eyeless均参与控制眼睛的发育。"]},"cards":null,"mem":"Pax6与eyeless同源，源自同一祖先基因"},{"i":12,"sec":"第四节 模式生物","title":"功能保守性 (p47)","notes":"Functional conservation between eyeless and Pax6 genes：(a)果蝇eyeless基因无效突变(null mutation)→失去眼睛；(b)小鼠同源Pax-6基因无效突变→眼睛发育缺陷。两基因可互换补偿，证明功能高度保守。","page":47,"level":"理解","img":"assets/img/ch01/p047.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于eyeless与Pax6的功能保守性，下列说法正确的是（　）","o":["A. 果蝇eyeless突变会增强眼睛发育","B. 果蝇eyeless无效突变失去眼睛，小鼠Pax-6无效突变眼睛发育缺陷","C. 小鼠Pax-6突变只影响四肢发育","D. 两基因不能互换补偿"],"a":"B","e":"果蝇eyeless无效突变导致失去眼睛，小鼠Pax-6无效突变导致眼睛发育缺陷，两基因可互换补偿，证明功能高度保守。","oe":["eyeless失活导致缺眼，而非增强。","正确，两基因突变均导致眼发育缺陷。","Pax-6突变影响眼睛发育，而非四肢。","两基因可互换补偿，说明其功能高度保守。"]},"cards":null,"mem":"eyeless/Pax6无效突变皆缺眼，可互换补偿"},{"i":13,"sec":"第四节 模式生物","title":"Pax6与无虹膜症 (p48)","notes":"正常人的眼睛需要Pax6基因(对应果蝇eyeless)。Pax6功能不足者患遗传病aniridia(无虹膜症)——虹膜缺失。果蝇eyeless基因失活则缺眼。说明同一基因在果蝇和人中控制眼睛发育。","page":48,"level":"理解","img":"assets/img/ch01/p048.jpg","anim":null,"fig":null,"points":null,"check":{"q":"人Pax6基因功能不足可导致的遗传病是（　）","o":["A. 血友病","B. 无虹膜症(aniridia)","C. 白化病","D. 镰刀型细胞贫血"],"a":"B","e":"正常人眼发育需要Pax6，Pax6功能不足者患无虹膜症，表现为虹膜缺失，说明该基因在果蝇和人中均控制眼发育。","oe":["血友病由凝血因子缺陷导致，与Pax6无关。","正确，Pax6功能不足导致无虹膜症。","白化病与Pax6基因功能无关。","镰刀型贫血由血红蛋白基因突变引起。"]},"cards":null,"mem":"Pax6不足→无虹膜症；eyeless失活→果蝇无眼"},{"i":14,"sec":"第四节 模式生物","title":"Ey可触发整个器官生成 (p49)","notes":"果蝇单个转录调控蛋白Ey(脊椎动物Pax-6)能触发一个完整器官的生成，对眼睛发育至关重要。人为地在腿的前体细胞中表达Ey基因，可触发整套调节蛋白的级联反应，其共同作用引起多种类型细胞形成有组织的集合体——整个器官(眼睛)形成。说明关键调控基因的'主控'作用。","page":49,"level":"理解","img":"assets/img/ch01/p049.jpg","anim":null,"fig":null,"points":null,"check":{"q":"在果蝇腿的前体细胞中人为表达Ey基因，最可能的结果是？","o":["A. 使腿的前体细胞转变为肌肉细胞","B. 导致细胞停止分裂并发生凋亡","C. 触发调节级联反应，异位形成完整眼睛","D. 促进腿部呈指数级增长"],"a":"C","e":"Ey作为关键调控基因能触发整套调节蛋白级联反应，使前体细胞形成完整器官(眼睛)。","oe":["错：未提向肌肉细胞转化，不符合本页所学概念","错：表达Ey并非引起细胞凋亡的结果","对：笔记明确可触发级联形成眼睛","错：与形成整个器官这一结果无关"],"basis":"表达Ey基因，可触发整套调节蛋白的级联反应…整个器官形成"},"cards":null,"mem":"Ey一个主控基因可触发整套眼器官生成"},{"i":15,"sec":"第四节 模式生物","title":"小鼠 (p50)","notes":"小鼠(mice, Mus musculus)：哺乳动物模式生物，用于研究哺乳动物遗传、免疫、发育等。通过遗传工程突变体(engineering mouse genes)检验哪个已知基因是必需的及其功能。小鼠在进化上最接近人类，为研究众多人类遗传病和传染病提供模型。已开发数千种遗传品系，许多以冷冻胚胎形式保存。约20天完成胚胎发育，出生后6周性成熟。","page":50,"level":"掌握","img":"assets/img/ch01/p050.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于小鼠作为哺乳动物模式生物，下列说法正确的是（　）","o":["A. 在进化上远离人类","B. 胚胎发育约需6个月","C. 无法用于建立人类疾病模型","D. 约20天完成胚胎发育，出生后6周性成熟"],"a":"D","e":"小鼠约20天完成胚胎发育、出生后6周性成熟，进化上最接近人类，已开发数千种遗传品系用于人类疾病研究。","oe":["小鼠在进化上最接近人类，是理想疾病模型。","胚胎发育约20天，而非6个月。","小鼠是研究人类遗传病与传染病的重要模型。","正确，20天胚胎发育、6周性成熟。"]},"cards":[{"front":"小鼠作为哺乳动物模式生物的核心优势是什么？","back":"进化上最接近人类；可研究哺乳动物遗传、免疫、发育；为人类遗传病和传染病提供模型；已开发数千种遗传品系","mnemonic":"小鼠近人，免疫遗传发育全能问","type":"功能","useImg":false,"blank":"进化上最接近人类","blank2":"哺乳动物遗传"},{"front":"小鼠的胚胎发育和性成熟时间分别是多少？","back":"约20天完成胚胎发育；出生后6周性成熟","mnemonic":"二十天出生，六周就成年","type":"组成数字","useImg":false,"blank":"6周","blank2":"胚胎发育"}],"mem":"小鼠近人，免疫遗传发育全能问"},{"i":16,"sec":"第四节 模式生物","title":"人鼠相似基因与发育 (p51)","notes":"Human and mouse: similar genes and similar development——人类婴儿和小鼠额头上都有相似的白斑，因为两者在同一个基因(Kit，色素细胞发育和维持所需)上都有突变。同一个基因突变造成相同的遗传疾病。证明人鼠基因与发育机制高度相似。","page":51,"level":"理解","img":"assets/img/ch01/p051.jpg","anim":null,"fig":null,"points":null,"check":{"q":"人类婴儿与小鼠额头出现相似白斑，其原因是？","o":["A. 二者同一基因(Kit)发生了突变","B. 二者感染了相同的病毒","C. 二者缺乏相同的维生素","D. 环境因素导致的后天损伤"],"a":"A","e":"两者在色素细胞发育所需的同一基因Kit上都发生突变，说明人鼠基因与发育机制高度相似。","oe":["对：笔记指出同一基因突变致相同疾病","错：并非病毒感染所致，不符合本页所学概念","错：该白斑与维生素等营养缺乏无关","错：属遗传因素而非后天损伤，不符合本页所学概念"],"basis":"两者在同一个基因(Kit)上都有突变"},"cards":null,"mem":"人鼠Kit同突变→同白斑：基因与发育相似"},{"i":17,"sec":"第四节 模式生物","title":"斑马鱼 (p52)","notes":"斑马鱼(Zebrafish, Danio rerio)：理想的模式脊椎动物。①胚胎透明、发育快——生命前两周透明，可跟踪观察每个细胞的发育及胚胎发育的各种事件；②基因组只有小鼠或人类的一半；③世代时间仅约3个月；④隶属脊椎动物，消化系统、循环系统等器官与人类类似。","page":52,"level":"掌握","img":"assets/img/ch01/p052.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于斑马鱼作为模式脊椎动物，下列说法正确的是（　）","o":["A. 基因组比人类大一倍","B. 不属于脊椎动物","C. 世代时间约3年","D. 胚胎透明、发育快，前两周透明便于活体观察"],"a":"D","e":"斑马鱼胚胎透明、发育快，前两周透明可跟踪细胞发育；基因组仅为小鼠或人的一半，世代时间约3个月，属脊椎动物。","oe":["基因组约为人类的一半，非大一倍。","斑马鱼隶属脊椎动物，器官与人类类似。","斑马鱼世代时间约3个月，而非3年。","正确，胚胎透明且发育快，便于活体观察。"]},"cards":[{"front":"斑马鱼作为模式脊椎动物的四大优势是什么？","back":"①胚胎透明、发育快，前两周可跟踪每个细胞发育；②基因组只有小鼠或人类的一半；③世代时间仅约3个月；④脊椎动物，器官与人类类似","mnemonic":"透明快、基因半、三月代、脊椎同","type":"功能","useImg":true,"blank":"胚胎透明","blank2":"发育快"},{"front":"为什么斑马鱼适合观察胚胎发育过程？","back":"生命前两周胚胎透明，可跟踪观察每个细胞的发育及胚胎发育的各种事件","mnemonic":"透明两周，细胞步步可见","type":"功能","useImg":true,"blank":"胚胎透明","blank2":"可跟踪观察每个细胞的发育"}],"mem":"透明快、基因半、三月代、脊椎同"},{"i":18,"sec":"第四节 模式生物","title":"斑马鱼的遗传学优势 (p53)","notes":"Genetic power of zebrafish：被称为'脊椎动物中的果蝇'。兼具脊椎动物发育特征与果蝇般的强大遗传学研究优势(易于大规模诱变筛选)。","page":53,"level":"了解","img":"assets/img/ch01/p053.jpg","anim":null,"fig":null,"points":null,"check":{"q":"斑马鱼被称为“脊椎动物中的果蝇”，主要原因是（　）","o":["A. 不能进行大规模诱变筛选","B. 基因组与果蝇完全相同","C. 兼具脊椎动物发育特征与果蝇般强大的遗传学研究优势","D. 与果蝇亲缘关系最近"],"a":"C","e":"斑马鱼兼具脊椎动物发育特征与果蝇般易于大规模诱变筛选的遗传学优势，因此被称为“脊椎动物中的果蝇”。","oe":["斑马鱼易于进行大规模诱变筛选研究。","斑马鱼与果蝇基因组并不相同，非同一物种。","正确，兼具脊椎动物特征与强大遗传学优势。","该称谓源于研究优势，而非亲缘最近。"]},"cards":null,"mem":"斑马鱼：脊椎动物中的果蝇，易大规模诱变"},{"i":19,"sec":"第四节 模式生物","title":"斑马鱼胚胎观察 (p54)","notes":"An embryo 24 hours after fertilization——受精24小时后的斑马鱼胚胎。斑马鱼作为脊椎动物发育研究的模型，胚胎透明便于活体观察。","page":54,"level":"了解","img":"assets/img/ch01/p054.jpg","anim":null,"fig":null,"points":null,"check":{"q":"受精24小时后的斑马鱼胚胎成为良好发育模型，主要因为它（　）","o":["A. 胚胎体积非常巨大","B. 胚胎已发育成熟","C. 胚胎透明，便于活体观察","D. 胚胎不能成活"],"a":"C","e":"斑马鱼作为脊椎动物发育模型，胚胎透明便于活体观察，受精24小时后的胚胎可清晰显示早期发育过程。","oe":["其优势在于胚胎透明，而非体积巨大。","24小时胚胎尚处早期，并未成熟。","正确，胚胎透明使其便于活体观察发育。","斑马鱼胚胎可正常发育并成活，并非不能成活。"]},"cards":null,"mem":"斑马鱼受精24h胚胎，透明便活体观察"},{"i":20,"sec":"第四节 模式生物","title":"斑马鱼与人类相似性 (p55)","notes":"斑马鱼：①基因与人类基因相似性高(相似度达87%)，在其身上药物实验结果多数适用于人类；②胚胎透明(transparent embryos)，可清晰观察活体内细胞移动和性质改变。容易观察药物对其体内器官的影响。","page":55,"level":"理解","img":"assets/img/ch01/p055.jpg","anim":null,"fig":null,"points":null,"check":{"q":"斑马鱼成为研究人类发育与疾病重要模式生物的理由之一是？","o":["A. 成体体型巨大，便于解剖","B. 与人类基因差异极大","C. 药物实验结果完全不能外推","D. 胚胎透明，便于观察活体内细胞行为"],"a":"D","e":"斑马鱼胚胎透明，可清晰观察活体内细胞移动与性质改变，且药物实验结果多适用于人类。","oe":["错：斑马鱼成体体型很小，不符合本页所学概念","错：其基因与人类相似性高，不符合本页所学概念","错：多数结果适用于人类，不符合本页所学概念","对：笔记强调透明胚胎利于活体观察"],"basis":"胚胎透明，可清晰观察活体内细胞移动和性质改变"},"cards":null,"mem":"斑马鱼基因87%似人、胚胎透明，药试多适用"},{"i":21,"sec":"第四节 模式生物","title":"斑马鱼与心血管研究 (p56)","notes":"斑马鱼的神经中枢系统、内脏器官及视觉系统等与人类在分子水平85%相似，尤其心血管系统早期发育与人类极为相似，是进行心血管发育机制研究的理想模式脊椎动物。①心血管系统发育缺陷的斑马鱼仍能通过气体交换存活数天；②其血管发生与形成过程与哺乳动物相比有很高保守性。","page":56,"level":"理解","img":"assets/img/ch01/p056.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于斑马鱼作为心血管研究模式生物，下列说法正确的是（　）","o":["A. 与人类分子水平相似度极低","B. 心血管系统早期发育与人类极为相似","C. 心血管发育缺陷的斑马鱼立即死亡","D. 血管发生过程与哺乳动物差异很大"],"a":"B","e":"斑马鱼与人类分子水平约85%相似，心血管系统早期发育与人极为相似，缺陷个体仍可通过气体交换存活数天。","oe":["二者分子水平约85%相似，相似度高","正确，心血管系统早期发育与人类极为相似","缺陷个体仍可通过气体交换存活数天","斑马鱼血管发生过程与哺乳动物高度保守"]},"cards":null,"mem":"斑马鱼心血管与人均85%似，早期发育极相似"}],"mcq":[{"id":"ch01_mcq_20","mod":"模块四：模式生物","modI":3,"q":"下列关于原核细胞的说法正确的是？","o":["A. 遗传信息量比真核多","B. 具有膜包被的细胞器","C. 遗传信息量少,一般1000-4000个基因","D. 有细胞骨架"],"a":"C","e":"原核遗传信息量少(1000-4000基因)，人细胞含3×10^9核苷酸。原核无膜被细胞器和细胞骨架。","kp":"ch01_s3_8","oe":["原核遗传信息量远少于真核，本项与事实相反。","原核没有膜包被的细胞器，本项说法错误。","原核遗传信息量少，一般含1000-4000个基因，描述正确。","原核无典型细胞骨架，本项说法错误。"]},{"id":"ch01_mcq_21","mod":"模块四：模式生物","modI":3,"q":"真核细胞分室化(区域化)的意义是？","o":["A. 增加细胞体积","B. 使DNA复制转录(核)与蛋白质合成(胞质)分工精细","C. 减少能量消耗","D. 使细胞失去核膜"],"a":"B","e":"真核内膜系统使细胞分室化：核内DNA复制/转录，成熟mRNA出核，胞质合成蛋白质，分工更精细。","kp":"ch01_s3_8","oe":["分室化的主要意义在功能分工，而非增大细胞体积。","分室化使核内复制转录与胞质蛋白质合成分工精细。","分室化并非以减少能量消耗为主要意义。","分室化以核膜等内膜系统为基础，并非使细胞失去核膜。"]},{"id":"ch01_mcq_22","mod":"模块四：模式生物","modI":3,"q":"细胞骨架的功能不包括？","o":["A. 维持细胞形态","B. 细胞内物质运输的轨道","C. 使基质区域化、帮助细胞移动","D. 储存遗传信息"],"a":"D","e":"细胞骨架由骨架蛋白组成的网络结构，功能：维持形态、运输轨道、基质区域化、帮助移动。遗传信息由DNA储存。","kp":"ch01_s3_8","oe":["维持细胞形态是细胞骨架的功能之一。","作为细胞内物质运输的轨道是细胞骨架的功能之一。","使基质区域化、帮助细胞移动是细胞骨架的功能之一。","储存遗传信息由DNA承担，不是细胞骨架的功能，为答案。"]},{"id":"ch01_mcq_23","mod":"模块四：模式生物","modI":3,"q":"下列属于真核模式生物的是？","o":["A. 大肠杆菌","B. 支原体","C. 酿酒酵母","D. 蓝藻"],"a":"C","e":"酿酒酵母是最小的真核模式生物。大肠杆菌、支原体、蓝藻均为原核生物。","kp":"ch01_s3_0","oe":["大肠杆菌是原核生物，不是真核模式生物。","支原体是原核生物，不是真核模式生物。","酿酒酵母是最小的真核模式生物，属真核模式生物。","蓝藻是原核生物，不是真核模式生物。"]},{"id":"ch01_mcq_24","mod":"模块四：模式生物","modI":3,"q":"实验细胞学时期(1900-1953)的三大分支是？","o":["A. 细胞遗传、细胞生理、细胞化学","B. 细胞膜、细胞质、细胞核","C. 酶学、代谢、遗传","D. 显微镜、染色、培养"],"a":"A","e":"实验细胞学三大分支：细胞遗传学、细胞生理学、细胞化学，从形态观察深入功能与机制研究。","kp":"ch01_s3_8","oe":["正确。实验细胞学三大分支确为细胞遗传学、细胞生理学和细胞化学，由形态深入功能机制。","错。细胞膜、细胞质、细胞核是细胞结构划分，并非实验细胞学的三大分支。","错。酶学、代谢、遗传是学科领域泛称，不是该时期细胞学的三大分支。","错。显微镜、染色、培养是研究技术与方法，不能作为学科分支。"]},{"id":"ch01_mcq_25","mod":"模块四：模式生物","modI":3,"q":"胡克观察到的'细胞'实际上是？","o":["A. 活的动物细胞","B. 死植物细胞的细胞壁(软木塞)","C. 细菌","D. 细胞核"],"a":"B","e":"胡克1665年观察栎树软木塞切片，看到的是死细胞的细胞壁，形似蜂巢，命名cellulae。","kp":"ch01_s3_8","oe":["错。胡克看到的是软木塞中死细胞的残余，来自植物而非活的动物细胞。","正确。胡克1665年观察软木塞死细胞的细胞壁，形似蜂巢，将其命名为cellulae。","错。受当时显微镜分辨率限制，他看到的是细胞壁围成的空腔，并非细菌。","错。胡克观察到的是整个细胞壁围成的空腔，当时并未识别出细胞核。"]}],"judge":[{"id":"ch01_judge_9","modI":3,"q":"大肠杆菌、酿酒酵母、拟南芥、秀丽隐杆线虫、果蝇、小鼠、斑马鱼都是常用模式生物。","a":"对","e":"这些均为常用模式生物；大肠杆菌/酵母为微生物，拟南芥为植物，线虫/果蝇/斑马鱼为无脊椎/脊椎动物，小鼠为哺乳类。","kp":"ch01_s3_0","oe":["这些均为常用模式生物，涵盖微生物、植物、无脊椎与脊椎动物及哺乳类。","误以为其中某物种非常用模式生物，或种类归属记错，故判错。"]},{"id":"ch01_judge_10","modI":3,"q":"秀丽隐杆线虫成体有1090个体细胞，其中131个发生凋亡。","a":"错","e":"线虫从受精卵产生1090个细胞，成体为959个体细胞，131个细胞在发育中凋亡。","kp":"ch01_s3_5","oe":["若把1090当作成体体细胞数则判对，实则1090是受精卵产生的细胞数。","线虫受精卵产生1090个细胞，成体为959个，131个在发育中凋亡。"]}],"fill":[{"id":"ch01_fill_9","modI":3,"q":"大肠杆菌基因组约________个基因(1997年测序)；酵母编码约________个蛋白质。","a":"4288,6200","kp":"ch01_s3_1","oe":["1997年完成大肠杆菌基因组测序，其约含4288个基因。","酵母基因组编码约6200个蛋白质，是重要的真核模式生物。"]},{"id":"ch01_fill_10","modI":3,"q":"秀丽隐杆线虫成体有________个体细胞，发育中________个细胞发生凋亡；相关研究获________年诺贝尔奖。","a":"959,131,2002(细胞凋亡)/2006(RNAi)","kp":"ch01_s3_5","oe":["秀丽隐杆线虫成体共有959个体细胞，且数目恒定。","其发育过程中有131个细胞按程序发生凋亡。","细胞凋亡相关研究获2002年诺贝尔生理学或医学奖。"]},{"id":"ch01_fill_11","modI":3,"q":"控制果蝇眼发育的基因是________，其脊椎动物同源基因是________；后者缺陷导致________。","a":"eyeless,Pax6,无虹膜症(aniridia)","kp":"ch01_s3_10","oe":["控制果蝇眼发育的关键基因是eyeless，其突变导致眼发育异常。","eyeless在脊椎动物中的同源基因为Pax6，功能高度保守。","Pax6缺陷可导致人类无虹膜症，说明眼发育机制高度保守。"]},{"id":"ch01_fill_12","modI":3,"q":"斑马鱼基因与人类相似度达________%，是研究________发育机制(尤其心血管)的理想模式脊椎动物。","a":"87,脊椎动物","kp":"ch01_s3_21","oe":["斑马鱼基因与人类相似度达87%，是重要的模式生物。","斑马鱼是研究脊椎动物发育机制(尤其心血管)的理想模式动物。"]}],"short":[{"id":"ch01_short_5","modI":3,"q":"列举5种常用模式生物及其作为模式生物的主要优点。","a":"常用模式生物及优点：\n\n①大肠杆菌(E. coli)：繁殖快(20-30min/代)，基因组简单(约4288基因，1997测序)，表达量高(5-30%)，常用作蛋白表达系统；DNA复制/转录/翻译机制最初在其阐明。\n\n②酿酒酵母(S. cerevisiae)：最小真核模式生物，基因组小(约6200蛋白，1996测序)，单倍体二倍体均可生长，含大量与人同源蛋白，研究细胞周期/凋亡。\n\n③拟南芥(A. thaliana)：基因组小(1.2亿bp，5条染色体)，世代短(8-10周)，首个完成全基因组测序的被子植物。\n\n④秀丽隐杆线虫(C. elegans)：成体959个体细胞，细胞命运精确可预测，体壁透明，凋亡机制保守(2002诺贝尔奖)；RNAi(2006诺贝尔奖)。\n\n⑤果蝇(D. melanogaster)：基因组约13600基因，研究胚胎发育和染色体；eyeless/Pax6控制眼发育。\n\n⑥小鼠(Mus musculus)：进化上最接近人类，用于研究哺乳动物遗传/免疫/发育，与人基因高度相似(Kit白斑)。\n\n⑦斑马鱼(Danio rerio)：模式脊椎动物，胚胎透明，基因与人类87%相似，研究心血管发育。\n\n【共同基础】由共同祖先进化而来，重要功能基因高度保守，信息可外推至其它生物。","kp":"ch01_s3_0"}],"calc":[{"id":"ch01_calc_1","modI":3,"q":"论述模式生物在细胞生物学研究中的意义,并说明为什么可以用简单生物研究人类细胞规律。","a":"模式生物是细胞生物学研究的基石,其信息可外推至人类","steps":"【模式生物的定义与选择标准】\n①由共同祖先进化而来；\n②重要功能基因在进化上高度保守；\n③易培养、繁殖快、基因组简单、遗传背景清楚。\n\n【为什么可以外推】\n①所有生物有共同祖先→基本细胞过程(DNA复制、转录、翻译、细胞周期、凋亡)高度保守；\n②例证：\n  • 人Cdc2与裂殖酵母63%、芽殖酵母58%同源→细胞周期保守；\n  • 线虫凋亡基因在哺乳动物有同源基因→凋亡机制保守；\n  • 果蝇eyeless与人Pax6同源→眼发育保守；\n  • 人鼠Kit基因突变均致白斑→基因功能保守。\n\n【意义】\n①用简单生物(大肠杆菌/酵母/线虫/果蝇/拟南芥/斑马鱼/小鼠)研究基因功能，成本低、周期短；\n②获得的规律可应用于较难研究的生物(如人类)；\n③模式生物推动了多项诺贝尔奖发现(线虫凋亡2002、RNAi 2006等)；\n④是理解人类疾病机制、开发药物的重要工具(如斑马鱼药物实验87%适用于人类)。\n\n【结论】\n进化保守性使模式生物研究具有普遍意义。","kp":"ch01_s3_0"}],"term":[{"id":"ch01_term_4","modI":3,"term":"模式生物(Model Organism)","def":"①用于研究基本生命规律、信息可外推至其它生物的易研究物种（定义）。②选择标准：共同祖先、重要基因进化保守、易培养繁殖快基因组简单（标准）。③常用：大肠杆菌、酿酒酵母、拟南芥、秀丽隐杆线虫、果蝇、小鼠、斑马鱼（举例）。④意义：成本低周期短，推动多项重大发现(线虫凋亡2002、RNAi 2006)（意义）。","kps":"踩分点:①定义(1分)②选择标准(1分)③举例(1分)④意义(1分)","kp":"ch01_s3_0"},{"id":"ch01_term_11","modI":3,"term":"eyeless/Pax6","def":"①控制无脊椎动物和脊椎动物眼形成的一对直系同源基因（定义）。②eyeless在果蝇、Pax6在脊椎动物，编码高度相关蛋白，源自同一祖先基因（同源）。③功能保守：eyeless失活致果蝇缺眼；人Pax6不足致无虹膜症(aniridia)（功能）。④Ey可触发整个眼睛器官生成，是发育主控基因的经典例子（意义）。","kps":"踩分点:①定义(1分)②同源性(1分)③功能保守(1分)④意义(1分)","kp":"ch01_s3_11"},{"id":"ch01_term_12","modI":3,"term":"秀丽隐杆线虫(C. elegans)","def":"①重要的模式生物，成体仅959个体细胞，细胞命运精确可预测（定义）。②发育：受精卵产生1090个细胞，131个发生凋亡（发育）。③特点：体壁透明、世代短(25℃约2.5天)、易遗传分析（特点）。④贡献：细胞凋亡(2002诺贝尔奖)、RNAi(2006诺贝尔奖)；凋亡机制从线虫到人保守（意义）。","kps":"踩分点:①定义(1分)②发育数字(1分)③特点(1分)④诺贝尔奖/意义(2分)","kp":"ch01_s3_5"},{"id":"ch01_term_15","modI":3,"term":"斑马鱼(Danio rerio)","def":"①理想的模式脊椎动物（定义）。②特点：胚胎透明、发育快、基因组约为小鼠/人类一半、世代约3个月（特点）。③基因与人类相似度87%，中枢神经/内脏/视觉系统分子水平85%相似，尤其心血管系统（相似性）。④应用：药物实验多适用人类，研究脊椎动物发育(尤其心血管)（应用）。","kps":"踩分点:①定义(1分)②特点(1分)③相似性(1分)④应用(1分)","kp":"ch01_s3_17"}]}],"mcq":[{"id":"ch01_mcq_1","mod":"模块一：细胞生物学发展简史","modI":0,"q":"1665年首次发现细胞(死细胞壁)的科学家是？","o":["A. 列文虎克","B. 胡克(Robert Hooke)","C. 施旺","D. 魏尔肖"],"a":"B","e":"1665年胡克观察栎树软木塞切片，借用拉丁文'cellulae'命名'cell'。列文虎克1674年首次观察活细胞。","kp":"ch01_s0_2","oe":["列文虎克1674年首次观察活细胞，并非1665年发现细胞者。","1665年胡克观察软木塞死细胞壁并命名cell，为首次发现者。","施旺1839年参与提出细胞学说，非首次发现细胞。","魏尔肖1858年提出细胞来自细胞，非首次发现细胞。"]},{"id":"ch01_mcq_2","mod":"模块一：细胞生物学发展简史","modI":0,"q":"细胞学说的三个基本原则不包括？","o":["A. 所有有机体由一个或多个细胞构成","B. 细胞是结构和功能的基本单位","C. 所有细胞来自已有细胞的分裂","D. 细胞都由细胞核和细胞器组成"],"a":"D","e":"细胞学说三原则：①生物由细胞构成；②细胞是基本单位；③细胞来自细胞(1858魏尔肖)。D是原核/真核区别，非细胞学说。","kp":"ch01_s0_5","oe":["生物由细胞构成是细胞学说原则①，描述正确故非答案。","细胞是结构与功能基本单位是原则②，描述正确故非答案。","细胞来自已有细胞分裂是原则③(魏尔肖)，正确故非答案。","此说非细胞学说原则，且原核细胞无核膜与细胞器，为答案。"]},{"id":"ch01_mcq_3","mod":"模块一：细胞生物学发展简史","modI":0,"q":"补充细胞学说第三条原则(细胞来自细胞)的科学家是？","o":["A. 施莱登","B. 施旺","C. 魏尔肖(Rudolf Virchow,1858)","D. 威尔逊"],"a":"C","e":"1858年魏尔肖补充：所有细胞都来自已有细胞的分裂(Omnis cellula e cellula)。","kp":"ch01_s0_4","oe":["施莱登提出植物细胞学说，未补充细胞来自细胞原则。","施旺提出动物细胞学说，并非补充第三条原则者。","魏尔肖1858年提出所有细胞都来自已有细胞的分裂。","威尔逊1925年强调细胞的重要性，非补充该原则者。"]},{"id":"ch01_mcq_4","mod":"模块一：细胞生物学发展简史","modI":0,"q":"细胞学经典时期是哪一时间段？","o":["A. 1665-1838","B. 1838-1858","C. 1875-1900","D. 1900-1953"],"a":"C","e":"19世纪最后25年(1875-1900)是细胞学经典时期；1900-1953为实验细胞学时期。","kp":"ch01_s0_9","oe":["1665-1838是细胞发现到细胞学说建立时期，非经典时期。","1838-1858是细胞学说建立与完善时期，非经典时期。","19世纪最后25年即1875-1900为细胞学经典时期。","1900-1953为实验细胞学时期，并非经典时期。"]},{"id":"ch01_mcq_5","mod":"模块一：细胞生物学发展简史","modI":0,"q":"原核细胞与真核细胞在结构上的共同点是？","o":["A. 都有核膜","B. 都有膜被细胞器","C. 都有细胞膜、DNA/RNA和核糖体","D. 都有细胞骨架"],"a":"C","e":"共同点：都有细胞膜、DNA和RNA、核糖体。核膜、膜被细胞器、细胞骨架是真核特有。","kp":"ch01_s0_0","oe":["核膜是真核细胞特有结构，原核细胞没有核膜。","膜被细胞器为真核特有，原核细胞没有。","均有细胞膜、DNA/RNA和核糖体，是原核与真核的共同点。","细胞骨架是真核细胞特有，原核无典型细胞骨架。"]},{"id":"ch01_mcq_6","mod":"模块一：细胞生物学发展简史","modI":0,"q":"关于原核细胞的描述,正确的是？","o":["A. 有核膜和核仁","B. 只有拟核,无核膜核仁,边转录边翻译","C. 有膜被细胞器","D. 进行有丝分裂"],"a":"B","e":"原核无核膜核仁只有拟核→边转录边翻译；真核分室化，核内转录、胞质翻译。原核行简单分裂。","kp":"ch01_s0_2","oe":["核膜和核仁是真核特征，原核细胞没有核膜核仁。","原核只有拟核、无核膜核仁，可边转录边翻译，描述正确。","原核细胞没有膜被细胞器，本项说法错误。","原核行简单二分裂，不进行有丝分裂。"]},{"id":"ch01_mcq_7","mod":"模块一：细胞生物学发展简史","modI":0,"q":"已知最小的细胞是？","o":["A. 蓝藻","B. 支原体(Mycoplasma,0.1~0.3μm)","C. 大肠杆菌","D. 酵母"],"a":"B","e":"支原体是已知最小细胞，0.1~0.3μm。蓝藻属真细菌；酵母是最小真核模式生物。","kp":"ch01_s0_2","oe":["蓝藻(蓝细菌)较支原体大，不是已知最小细胞。","支原体直径约0.1-0.3μm，是已知最小的细胞。","大肠杆菌约1-3μm，明显大于支原体。","酵母是最小真核模式生物，体积大于支原体。"]},{"id":"ch01_mcq_8","mod":"模块二：细胞的基本性质","modI":1,"q":"古细菌通常生活在？","o":["A. 正常土壤","B. 极端环境(热泉、浓盐水、厌氧沉积层等)","C. 人体血液","D. 植物叶片"],"a":"B","e":"古细菌出现在极端环境：浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管等，如产甲烷菌。","kp":null,"oe":["古细菌多栖极端环境，并非以正常土壤为主。","古细菌常见于热泉、浓盐水、厌氧沉积层等极端环境。","人体血液并非古细菌的典型栖息环境。","植物叶片并非古细菌的典型栖息环境。"]},{"id":"ch01_mcq_9","mod":"模块二：细胞的基本性质","modI":1,"q":"真核细胞与原核细胞在遗传物质上的区别是？","o":["A. 完全相同","B. 真核有大量DNA-蛋白染色体,原核仅一个环状裸露DNA","C. 原核有多条染色体","D. 真核DNA裸露"],"a":"B","e":"真核：大量由DNA和蛋白质组成的染色体；原核：仅一个单链、环状、裸露的DNA染色体。","kp":"ch01_s1_0","oe":["真核与原核遗传物质差异显著，并非完全相同。","真核为DNA-蛋白染色体，原核仅一个环状裸露DNA。","原核通常仅一条环状DNA，并非有多条染色体。","真核DNA与蛋白质结合成染色体，并非裸露。"]},{"id":"ch01_mcq_10","mod":"模块二：细胞的基本性质","modI":1,"q":"原核与真核鞭毛的主要区别是？","o":["A. 完全相同","B. 原核由flagellin组成,真核为9+2微管(tubulin+dynein)","C. 原核由微管组成","D. 真核由鞭毛蛋白组成"],"a":"B","e":"原核鞭毛=单一蛋白flagellin；真核鞭毛=9+2微管结构(tubulin)，马达蛋白dynein。趋同进化经典例。","kp":"ch01_s1_0","oe":["两者结构组成截然不同，并非完全相同。","原核鞭毛由flagellin组成，真核为9+2微管(tubulin+dynein)。","原核鞭毛不含微管，微管结构是真核鞭毛的特征。","真核鞭毛由微管蛋白构成，鞭毛蛋白属原核鞭毛。"]},{"id":"ch01_mcq_11","mod":"模块二：细胞的基本性质","modI":1,"q":"大肠杆菌作为模式生物的优点不包括？","o":["A. 繁殖快(20-30min一代)","B. 基因组简单,1997年测序完毕","C. 有核膜和细胞器","D. 常用作蛋白质表达系统"],"a":"C","e":"大肠杆菌是原核生物，无核膜和膜被细胞器。其优点是繁殖快、基因组简单、表达量高。","kp":null,"oe":["繁殖快、20-30分钟一代是大肠杆菌的优点之一。","基因组简单、1997年测序完毕是其优点之一。","大肠杆菌是原核生物，无核膜和膜被细胞器，此说法错误。","常作蛋白质表达系统是其优点之一。"]},{"id":"ch01_mcq_12","mod":"模块二：细胞的基本性质","modI":1,"q":"第一个完成全基因组测定的被子植物是？","o":["A. 水稻","B. 拟南芥(Arabidopsis thaliana)","C. 玉米","D. 大豆"],"a":"B","e":"拟南芥基因组小(1.2亿碱基对)，是被子植物中第一个完成全基因组测定的植物。","kp":null,"oe":["水稻基因组较大，且晚于拟南芥完成全基因组测定。","拟南芥是被子植物中第一个完成全基因组测定的植物。","玉米基因组较大，并非首个完成全基因组测定的植物。","大豆并非首个完成全基因组测定的被子植物。"]},{"id":"ch01_mcq_13","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"秀丽隐杆线虫成体的体细胞数目是？","o":["A. 1090个","B. 959个","C. 131个","D. 6200个"],"a":"B","e":"线虫从受精卵产生1090个细胞，最终成体959个体细胞，其中131个发生凋亡。细胞命运精确可预测。","kp":"ch01_s2_0","oe":["1090是受精卵产生的细胞总数，非成体体细胞数。","线虫成体共有959个体细胞，数目精确可预测。","131是发育过程中发生凋亡的细胞数，非成体体细胞数。","6200与线虫成体体细胞数目不符。"]},{"id":"ch01_mcq_14","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"线虫相关的两次诺贝尔奖是？","o":["A. 细胞凋亡(2002)和RNAi(2006)","B. DNA复制和转录","C. 光合作用和呼吸","D. 酶学和免疫"],"a":"A","e":"线虫用于研究细胞凋亡(2002年诺贝尔奖)和RNA干扰RNAi(2006年诺贝尔奖)。","kp":null,"oe":["线虫凋亡研究获2002年、RNAi研究获2006年诺贝尔奖。","DNA复制和转录研究与线虫两次诺奖无关。","光合作用和呼吸研究与线虫诺奖项目无关。","酶学和免疫研究与线虫诺奖项目不符。"]},{"id":"ch01_mcq_15","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"控制果蝇和脊椎动物眼发育的同源基因是？","o":["A. eyeless与Pax6","B. Kit与Pax6","C. Cdc2与eyeless","D. p53与Rb"],"a":"A","e":"果蝇eyeless与脊椎动物Pax6是直系同源基因，源自同一祖先基因，控制眼睛发育。","kp":"ch01_s2_6","oe":["果蝇eyeless与脊椎动物Pax6为控制眼发育的直系同源基因。","Kit与色素细胞发育有关，并非控制眼发育的同源基因。","Cdc2与细胞周期相关，eyeless与眼发育相关，二者不配对。","p53与Rb为抑癌基因，不是控制眼发育的同源基因。"]},{"id":"ch01_mcq_16","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"人类Pax6功能不足会导致？","o":["A. 白化病","B. 无虹膜症(aniridia)","C. 镰刀型贫血","D. 色盲"],"a":"B","e":"人Pax6功能不足患遗传病aniridia(无虹膜症)；果蝇eyeless失活则缺眼。同一基因控制眼发育。","kp":"ch01_s2_2","oe":["白化病与酪氨酸酶等基因缺陷有关，与Pax6无关。","人Pax6功能不足导致无虹膜症(aniridia)。","镰刀型贫血由血红蛋白基因突变引起，与Pax6无关。","色盲与视色素基因缺陷相关，并非Pax6所致。"]},{"id":"ch01_mcq_17","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"人鼠相似白斑(Kit基因突变)说明了？","o":["A. 两者无关","B. 同一基因突变造成相同的遗传疾病,人鼠基因高度相似","C. 只有人有Kit","D. 小鼠没有色素细胞"],"a":"B","e":"人婴儿和小鼠额头相似白斑，因同一基因Kit突变，证明人鼠基因与发育机制高度相似。","kp":"ch01_s2_6","oe":["人鼠因同源Kit基因突变出现相似白斑，关系密切。","同一Kit基因突变致相似白斑，说明人鼠基因高度相似。","小鼠同样具有Kit基因，并非只有人才有。","小鼠有黑色素细胞，Kit突变影响其发育，并非没有。"]},{"id":"ch01_mcq_18","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"斑马鱼作为模式生物的特点不包括？","o":["A. 胚胎透明","B. 基因与人类相似度87%","C. 世代时间仅约3个月","D. 是无脊椎动物"],"a":"D","e":"斑马鱼是模式脊椎动物(非无脊椎)。特点：胚胎透明、基因与人类87%相似、世代约3个月。","kp":"ch01_s2_2","oe":["胚胎透明是斑马鱼作为模式生物的特点之一。","基因与人类相似度达87%是其特点之一。","世代时间仅约3个月是其特点之一。","斑马鱼是脊椎动物，本项称其无脊椎，说法错误，为答案。"]},{"id":"ch01_mcq_19","mod":"模块三：原核细胞与真核细胞","modI":2,"q":"酵母与人类细胞周期蛋白的相似性说明了？","o":["A. 酵母是原核生物","B. 细胞周期调控机制在进化上高度保守","C. 人类没有Cdc2","D. 两者无同源蛋白"],"a":"B","e":"人Cdc2与裂殖酵母63%、与芽殖酵母58%相同→细胞周期调控从酵母到人高度保守。","kp":"ch01_s2_8","oe":["酵母是真核生物，并非原核生物。","人Cdc2与酵母同源，说明细胞周期调控在进化上高度保守。","人类存在Cdc2，与酵母细胞周期蛋白同源。","两者存在同源细胞周期蛋白，并非无同源蛋白。"]},{"id":"ch01_mcq_20","mod":"模块四：模式生物","modI":3,"q":"下列关于原核细胞的说法正确的是？","o":["A. 遗传信息量比真核多","B. 具有膜包被的细胞器","C. 遗传信息量少,一般1000-4000个基因","D. 有细胞骨架"],"a":"C","e":"原核遗传信息量少(1000-4000基因)，人细胞含3×10^9核苷酸。原核无膜被细胞器和细胞骨架。","kp":"ch01_s3_8","oe":["原核遗传信息量远少于真核，本项与事实相反。","原核没有膜包被的细胞器，本项说法错误。","原核遗传信息量少，一般含1000-4000个基因，描述正确。","原核无典型细胞骨架，本项说法错误。"]},{"id":"ch01_mcq_21","mod":"模块四：模式生物","modI":3,"q":"真核细胞分室化(区域化)的意义是？","o":["A. 增加细胞体积","B. 使DNA复制转录(核)与蛋白质合成(胞质)分工精细","C. 减少能量消耗","D. 使细胞失去核膜"],"a":"B","e":"真核内膜系统使细胞分室化：核内DNA复制/转录，成熟mRNA出核，胞质合成蛋白质，分工更精细。","kp":"ch01_s3_8","oe":["分室化的主要意义在功能分工，而非增大细胞体积。","分室化使核内复制转录与胞质蛋白质合成分工精细。","分室化并非以减少能量消耗为主要意义。","分室化以核膜等内膜系统为基础，并非使细胞失去核膜。"]},{"id":"ch01_mcq_22","mod":"模块四：模式生物","modI":3,"q":"细胞骨架的功能不包括？","o":["A. 维持细胞形态","B. 细胞内物质运输的轨道","C. 使基质区域化、帮助细胞移动","D. 储存遗传信息"],"a":"D","e":"细胞骨架由骨架蛋白组成的网络结构，功能：维持形态、运输轨道、基质区域化、帮助移动。遗传信息由DNA储存。","kp":"ch01_s3_8","oe":["维持细胞形态是细胞骨架的功能之一。","作为细胞内物质运输的轨道是细胞骨架的功能之一。","使基质区域化、帮助细胞移动是细胞骨架的功能之一。","储存遗传信息由DNA承担，不是细胞骨架的功能，为答案。"]},{"id":"ch01_mcq_23","mod":"模块四：模式生物","modI":3,"q":"下列属于真核模式生物的是？","o":["A. 大肠杆菌","B. 支原体","C. 酿酒酵母","D. 蓝藻"],"a":"C","e":"酿酒酵母是最小的真核模式生物。大肠杆菌、支原体、蓝藻均为原核生物。","kp":"ch01_s3_0","oe":["大肠杆菌是原核生物，不是真核模式生物。","支原体是原核生物，不是真核模式生物。","酿酒酵母是最小的真核模式生物，属真核模式生物。","蓝藻是原核生物，不是真核模式生物。"]},{"id":"ch01_mcq_24","mod":"模块四：模式生物","modI":3,"q":"实验细胞学时期(1900-1953)的三大分支是？","o":["A. 细胞遗传、细胞生理、细胞化学","B. 细胞膜、细胞质、细胞核","C. 酶学、代谢、遗传","D. 显微镜、染色、培养"],"a":"A","e":"实验细胞学三大分支：细胞遗传学、细胞生理学、细胞化学，从形态观察深入功能与机制研究。","kp":"ch01_s3_8","oe":["正确。实验细胞学三大分支确为细胞遗传学、细胞生理学和细胞化学，由形态深入功能机制。","错。细胞膜、细胞质、细胞核是细胞结构划分，并非实验细胞学的三大分支。","错。酶学、代谢、遗传是学科领域泛称，不是该时期细胞学的三大分支。","错。显微镜、染色、培养是研究技术与方法，不能作为学科分支。"]},{"id":"ch01_mcq_25","mod":"模块四：模式生物","modI":3,"q":"胡克观察到的'细胞'实际上是？","o":["A. 活的动物细胞","B. 死植物细胞的细胞壁(软木塞)","C. 细菌","D. 细胞核"],"a":"B","e":"胡克1665年观察栎树软木塞切片，看到的是死细胞的细胞壁，形似蜂巢，命名cellulae。","kp":"ch01_s3_8","oe":["错。胡克看到的是软木塞中死细胞的残余，来自植物而非活的动物细胞。","正确。胡克1665年观察软木塞死细胞的细胞壁，形似蜂巢，将其命名为cellulae。","错。受当时显微镜分辨率限制，他看到的是细胞壁围成的空腔，并非细菌。","错。胡克观察到的是整个细胞壁围成的空腔，当时并未识别出细胞核。"]}],"judge":[{"id":"ch01_judge_1","modI":0,"q":"1665年列文虎克首次观察到活细胞，并借用拉丁文“cellulae”命名了细胞。","a":"错","e":"1665年胡克(Robert Hooke)观察软木塞并命名“cellulae”；列文虎克1674年首次观察到活细胞。","kp":"ch01_s0_3","oe":["易误记为列文虎克1665年观察软木塞并命名cellulae，实为胡克所为。","1665年胡克观察软木塞并命名cellulae；列文虎克1674年才首次观察到活细胞。"]},{"id":"ch01_judge_2","modI":0,"q":"细胞学说认为所有生物（包括病毒）都由细胞构成。","a":"错","e":"细胞学说第一原则为“所有有机体由一个或多个细胞构成”，病毒是非细胞形态生命体，属例外。","kp":"ch01_s0_4","oe":["易误以为病毒也是细胞，忽略其为非细胞形态生命体，故判对。","细胞学说指所有有机体由一个或多个细胞构成，病毒是非细胞形态生命体，属例外。"]},{"id":"ch01_judge_3","modI":0,"q":"魏尔肖提出“细胞来自细胞”，补充了细胞学说的第三条原则。","a":"对","e":"1858年魏尔肖(Rudolf Virchow)补充：所有细胞都来自已有细胞的分裂。","kp":"ch01_s0_4","oe":["1858年魏尔肖补充‘细胞来自细胞’，即细胞只能由已有细胞分裂产生。","误以为该原则由施莱登或施旺提出，或否认其为细胞学说第三条，故判错。"]},{"id":"ch01_judge_4","modI":2,"q":"原核细胞没有核膜和核仁，只有拟核，且没有膜被细胞器和细胞骨架。","a":"对","e":"原核细胞无核膜核仁、无膜被细胞器与细胞骨架，DNA为单链环状裸露；这是与真核细胞的根本区别之一。","kp":"ch01_s2_2","oe":["原核细胞无核膜核仁，仅有拟核，且无膜被细胞器与细胞骨架，故正确。","误以为原核细胞有核糖体外的膜被细胞器或有细胞骨架，从而判错。"]},{"id":"ch01_judge_5","modI":2,"q":"支原体是已知最小的细胞，也是唯一没有细胞壁的原核细胞。","a":"对","e":"支原体直径仅0.1~0.3μm，是最小、最简单的原核细胞，也是唯一无细胞壁的原核细胞。","kp":"ch01_s2_3","oe":["支原体直径0.1~0.3μm，是最小、最简单的原核细胞，且唯一无细胞壁。","误以为所有原核细胞都有细胞壁，或把最小细胞记成衣原体，故判错。"]},{"id":"ch01_judge_6","modI":2,"q":"真核细胞与原核细胞的鞭毛结构相同，都由微管蛋白(tubulin)组成。","a":"错","e":"原核鞭毛由单一蛋白flagellin组成；真核鞭毛为“9+2”微管结构(tubulin+dynein)，二者不同。","kp":"ch01_s2_9","oe":["若以为鞭毛均含微管蛋白则判对，混淆了原核与真核鞭毛的组成。","原核鞭毛由flagellin组成，真核鞭毛为9+2微管(tubulin)结构。"]},{"id":"ch01_judge_7","modI":2,"q":"古细菌在系统发育上既不属于真核生物，也不属于真细菌，是一类特殊细菌。","a":"对","e":"古细菌具有原核与真核的混合特征及独有特征，被认为代表第三界生物。","kp":"ch01_s2_4","oe":["古细菌兼具原核与真核特征并有独有特征，系统发育上独立，代表第三界生物。","误以为古细菌属于真细菌，忽略其与真细菌的系统发育差异，故判错。"]},{"id":"ch01_judge_8","modI":1,"q":"细胞体积越大，其相对表面积越大，物质交换效率越高。","a":"错","e":"细胞体积与相对表面积成反比：体积越大，相对表面积越小，物质交换效率越低。","kp":"ch01_s1_0","oe":["若认为体积越大相对表面积越大则判对，实则两者成反比关系。","体积越大相对表面积越小，物质交换效率越低，故原说法错误。"]},{"id":"ch01_judge_9","modI":3,"q":"大肠杆菌、酿酒酵母、拟南芥、秀丽隐杆线虫、果蝇、小鼠、斑马鱼都是常用模式生物。","a":"对","e":"这些均为常用模式生物；大肠杆菌/酵母为微生物，拟南芥为植物，线虫/果蝇/斑马鱼为无脊椎/脊椎动物，小鼠为哺乳类。","kp":"ch01_s3_0","oe":["这些均为常用模式生物，涵盖微生物、植物、无脊椎与脊椎动物及哺乳类。","误以为其中某物种非常用模式生物，或种类归属记错，故判错。"]},{"id":"ch01_judge_10","modI":3,"q":"秀丽隐杆线虫成体有1090个体细胞，其中131个发生凋亡。","a":"错","e":"线虫从受精卵产生1090个细胞，成体为959个体细胞，131个细胞在发育中凋亡。","kp":"ch01_s3_5","oe":["若把1090当作成体体细胞数则判对，实则1090是受精卵产生的细胞数。","线虫受精卵产生1090个细胞，成体为959个，131个在发育中凋亡。"]}],"fill":[{"id":"ch01_fill_1","modI":0,"q":"1665年________(Robert Hooke)首次发现细胞；1674年________首次观察到活细胞。","a":"胡克,列文虎克(van Leeuwenhoek)","kp":"ch01_s0_2","oe":["1665年胡克用自制显微镜观察软木薄片，看到细胞壁，首次发现并命名细胞。","1674年列文虎克用显微镜首次观察到细菌、原生动物等活细胞。"]},{"id":"ch01_fill_2","modI":0,"q":"细胞学说由________和________建立(1839)，1858年由________补充第三条'细胞来自细胞'。","a":"施莱登(Schleiden),施旺(Schwann),魏尔肖(Virchow)","kp":"ch01_s0_4","oe":["1839年德国植物学家施莱登提出所有植物由细胞组成，奠定细胞学说基础。","同年施旺把细胞学说推广到动物界，认为动物也由细胞构成。","1858年魏尔肖补充细胞来自细胞，即细胞只能由已有细胞分裂产生。"]},{"id":"ch01_fill_3","modI":0,"q":"细胞学说三原则：①所有有机体由________构成；②细胞是________的基本单位；③所有细胞来自________。","a":"一个或多个细胞,结构和功能,已有细胞的分裂","kp":"ch01_s0_5","oe":["细胞学说第一原则：所有有机体都由一个或多个细胞构成。","第二原则：细胞是生命体结构和功能的基本单位。","第三原则：所有细胞都来自已有细胞的分裂，即细胞来自细胞。"]},{"id":"ch01_fill_4","modI":1,"q":"细胞的基本共性：都具有选择透性的________、遗传物质________、合成蛋白质的________。","a":"质膜(plasma membrane),双链DNA,核糖体","kp":"ch01_s1_0","oe":["所有细胞都具有选择透性的质膜，将细胞与外界环境分隔开。","细胞遗传物质均为双链DNA，保证遗传信息的稳定传递。","所有细胞都含核糖体，是合成蛋白质的场所，体现细胞基本共性。"]},{"id":"ch01_fill_5","modI":2,"q":"原核细胞没有真正的细胞核，只有________；遗传信息量少，一般含________个基因。","a":"拟核,1000-4000","kp":"ch01_s2_2","oe":["原核细胞无真正细胞核，只有无膜包裹的拟核区域含DNA。","原核细胞遗传信息量少，一般含1000~4000个基因。"]},{"id":"ch01_fill_6","modI":2,"q":"原核细胞分为两个亚门：________和________；已知最小的细胞是________(0.1~0.3μm)。","a":"真细菌,古细菌,支原体(Mycoplasma)","kp":"ch01_s2_3","oe":["原核细胞分为真细菌和古细菌两个亚门，二者在遗传与代谢上有别。","古细菌是另一亚门，多生活在极端环境，细胞壁组成与真细菌不同。","支原体是最小的细胞，直径约0.1~0.3μm，且无细胞壁。"]},{"id":"ch01_fill_7","modI":2,"q":"真核细胞遗传物质由________和蛋白质组成染色体；原核仅一个________、________的DNA染色体。","a":"DNA,单链,环状裸露","kp":"ch01_s2_7","oe":["真核细胞遗传物质是DNA，与组蛋白等蛋白质结合形成染色体。","原核细胞仅一个DNA染色体，按教材表述为单链，信息量远少于真核。","该DNA呈环状、裸露，不与蛋白质结合，集中于拟核区。"]},{"id":"ch01_fill_8","modI":2,"q":"原核细胞进行________(无丝)分裂；真核细胞进行________。","a":"简单,有丝分裂","kp":"ch01_s2_0","oe":["原核细胞以简单(无丝)分裂方式增殖，无纺锤体和核膜变化。","真核细胞主要进行有丝分裂，保证遗传物质均等分配到子细胞。"]},{"id":"ch01_fill_9","modI":3,"q":"大肠杆菌基因组约________个基因(1997年测序)；酵母编码约________个蛋白质。","a":"4288,6200","kp":"ch01_s3_1","oe":["1997年完成大肠杆菌基因组测序，其约含4288个基因。","酵母基因组编码约6200个蛋白质，是重要的真核模式生物。"]},{"id":"ch01_fill_10","modI":3,"q":"秀丽隐杆线虫成体有________个体细胞，发育中________个细胞发生凋亡；相关研究获________年诺贝尔奖。","a":"959,131,2002(细胞凋亡)/2006(RNAi)","kp":"ch01_s3_5","oe":["秀丽隐杆线虫成体共有959个体细胞，且数目恒定。","其发育过程中有131个细胞按程序发生凋亡。","细胞凋亡相关研究获2002年诺贝尔生理学或医学奖。"]},{"id":"ch01_fill_11","modI":3,"q":"控制果蝇眼发育的基因是________，其脊椎动物同源基因是________；后者缺陷导致________。","a":"eyeless,Pax6,无虹膜症(aniridia)","kp":"ch01_s3_10","oe":["控制果蝇眼发育的关键基因是eyeless，其突变导致眼发育异常。","eyeless在脊椎动物中的同源基因为Pax6，功能高度保守。","Pax6缺陷可导致人类无虹膜症，说明眼发育机制高度保守。"]},{"id":"ch01_fill_12","modI":3,"q":"斑马鱼基因与人类相似度达________%，是研究________发育机制(尤其心血管)的理想模式脊椎动物。","a":"87,脊椎动物","kp":"ch01_s3_21","oe":["斑马鱼基因与人类相似度达87%，是重要的模式生物。","斑马鱼是研究脊椎动物发育机制(尤其心血管)的理想模式动物。"]}],"short":[{"id":"ch01_short_1","modI":0,"q":"简述细胞学说的建立过程及其三个基本原则。","a":"【建立过程】\n①1838年德国植物学家施莱登(M.J.Schleiden)：植物组织虽结构差异大但都由细胞构成，植物胚由单个细胞产生。\n②1839年德国动物学家施旺(Theodor Schwann)《关于动植物的结构和生长的一致性的显微研究》：地球生物都由细胞构成；所有生活细胞结构类似。\n③1858年德国病理学家魏尔肖(Rudolf Virchow)补充第三条：所有细胞都来自已有细胞的分裂。\n\n【三个基本原则】\n1. All organisms are composed of one or more cells——所有有机体都由一个或多个细胞构成(病毒除外)；\n2. The cell is the basic unit of structure and function——细胞是所有有机体结构和功能的基本单位；\n3. Cells can arise only by division from preexisting cells——所有细胞都来自已有细胞的分裂。\n\n【意义】\n细胞1665年发现后170年无大发展，因未上升为理论。细胞学说创立后细胞学突飞猛进，1875-1900成为经典时期。","kp":"ch01_s0_5"},{"id":"ch01_short_2","modI":2,"q":"比较原核细胞与真核细胞的主要区别。","a":"原核细胞 vs 真核细胞：\n\n①细胞核：原核无核膜核仁，只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核仅一个单链、环状、裸露DNA染色体，遗传信息量少(1000-4000基因)；真核有大量由DNA和蛋白质组成的染色体，DNA/RNA多得多(人DNA总长1m)。\n③转录翻译：原核无核膜→边转录边翻译；真核分室化→核内复制转录、胞质翻译。\n④细胞器：原核无膜被细胞器；真核有膜被细胞器(内质网、高尔基体、线粒体、叶绿体等)。\n⑤细胞骨架：原核无；真核有细胞骨架(细胞质骨架/核骨架/膜骨架)。\n⑥分裂：原核简单(无丝)分裂；真核有丝分裂。\n⑦鞭毛：原核由flagellin组成；真核为9+2微管(tubulin+dynein)。\n⑧大小：原核小(支原体0.1~0.3μm)；真核大而复杂。\n\n【共同点】都有细胞膜、DNA和RNA、核糖体；都是生命基本结构单位、能分裂繁殖和遗传。","kp":"ch01_s2_0"},{"id":"ch01_short_3","modI":1,"q":"简述细胞的基本性质(共性与特性)。","a":"细胞的基本性质：\n\n【结构共性】\n①都具有选择透性的质膜(plasma membrane)；\n②都具有遗传物质双链DNA(原核为裸露拟核，真核包裹在细胞核中)；\n③都有核糖体(Ribosome)合成蛋白质；\n④化学组成元素基本相同(C、H、O、N、P、S等)。\n\n【功能共性】\n⑤都能进行物质和能量的新陈代谢，都由酶控制化学反应，需要和利用能量(能量几乎都来自太阳)；\n⑥都具运动性——细胞内物质运输及细胞整体运动；\n⑦都能自我增殖和遗传(一分为二)，体外培养仍可增殖(如HeLa细胞系)。\n\n【大小】以μm、nm为单位；细胞核5-10μm，线粒体约2μm；人体卵细胞约200μm，是最大的人体细胞之一。","kp":"ch01_s1_0"},{"id":"ch01_short_4","modI":2,"q":"简述真核细胞的结构体系及其意义。","a":"真核细胞的结构体系：\n\n【生物膜体系】\n质膜、核膜、膜被细胞器(高尔基体、内质网、叶绿体、线粒体等)，实现细胞分室化、区域化。\n意义：核内进行DNA复制、转录，成熟mRNA出核，细胞质进行蛋白质合成——分工更精细、效率更高。\n\n【细胞骨架体系】\n由相关骨架蛋白组成的充满整个细胞的网络结构，包括细胞质骨架、细胞核骨架、细胞膜骨架。\n功能：①维持细胞的一定形态；②细胞内物质运输的轨道；③使细胞内基质区域化；④帮助细胞移动或行走。\n\n【意义】\n生物膜体系与细胞骨架体系共同支撑真核细胞高度分化的结构与功能，是真核细胞比原核细胞复杂得多的根本原因。","kp":"ch01_s2_10"},{"id":"ch01_short_5","modI":3,"q":"列举5种常用模式生物及其作为模式生物的主要优点。","a":"常用模式生物及优点：\n\n①大肠杆菌(E. coli)：繁殖快(20-30min/代)，基因组简单(约4288基因，1997测序)，表达量高(5-30%)，常用作蛋白表达系统；DNA复制/转录/翻译机制最初在其阐明。\n\n②酿酒酵母(S. cerevisiae)：最小真核模式生物，基因组小(约6200蛋白，1996测序)，单倍体二倍体均可生长，含大量与人同源蛋白，研究细胞周期/凋亡。\n\n③拟南芥(A. thaliana)：基因组小(1.2亿bp，5条染色体)，世代短(8-10周)，首个完成全基因组测序的被子植物。\n\n④秀丽隐杆线虫(C. elegans)：成体959个体细胞，细胞命运精确可预测，体壁透明，凋亡机制保守(2002诺贝尔奖)；RNAi(2006诺贝尔奖)。\n\n⑤果蝇(D. melanogaster)：基因组约13600基因，研究胚胎发育和染色体；eyeless/Pax6控制眼发育。\n\n⑥小鼠(Mus musculus)：进化上最接近人类，用于研究哺乳动物遗传/免疫/发育，与人基因高度相似(Kit白斑)。\n\n⑦斑马鱼(Danio rerio)：模式脊椎动物，胚胎透明，基因与人类87%相似，研究心血管发育。\n\n【共同基础】由共同祖先进化而来，重要功能基因高度保守，信息可外推至其它生物。","kp":"ch01_s3_0"},{"id":"ch01_short_6","modI":1,"q":"为什么说细胞是生命活动的基本单位？","a":"细胞是生命活动基本单位的理由：\n\n【结构上】\n①所有有机体都由一个或多个细胞构成(病毒除外)；\n②细胞具有选择透性质膜，是相对独立的结构单位；\n③细胞具有遗传物质DNA和核糖体，能自我复制和合成蛋白质。\n\n【功能上】\n①细胞能进行物质和能量的新陈代谢，由酶催化各种化学反应；\n②细胞能自我增殖和遗传(一分为二)，体外培养仍可增殖；\n③细胞具运动性，能进行物质运输和整体运动；\n④一切生命现象(生长、发育、繁殖、遗传、变异、代谢)都以细胞为基础。\n\n【理论支持】\n威尔逊名言：'一切生命的关键问题都要到细胞中去寻找答案'。细胞学说确立细胞是生物结构和功能的基本单位，细胞生物学成为生命科学的核心与汇聚点。\n\n【结论】\n细胞既是结构单位又是功能单位，是生命活动的基本单位。","kp":"ch01_s1_0"}],"calc":[{"id":"ch01_calc_1","modI":3,"q":"论述模式生物在细胞生物学研究中的意义,并说明为什么可以用简单生物研究人类细胞规律。","a":"模式生物是细胞生物学研究的基石,其信息可外推至人类","steps":"【模式生物的定义与选择标准】\n①由共同祖先进化而来；\n②重要功能基因在进化上高度保守；\n③易培养、繁殖快、基因组简单、遗传背景清楚。\n\n【为什么可以外推】\n①所有生物有共同祖先→基本细胞过程(DNA复制、转录、翻译、细胞周期、凋亡)高度保守；\n②例证：\n  • 人Cdc2与裂殖酵母63%、芽殖酵母58%同源→细胞周期保守；\n  • 线虫凋亡基因在哺乳动物有同源基因→凋亡机制保守；\n  • 果蝇eyeless与人Pax6同源→眼发育保守；\n  • 人鼠Kit基因突变均致白斑→基因功能保守。\n\n【意义】\n①用简单生物(大肠杆菌/酵母/线虫/果蝇/拟南芥/斑马鱼/小鼠)研究基因功能，成本低、周期短；\n②获得的规律可应用于较难研究的生物(如人类)；\n③模式生物推动了多项诺贝尔奖发现(线虫凋亡2002、RNAi 2006等)；\n④是理解人类疾病机制、开发药物的重要工具(如斑马鱼药物实验87%适用于人类)。\n\n【结论】\n进化保守性使模式生物研究具有普遍意义。","kp":"ch01_s3_0"},{"id":"ch01_calc_2","modI":2,"q":"论述原核细胞与真核细胞的分界为何是细胞生物学最重要的分类之一。","a":"原核/真核的分界反映了细胞结构与进化水平的根本差异","steps":"【结构差异】\n①核：原核无核膜核仁只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核单链环状裸露DNA；真核DNA+蛋白组成染色体。\n③细胞器：原核无膜被细胞器；真核有内膜系统(内质网/高尔基/线粒体/叶绿体等)。\n④细胞骨架：原核无；真核有。\n⑤转录翻译：原核边转录边翻译；真核分室化(核内转录、胞质翻译)。\n\n【进化意义】\n①原核细胞起源于35亿年前；真核细胞起源于15亿年前；\n②生命树分三支：古细菌、细菌、真核生物——古细菌更接近真核；\n③内膜系统的形成是真核细胞由低等到高等发展的反映。\n\n【功能意义】\n①分室化使真核细胞分工精细、效率高，能支持更大更复杂的细胞；\n②原核细胞结构简单、遗传信息量少(1000-4000基因)，但繁殖快、适应性强。\n\n【结论】\n原核/真核的分界是理解细胞结构、功能、进化、疾病的基础，故为最重要的分类之一。","kp":"ch01_s2_0"},{"id":"ch01_calc_3","modI":0,"q":"论述细胞学说的建立对细胞生物学发展的推动作用。","a":"细胞学说将零散的观察上升为理论,极大推动了细胞学发展","steps":"【建立前】\n①1665年胡克发现细胞；1674年列文虎克观察活细胞；\n②但此后约170年细胞学没有大发展；\n③原因：实验观察没有上升为理论。\n\n【建立】\n①1838施莱登(植物)、1839施旺(动物)提出细胞学说前两条；\n②1858魏尔肖补充第三条(细胞来自细胞)；\n③三原则：生物由细胞构成；细胞是基本单位；细胞来自细胞。\n\n【推动作用】\n①细胞科学是实验科学，既依赖实验观察又有待理论升华；\n②细胞学说创立后，细胞学突飞猛进；\n③19世纪最后25年(1875-1900)成为细胞学经典时期：原生质理论、细胞分裂(有丝/减数)、细胞器(中心体/染色体/线粒体/高尔基体)相继发现；\n④1900-1953实验细胞学时期：细胞遗传学、细胞生理学、细胞化学；\n⑤进而发展到超微结构、分子细胞生物学。\n\n【结论】\n细胞学说的建立是细胞生物学从描述走向理论、从静态走向动态的转折点。","kp":"ch01_s0_1"}],"term":[{"id":"ch01_term_1","modI":0,"term":"细胞学说(Cell Theory)","def":"①关于细胞是生物体基本单位的学说，由施莱登(1838)和施旺(1839)建立、魏尔肖(1858)补充（定义）。②三个基本原则：所有有机体由一个或多个细胞构成(病毒除外)；细胞是结构和功能的基本单位；所有细胞来自已有细胞的分裂（内容）。③意义：使细胞学从零散观察上升为理论，推动1875-1900细胞学经典时期的到来（意义）。","kps":"踩分点:①建立者(1分)②三原则(2分)③意义(1分)","kp":"ch01_s0_5"},{"id":"ch01_term_2","modI":2,"term":"原核细胞(Prokaryotic Cell)","def":"①没有真正细胞核(无核膜核仁，只有拟核)的细胞，进化地位较低（定义）。②特点：遗传信息量少(1000-4000基因)；内部结构简单，无膜被细胞器和细胞骨架；DNA为单链环状裸露；边转录边翻译；简单分裂；鞭毛由flagellin组成（特点）。③分为真细菌和古细菌两个亚门；代表：细菌、蓝藻、支原体(最小细胞0.1~0.3μm)、产甲烷菌（分类）。","kps":"踩分点:①定义(1分)②特点(2分)③分类/代表(1分)","kp":"ch01_s2_2"},{"id":"ch01_term_3","modI":2,"term":"真核细胞(Eukaryotic Cell)","def":"①具有核膜包被的细胞核和膜被细胞器的细胞（定义）。②特点：有细胞核、大量DNA-蛋白染色体、内膜系统(分室化)、细胞骨架；核内复制转录、胞质翻译；有丝分裂；鞭毛为9+2微管结构(tubulin+dynein)（特点）。③代表：原生生物、真菌、植物、动物；最早真核细胞起源于15亿年前（分类）。","kps":"踩分点:①定义(1分)②特点(2分)③分类(1分)","kp":"ch01_s2_10"},{"id":"ch01_term_4","modI":3,"term":"模式生物(Model Organism)","def":"①用于研究基本生命规律、信息可外推至其它生物的易研究物种（定义）。②选择标准：共同祖先、重要基因进化保守、易培养繁殖快基因组简单（标准）。③常用：大肠杆菌、酿酒酵母、拟南芥、秀丽隐杆线虫、果蝇、小鼠、斑马鱼（举例）。④意义：成本低周期短，推动多项重大发现(线虫凋亡2002、RNAi 2006)（意义）。","kps":"踩分点:①定义(1分)②选择标准(1分)③举例(1分)④意义(1分)","kp":"ch01_s3_0"},{"id":"ch01_term_5","modI":2,"term":"细胞骨架(Cytoskeleton)","def":"①由相关骨架蛋白组成的、充满整个细胞的网络结构（定义）。②包括细胞质骨架、细胞核骨架、细胞膜骨架（组成）。③功能：维持细胞形态；细胞内物质运输的轨道；使基质区域化；帮助细胞移动或行走（功能）。④是真核细胞特有的结构（意义）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(2分)④真核特有(1分)","kp":"ch01_s2_8"},{"id":"ch01_term_6","modI":1,"term":"质膜(Plasma Membrane)","def":"①细胞表面具有选择透性的生物膜，由膜脂、蛋白质、糖类组成（定义）。②功能：屏障和半透膜，维护细胞内微环境相对稳定；细胞与外界进行物质、能量、信息交换（功能）。③进化意义：质膜的形成是非细胞生命(病毒)与细胞生物的重要分界点（意义）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)④进化意义(1分)","kp":"ch01_s1_0"},{"id":"ch01_term_7","modI":2,"term":"细胞分室化(Compartmentalization)","def":"①真核细胞内由生物膜体系将细胞分成不同区域/细胞器的现象（定义）。②基础：内膜系统(质膜、核膜、膜被细胞器)（基础）。③意义：DNA复制、转录在核内进行，成熟mRNA出核，蛋白质合成在细胞质进行——分工精细、效率高（意义）。","kps":"踩分点:①定义(1分)②基础(1分)③意义(2分)","kp":"ch01_s2_6"},{"id":"ch01_term_8","modI":1,"term":"HeLa细胞系","def":"①1951年从黑人妇女Henrietta Lacks的宫颈癌细胞分离建立的人类细胞系（定义）。②是首例长期保存并运用至今的人类细胞系（意义）。③证明细胞在体外培养条件下仍可自我增殖和遗传（应用）。","kps":"踩分点:①定义(1分)②首例意义(2分)③体外增殖(1分)","kp":"ch01_s1_1"},{"id":"ch01_term_9","modI":2,"term":"支原体(Mycoplasma)","def":"①已知最小的细胞，直径仅0.1~0.3μm（定义）。②属真细菌（分类）。③无细胞壁，是研究最小生命单位与细胞膜结构的模型（意义）。","kps":"踩分点:①定义(1分)②大小(1分)③分类(1分)④意义(1分)","kp":"ch01_s2_3"},{"id":"ch01_term_10","modI":2,"term":"古细菌(Archaebacteria)","def":"①古核细胞(古核生物)，与原核细胞、真核生物并列为三大类，通常生活在极端环境（定义）。②环境：浓海水、无空气海洋沉积层、酸性火山热泉、污水淤泥、食草动物消化管（环境）。③代表：产甲烷菌(利用CO2+H2合成甲烷)、硫氧化菌、盐生菌（举例）。④进化上更接近真核生物（意义）。","kps":"踩分点:①定义(1分)②环境(1分)③举例(1分)④进化地位(1分)","kp":"ch01_s2_4"},{"id":"ch01_term_11","modI":3,"term":"eyeless/Pax6","def":"①控制无脊椎动物和脊椎动物眼形成的一对直系同源基因（定义）。②eyeless在果蝇、Pax6在脊椎动物，编码高度相关蛋白，源自同一祖先基因（同源）。③功能保守：eyeless失活致果蝇缺眼；人Pax6不足致无虹膜症(aniridia)（功能）。④Ey可触发整个眼睛器官生成，是发育主控基因的经典例子（意义）。","kps":"踩分点:①定义(1分)②同源性(1分)③功能保守(1分)④意义(1分)","kp":"ch01_s3_11"},{"id":"ch01_term_12","modI":3,"term":"秀丽隐杆线虫(C. elegans)","def":"①重要的模式生物，成体仅959个体细胞，细胞命运精确可预测（定义）。②发育：受精卵产生1090个细胞，131个发生凋亡（发育）。③特点：体壁透明、世代短(25℃约2.5天)、易遗传分析（特点）。④贡献：细胞凋亡(2002诺贝尔奖)、RNAi(2006诺贝尔奖)；凋亡机制从线虫到人保守（意义）。","kps":"踩分点:①定义(1分)②发育数字(1分)③特点(1分)④诺贝尔奖/意义(2分)","kp":"ch01_s3_5"},{"id":"ch01_term_13","modI":1,"term":"细胞的基本性质","def":"①所有细胞共有的结构与功能特征（定义）。②结构共性：选择透性质膜、双链DNA、核糖体、相同化学元素(C/H/O/N/P/S)（结构）。③功能共性：新陈代谢(酶催化)、能量利用(来自太阳)、运动性、自我增殖和遗传（功能）。④是真核与原核细胞的共同点（意义）。","kps":"踩分点:①定义(1分)②结构共性(1分)③功能共性(2分)④共同点(1分)","kp":"ch01_s1_0"},{"id":"ch01_term_14","modI":2,"term":"生命树的三分支","def":"①将生物划分为三个主要分支的进化树（定义）。②分支：古核生物(Archaea)、细菌(Bacteria)、真核生物(Eukarya)（三大类/域）。③意义：古核细胞与细菌虽同属原核，但进化上分属不同分支，古核细胞更接近真核生物（意义）。","kps":"踩分点:①定义(1分)②三支(2分)③进化意义(2分)","kp":"ch01_s2_1"},{"id":"ch01_term_15","modI":3,"term":"斑马鱼(Danio rerio)","def":"①理想的模式脊椎动物（定义）。②特点：胚胎透明、发育快、基因组约为小鼠/人类一半、世代约3个月（特点）。③基因与人类相似度87%，中枢神经/内脏/视觉系统分子水平85%相似，尤其心血管系统（相似性）。④应用：药物实验多适用人类，研究脊椎动物发育(尤其心血管)（应用）。","kps":"踩分点:①定义(1分)②特点(1分)③相似性(1分)④应用(1分)","kp":"ch01_s3_17"}],"preview":{"main":"本章是细胞生物学的绪论，从细胞发现和细胞学说的建立讲起，梳理学科发展简史，并重点比较原核细胞与真核细胞的基本性质、结构差异及共同点，最后介绍几种模式生物。它是后续各章学习的基础框架，帮助你建立'细胞是什么、分几类、怎么研究'的整体认识。","questions":["细胞是如何被发现的？胡克和列文虎克各自做出了什么关键贡献？","细胞学说的三个基本原则是什么？它为什么在细胞生物学史上具有里程碑意义？","原核细胞与真核细胞在结构、遗传物质、繁殖和运动方式上有哪些主要区别与共同点？","真核细胞的结构体系包括哪些基本组成部分？它们如何分工协作？","为什么大肠杆菌、啤酒酵母、拟南芥、线虫、果蝇、小鼠和斑马鱼会成为细胞生物学研究的模式材料？","从细胞发现到实验细胞学时期，研究方法和关注问题发生了怎样的演变？"]},"appcards":[{"front":"简述细胞学说的建立过程及其三个基本原则。","back":"【建立过程】\n①1838年德国植物学家施莱登(M.J.Schleiden)：植物组织虽结构差异大但都由细胞构成，植物胚由单个细胞产生。\n②1839年德国动物学家施旺(Theodor Schwann)《关于动植物的结构和生长的一致性的显微研究》：地球生物都由细胞构成；所有生活细胞结构类似。\n③1858年德国病理学家魏尔肖(Rudolf Virchow)补充第三条：所有细胞都来自已有细胞的分裂。\n\n【三个基本原则】\n1. All organisms are composed of one or more cells——所有有机体都由一个或多个细胞构成(病毒除外)；\n2. The cell is the basic unit of structure and function——细胞是所有有机体结构和功能的基本单位；\n3. Cells can arise only by division from preexisting cells——所有细胞都来自已有细胞的分裂。\n\n【意义】\n细胞1665年发现后170年无大发展，因未上升为理论。细胞学说创立后细胞学突飞猛进，1875-1900成为经典时期。","points":"","mod":0,"modName":"模块一：细胞生物学发展简史","level":"掌握","src":"题库"},{"front":"比较原核细胞与真核细胞的主要区别。","back":"原核细胞 vs 真核细胞：\n\n①细胞核：原核无核膜核仁，只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核仅一个单链、环状、裸露DNA染色体，遗传信息量少(1000-4000基因)；真核有大量由DNA和蛋白质组成的染色体，DNA/RNA多得多(人DNA总长1m)。\n③转录翻译：原核无核膜→边转录边翻译；真核分室化→核内复制转录、胞质翻译。\n④细胞器：原核无膜被细胞器；真核有膜被细胞器(内质网、高尔基体、线粒体、叶绿体等)。\n⑤细胞骨架：原核无；真核有细胞骨架(细胞质骨架/核骨架/膜骨架)。\n⑥分裂：原核简单(无丝)分裂；真核有丝分裂。\n⑦鞭毛：原核由flagellin组成；真核为9+2微管(tubulin+dynein)。\n⑧大小：原核小(支原体0.1~0.3μm)；真核大而复杂。\n\n【共同点】都有细胞膜、DNA和RNA、核糖体；都是生命基本结构单位、能分裂繁殖和遗传。","points":"","mod":2,"modName":"模块三：原核细胞与真核细胞","level":"掌握","src":"题库"},{"front":"简述细胞的基本性质(共性与特性)。","back":"细胞的基本性质：\n\n【结构共性】\n①都具有选择透性的质膜(plasma membrane)；\n②都具有遗传物质双链DNA(原核为裸露拟核，真核包裹在细胞核中)；\n③都有核糖体(Ribosome)合成蛋白质；\n④化学组成元素基本相同(C、H、O、N、P、S等)。\n\n【功能共性】\n⑤都能进行物质和能量的新陈代谢，都由酶控制化学反应，需要和利用能量(能量几乎都来自太阳)；\n⑥都具运动性——细胞内物质运输及细胞整体运动；\n⑦都能自我增殖和遗传(一分为二)，体外培养仍可增殖(如HeLa细胞系)。\n\n【大小】以μm、nm为单位；细胞核5-10μm，线粒体约2μm；人体卵细胞约200μm，是最大的人体细胞之一。","points":"","mod":1,"modName":"模块二：细胞的基本性质","level":"掌握","src":"题库"},{"front":"简述真核细胞的结构体系及其意义。","back":"真核细胞的结构体系：\n\n【生物膜体系】\n质膜、核膜、膜被细胞器(高尔基体、内质网、叶绿体、线粒体等)，实现细胞分室化、区域化。\n意义：核内进行DNA复制、转录，成熟mRNA出核，细胞质进行蛋白质合成——分工更精细、效率更高。\n\n【细胞骨架体系】\n由相关骨架蛋白组成的充满整个细胞的网络结构，包括细胞质骨架、细胞核骨架、细胞膜骨架。\n功能：①维持细胞的一定形态；②细胞内物质运输的轨道；③使细胞内基质区域化；④帮助细胞移动或行走。\n\n【意义】\n生物膜体系与细胞骨架体系共同支撑真核细胞高度分化的结构与功能，是真核细胞比原核细胞复杂得多的根本原因。","points":"","mod":2,"modName":"模块三：原核细胞与真核细胞","level":"掌握","src":"题库"},{"front":"列举5种常用模式生物及其作为模式生物的主要优点。","back":"常用模式生物及优点：\n\n①大肠杆菌(E. coli)：繁殖快(20-30min/代)，基因组简单(约4288基因，1997测序)，表达量高(5-30%)，常用作蛋白表达系统；DNA复制/转录/翻译机制最初在其阐明。\n\n②酿酒酵母(S. cerevisiae)：最小真核模式生物，基因组小(约6200蛋白，1996测序)，单倍体二倍体均可生长，含大量与人同源蛋白，研究细胞周期/凋亡。\n\n③拟南芥(A. thaliana)：基因组小(1.2亿bp，5条染色体)，世代短(8-10周)，首个完成全基因组测序的被子植物。\n\n④秀丽隐杆线虫(C. elegans)：成体959个体细胞，细胞命运精确可预测，体壁透明，凋亡机制保守(2002诺贝尔奖)；RNAi(2006诺贝尔奖)。\n\n⑤果蝇(D. melanogaster)：基因组约13600基因，研究胚胎发育和染色体；eyeless/Pax6控制眼发育。\n\n⑥小鼠(Mus musculus)：进化上最接近人类，用于研究哺乳动物遗传/免疫/发育，与人基因高度相似(Kit白斑)。\n\n⑦斑马鱼(Danio rerio)：模式脊椎动物，胚胎透明，基因与人类87%相似，研究心血管发育。\n\n【共同基础】由共同祖先进化而来，重要功能基因高度保守，信息可外推至其它生物。","points":"","mod":3,"modName":"模块四：模式生物","level":"掌握","src":"题库"},{"front":"为什么说细胞是生命活动的基本单位？","back":"细胞是生命活动基本单位的理由：\n\n【结构上】\n①所有有机体都由一个或多个细胞构成(病毒除外)；\n②细胞具有选择透性质膜，是相对独立的结构单位；\n③细胞具有遗传物质DNA和核糖体，能自我复制和合成蛋白质。\n\n【功能上】\n①细胞能进行物质和能量的新陈代谢，由酶催化各种化学反应；\n②细胞能自我增殖和遗传(一分为二)，体外培养仍可增殖；\n③细胞具运动性，能进行物质运输和整体运动；\n④一切生命现象(生长、发育、繁殖、遗传、变异、代谢)都以细胞为基础。\n\n【理论支持】\n威尔逊名言：'一切生命的关键问题都要到细胞中去寻找答案'。细胞学说确立细胞是生物结构和功能的基本单位，细胞生物学成为生命科学的核心与汇聚点。\n\n【结论】\n细胞既是结构单位又是功能单位，是生命活动的基本单位。","points":"","mod":1,"modName":"模块二：细胞的基本性质","level":"掌握","src":"题库"},{"front":"论述模式生物在细胞生物学研究中的意义,并说明为什么可以用简单生物研究人类细胞规律。","back":"【模式生物的定义与选择标准】\n①由共同祖先进化而来；\n②重要功能基因在进化上高度保守；\n③易培养、繁殖快、基因组简单、遗传背景清楚。\n\n【为什么可以外推】\n①所有生物有共同祖先→基本细胞过程(DNA复制、转录、翻译、细胞周期、凋亡)高度保守；\n②例证：\n  • 人Cdc2与裂殖酵母63%、芽殖酵母58%同源→细胞周期保守；\n  • 线虫凋亡基因在哺乳动物有同源基因→凋亡机制保守；\n  • 果蝇eyeless与人Pax6同源→眼发育保守；\n  • 人鼠Kit基因突变均致白斑→基因功能保守。\n\n【意义】\n①用简单生物(大肠杆菌/酵母/线虫/果蝇/拟南芥/斑马鱼/小鼠)研究基因功能，成本低、周期短；\n②获得的规律可应用于较难研究的生物(如人类)；\n③模式生物推动了多项诺贝尔奖发现(线虫凋亡2002、RNAi 2006等)；\n④是理解人类疾病机制、开发药物的重要工具(如斑马鱼药物实验87%适用于人类)。\n\n【结论】\n进化保守性使模式生物研究具有普遍意义。","points":"","mod":3,"modName":"模块四：模式生物","level":"掌握","src":"题库"},{"front":"论述原核细胞与真核细胞的分界为何是细胞生物学最重要的分类之一。","back":"【结构差异】\n①核：原核无核膜核仁只有拟核；真核有核膜包被的细胞核。\n②遗传物质：原核单链环状裸露DNA；真核DNA+蛋白组成染色体。\n③细胞器：原核无膜被细胞器；真核有内膜系统(内质网/高尔基/线粒体/叶绿体等)。\n④细胞骨架：原核无；真核有。\n⑤转录翻译：原核边转录边翻译；真核分室化(核内转录、胞质翻译)。\n\n【进化意义】\n①原核细胞起源于35亿年前；真核细胞起源于15亿年前；\n②生命树分三支：古细菌、细菌、真核生物——古细菌更接近真核；\n③内膜系统的形成是真核细胞由低等到高等发展的反映。\n\n【功能意义】\n①分室化使真核细胞分工精细、效率高，能支持更大更复杂的细胞；\n②原核细胞结构简单、遗传信息量少(1000-4000基因)，但繁殖快、适应性强。\n\n【结论】\n原核/真核的分界是理解细胞结构、功能、进化、疾病的基础，故为最重要的分类之一。","points":"","mod":2,"modName":"模块三：原核细胞与真核细胞","level":"掌握","src":"题库"},{"front":"论述细胞学说的建立对细胞生物学发展的推动作用。","back":"【建立前】\n①1665年胡克发现细胞；1674年列文虎克观察活细胞；\n②但此后约170年细胞学没有大发展；\n③原因：实验观察没有上升为理论。\n\n【建立】\n①1838施莱登(植物)、1839施旺(动物)提出细胞学说前两条；\n②1858魏尔肖补充第三条(细胞来自细胞)；\n③三原则：生物由细胞构成；细胞是基本单位；细胞来自细胞。\n\n【推动作用】\n①细胞科学是实验科学，既依赖实验观察又有待理论升华；\n②细胞学说创立后，细胞学突飞猛进；\n③19世纪最后25年(1875-1900)成为细胞学经典时期：原生质理论、细胞分裂(有丝/减数)、细胞器(中心体/染色体/线粒体/高尔基体)相继发现；\n④1900-1953实验细胞学时期：细胞遗传学、细胞生理学、细胞化学；\n⑤进而发展到超微结构、分子细胞生物学。\n\n【结论】\n细胞学说的建立是细胞生物学从描述走向理论、从静态走向动态的转折点。","points":"","mod":0,"modName":"模块一：细胞生物学发展简史","level":"掌握","src":"题库"},{"front":"比较胡克与列文虎克在细胞发现史上的贡献有何异同？","back":"同：均为早期显微镜观察者，推动细胞发现；异：胡克1665年观察软木塞死细胞壁，首次命名cell；列文虎克1674年观察活细胞（血细胞、精子等），首次看到完整活细胞。","points":"胡克：死细胞壁、命名cell；列文虎克：活细胞、首次观察","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说细胞学说的建立离不开施莱登和施旺两人的工作？","back":"施莱登1838年提出植物由细胞构成、胚由单细胞产生；施旺1839年将其扩展到动物，提出动植物结构生长一致性；两人共同奠定细胞学说。","points":"施莱登：植物；施旺：动物；共同建立","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"细胞学说三个基本原则有什么意义？","back":"①所有有机体由一个或多个细胞构成；②细胞是生命基本单位；③细胞来自已有细胞；意义：统一了生物界的结构基础，推动生物学成为实验科学。","points":"三条原则；统一生物界；推动实验科学","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较经典时期与实验细胞学时期研究特点的异同。","back":"同：均研究细胞结构与功能；异：经典时期以形态观察为主，发现分裂和细胞器；实验时期用实验手段研究生理、生化、遗传发育机制。","points":"经典：形态观察；实验：实验手段；功能机制","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说细胞分裂和细胞器的发现奠定了细胞结构学基础？","back":"有丝分裂、减数分裂揭示细胞增殖机制；中心体、染色体、线粒体、高尔基体等细胞器揭示内部结构分工；二者共同构成细胞结构学核心内容。","points":"分裂：增殖机制；细胞器：结构分工；结构学基础","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明实验细胞学时期的三大分支及其研究内容。","back":"细胞遗传：染色体结构与基因表达；细胞生理：营养、代谢等生理功能；细胞化学：细胞化学成分与反应；三者从不同角度研究细胞。","points":"细胞遗传；细胞生理；细胞化学；各举内容","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较原核细胞与真核细胞在结构上的共同点。","back":"都有细胞膜；都有DNA和RNA；都有核糖体；都能分裂繁殖和遗传；都是生命基本结构单位。","points":"细胞膜；DNA/RNA；核糖体；分裂遗传","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么原核细胞没有真正的细胞核？","back":"原核细胞无核膜和核仁，DNA裸露呈环状，集中在拟核区；真核细胞有核膜包被的细胞核，DNA与蛋白质结合成染色体。","points":"无核膜核仁；拟核；环状裸露DNA","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较原核与真核细胞在遗传物质形式与数量上的差异。","back":"形式：原核为单链环状裸露DNA；真核为DNA与蛋白质组成的染色体。数量：真核DNA/RNA远多于原核，如酵母DNA 4.6mm，细菌0.25-3mm。","points":"原核：环状裸露；真核：染色体；数量真核多","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"原核与真核细胞在细胞质和繁殖方式上有何不同？","back":"细胞质：真核有膜包被细胞器和细胞骨架，原核无；核糖体大小不同。繁殖：真核有丝分裂，原核简单无丝分裂。","points":"细胞器/骨架；核糖体大小；有丝/无丝分裂","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较原核鞭毛与真核鞭毛的异同。","back":"同：均用于运动；异：原核鞭毛由flagellin组成，无9+2结构；真核鞭毛为9+2微管结构，由tubulin和dynein组成，运动机制不同。","points":"原核：flagellin；真核：9+2、tubulin、dynein","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说古核细胞更接近真核生物？","back":"古核与细菌同属原核，但进化上分属不同分支；古核在分子机制、遗传信息传递等方面更接近真核生物，生命树中与真核同源更近。","points":"进化分支不同；分子机制接近真核；生命树位置","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明原核细胞两个亚门及其代表生物。","back":"真细菌：支原体、蓝藻，常见或致病；古细菌：极端环境如浓海水、酸性热泉；支原体是最小细胞，仅0.1-0.3μm。","points":"真细菌：支原体/蓝藻；古细菌：极端环境；支原体最小","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"真核细胞的结构体系包括哪些？各有什么作用？","back":"细胞骨架：维持形态、运输轨道、区域化、帮助移动；生物膜体系：质膜和内膜系统，分隔区室；两者共同保证细胞复杂功能。","points":"细胞骨架；生物膜体系；各说作用","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么模式生物能用于研究人类基因功能？","back":"模式生物由共同祖先进化而来；重要功能基因高度保守；用易研究生物做模型，获得信息可推广到其他生物，包括人类。","points":"共同祖先；基因保守；信息可推广","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明大肠杆菌作为模式生物的优点。","back":"易培养、繁殖快，20-30min一代；基因组简单，约4288个基因，1997年测序完成；遗传背景清楚，成本低，便于大规模研究。","points":"繁殖快；基因组简单；测序完成；成本低","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较啤酒酵母与大肠杆菌作为模式生物的特点。","back":"同：均为常用模式生物；异：酵母是最小真核模式生物，含与人同源蛋白，基因组约6200蛋白，1996年测序；大肠杆菌为原核，基因组更小。","points":"酵母：真核、同源蛋白；大肠杆菌：原核；基因组大小","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"拟南芥作为植物模式生物有哪些优势？","back":"DNA量小，仅酵母3-4倍；8-10周产生大量后代，无明显季节性；基因组小1.2亿碱基对，单倍体5条染色体；便于遗传研究。","points":"DNA小；繁殖快；基因组小；染色体少","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么秀丽隐杆线虫适合研究细胞凋亡？","back":"发育中从受精卵产生1090个细胞，成体959个，131个细胞凋亡；细胞按可预设程序精确发育，便于追踪和遗传分析。","points":"1090→959；131凋亡；程序精确；便于追踪","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明果蝇在发育遗传研究中的作用。","back":"基因组约13600基因，测序完成；研究单个受精卵如何调控分化、发育成多细胞类型组成的成体；揭示胚胎和幼虫发育遗传机制。","points":"基因组测序；受精卵分化；发育遗传机制","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"小鼠作为哺乳动物模式生物有什么意义？","back":"进化上最接近人类；用于研究哺乳动物遗传、免疫、发育；通过遗传工程突变体检验基因必需性和功能，为人类疾病研究提供模型。","points":"接近人类；遗传免疫发育；基因突变体；人类疾病","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"斑马鱼作为模式脊椎动物有哪些优点？","back":"胚胎透明、发育快，前两周可跟踪每个细胞；基因组只有小鼠或人类一半；世代时间约3个月；属脊椎动物，消化、循环等系统与人类相似。","points":"胚胎透明；基因组小；世代短；脊椎动物","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞失去选择透性质膜会怎样？","back":"物质进出失控，细胞内环境无法维持；代谢紊乱、细胞肿胀或死亡；说明质膜选择透性是细胞基本共性之一。","points":"物质失控；内环境破坏；代谢紊乱；质膜重要性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若真核细胞核膜消失会有什么后果？","back":"遗传物质失去核膜保护，转录翻译时空分隔破坏；DNA易受损伤；细胞区室化紊乱；说明核膜对真核细胞遗传信息保护的重要性。","points":"失去保护；时空分隔破坏；DNA损伤；区室化紊乱","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明细胞功能共性中的新陈代谢和能量利用。","back":"所有细胞都由酶控制化学反应，需要和利用能量；如大肠杆菌利用葡萄糖产能，酵母发酵，线粒体氧化磷酸化；体现生命基本特征。","points":"酶控制反应；需要能量；举例大肠杆菌/酵母/线粒体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}],"jyq":[{"id":"jyq_ch01_1","q":"细胞学说创始人是和。","a":"施旺；施莱登。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch01_2","q":"根据细胞生物学研究的内容与你所掌握的生命科学知识，恰当地估计细胞生物学在生命科学中所处的地位以及它与其他学科的关系。","a":"次上研究细胞结构与功能，细胞增殖、分化、衰老与凋亡，细胞信号转导，真核细胞基因表达与调控，细胞起源与进化等内容。细胞生物学运用了近代物理、化学技术和分子生物学方法。它主要研究细胞各种组成部分的结构、功能及其相互作用；研究细胞总体的和动态的功能活动，包括细胞生长分裂、发育分化、遗传变异和演化，以及研究这些相互关系和功能活动的分子基础。因此，现代细胞生物学实际上是分子生物学与细胞生物学的结合，即细胞分子生物学。可见，细胞生物学的兴起是与分子生物学的发展不可分割的。从生命结构层次来看，细胞生物学介于分子生物学与个体生物学之间，同它们相互衔接、相互渗透。因此，细胞生物学是一门承上启下的学科，和分子生物学一起组成现代生命科学的基础。在我国基础科学发展规划中，细胞生物学与分子生物学、神经生物学和生态学并列为生命科学的四大基础学种。它广泛渗透到遗传学、发育生物学、生殖生物学、神经生物学和免疫生物学等的研究中，并同农业、医学和生物高技术发展有极其密切的关系。细胞生物学与其他学科之间的渗透日益明显，以医学为例。医学作为一门维持人类健康、防治人体疾病的应用性学科，同细胞生物学有着密切的关系。细胞生物学的新理论、新发现、新技术在医学方面的应用，极大地促进了医学的进步，如单克隆抗体的应用，使很多疾病的诊断简单而精确，使癌症等复杂疾病的治疗效果大大提高。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_3","q":"如何认识细胞学说在细胞学乃至生物学发展简史中的重要意义？","a":"答从细胞的发现到细胞生物学的建立，大约经历了300年的时间，这段历程一般分为以下五个阶段：①细胞的发现；②细胞学说的建立；③细胞学说的经典时期；④实验细胞学时期；5细胞生物学学科的形成与发展。细胞学说是1838一1839年间由德国的植物学家施莱登和动物学家施旺所提出，直到1858年才完善。它是关于生物有机体组成的学说，主要内容包括：①细胞是有机体，一切动植物都是由细胞发育而来，即生物是由细胞和细胞的产物所组成的；②所有细胞在结构和组成上基本相似；③生物体是通过其细胞的活动反映其功能；4新细胞是由已存在的细胞分裂而来的；5生物的疾病是因为其细胞机能失常。恩格斯对细胞学说的评价是：19世纪自然科学的三大发现之一。细胞学说、进化论、遗传学三大定律被称为现代生物学的三大基石，而细胞学说又是后两者的基石。.6，起源，动植物的产生、成长和构造的秘密被揭开了，从而为19世纪自然哲学领域中辩证唯物主义战胜形而上学的唯心主义，提供了一个有力的证据，为近代生物科学的发展接受有机界进化的观念准备了条件。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_4","q":"试简明扼要地分析细胞生物学学科形成的客观条件以及它今后发展的主要趋势。","a":"细胞生物学学科是经过科学家长时期的研究与探索，在理论研究与实验研究相结合的基础上逐渐形成的。对细胞超微结构的观察不仅对已知的细胞组成如线粒体、细胞膜、高尔基体、核膜、核仁、染色质与染色体的结构有了全新了解，而且发现了一些新的重要的细胞结构，如内质网、核糖体、溶酶体、核孔复合体与细胞骨架体系等，为细胞生物学学科早期的形成奠定了良好的基础。20世纪50～60年代以来，生物化学与细胞学的相互渗透与结合，细胞生物化学这一领域的快速发展，使人们对细胞结构与功能相结合的研究水平达到了前所未有的高度。最重要的是20世纪70年代以来，科学家将分子生物学的概念与技术引进细胞学，使人们能从分子水平来研究细胞的结构与功能，为细胞生物学这门学科的最后形成与建立创造了全新的局面。所以20世纪60年代提出细胞生物学这一概念，它是以细胞作为一切有机体进行生命活动的基本单位这一概念为出发点，在显微、亚显微、分子水平上研究细胞生命活动的基本规律的学科。细胞生物学的主要发展方向是细胞的分子生物学。随着研究手段的进步、研究的进一步深人，细胞生物学与分子生物学在许多领域相互交汇和融合，如细胞生命活动的调控、细胞器三维结构的研究等。因此，细胞生物学的概念被延伸为分子细胞生物学或细胞分子生物学。主要趋势可以概括为两点：一是基因与基因产物如何控制细胞的重要生命活动；二是基因产物，即蛋白质分子与其他生物分子如何构建与装配成细胞的结构，并行使细胞的有序的生命活动。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_5","q":"当前细胞生物学研究的热点课题中你最感兴趣的是哪些？","a":"为什么？当前细胞生物学研究的热点课题集中在：①细胞核、染色体以及基因表达的研究；②生物膜与细胞器的研究；③细胞骨架体系的研究；④细胞增殖及其调控；5细胞分化及其调控；6细胞的衰老与凋亡；7细胞的起源与进化；⑧细胞工程。如细胞凋亡就是当前生命科学研究中最热门的领域之一，近几年的研究已取得许多重大突破。对凋亡中的热点问题，包括细胞接受胞内外信号的刺激启动凋亡、胞内凋亡特异性蛋白酶的激活，细胞凋亡研究的新发现、新结果层出不穷，而细胞凋亡体系的建立与利用，在很大程度上促进了人们对凋亡机制的研究。对细胞凋亡机理的深入了解将有可能得到有关细胞起源、进化以及发育生物学的新的认识，并可对一些疾病包括癌症提供新的治疗方法和途径，如ca5PMe活化抑制剂已经表明可在几个病理条件下抑制非正常细胞凋亡，为可行的治疗方法带来了乐观的前景。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_6","q":"原核细胞和真核细胞相比，共有的基本特征中，哪一条描述是不正确的。A.都有细胞膜B.都有内质网C.都有核糖体D.都有两种核酸DNA和RNA","a":"B。","src":"中国科学院，2005年","kp":null},{"id":"jyq_ch01_7","q":"除极个别例外，所有细胞都具有细胞膜、细胞质和细胞核。","a":"错。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_8","q":"下列哪一组属于原核生物（）。A.病毒和支原体B.衣藻和细菌C.细菌和念珠菌D.放线菌和霉菌","a":"C。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_9","q":"列出原核细胞和真核细胞的主要差别。","a":"原核细胞和真核细胞的根本区别：①细胞膜系统的分化演变；②遗传信息量与遗传装置的扩增与复杂化。由于上述的根本差异，真核细胞的体积也相应扩增，细胞内部出现精密的网架结构一细胞骨架。二者的区别可分两部分进行比较：①结构与功能比较：真核细胞的生物膜将细胞分化为核和质两部分，细胞质又分化出各种细胞器，细胞骨架保证了细胞形态的合理排布与执行功能的有序性；②细胞遗传装置与表达方式的比较：核膜使扩增了的遗传信息与复杂的遗传装置相球进物攀表程威有平格的阶段性与区域性。","src":"浙江理工大学，2009年","kp":null},{"id":"jyq_ch01_10","q":"原核细胞与真核细胞在基因组成和生命活动方面有何不同？","a":"真核细胞与原核细胞的基因在组成和生命活动方面的差异主要是：①真核细胞的DNA分子有一条，分子较小，且储存的遗传信息量较少。②真核细胞的DNA呈线状，与蛋白质结合并被包装成高度凝集的染色质结构，保证了遗传信息的稳定性；DNA位于细胞核内，更有利于RNA前体进行有效的剪切和修饰，并为基因的表达提供方便。原核细胞的DNA位于细胞质中，呈环状，没有与蛋白质结合，裸露。③真核细胞的细胞器中也含有遗传物质DNA。线粒体和叶绿体中的DNA可编码线粒体mRNA、tRNA、rRNA，并能合成少量的线粒体蛋白质；原核细胞的细胞器中无DNA。④原核细胞DNA的复制，mRNA、rRNA、tRNA转录和蛋白质的合成可以同时在细胞质内连续进行，边转录边翻译，无需对mRNA进行加工。真核细胞的转录与翻译分开进行，整个过程具有严格的阶段性和区域性，是不连续的。真核细胞DNA的复制和各种RNA的转录发生在细胞核内，mRNA前体合成之后，在细胞核内经过剪接加工过程形成成熟的mRNA以后，必须运输到细胞质中才能翻译成蛋白质。5原核细胞的繁殖无明显的周期性，而且没有使遗传物质均等分配到子细胞的机制；真核细胞的繁殖具有明显的周期性，并且在细胞繁殖过程中形成有丝分裂器，使遗传物质均等地分配到子细胞中。6原核细胞的代谢形式主要是无氧呼吸，产生的能量较少；而真核细胞的代谢形式主要是有氧呼吸辅以无氧呼吸，可产生大量的能量。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch01_11","q":"如何理解“细胞是生命活动的基本单位”这一概念？","a":"答关于细胞的定义有多种提法，近年比较普遍的提法是：细胞是生命活动的基本单位。这一概念概括性较强，内涵也更有深度，要全面理解这一概念，应从以下五个方面出发。①一切有机体都由细胞构成，只有病毒是非细胞形态的生命体，细胞是构成有机体的基本单位。②细胞具有独立的、有序的自控化技术体系，细胞是代谢与功能的基本单位。③细胞是有机体生长与发育的基础。④细胞是遗传的基本单位，细胞具有遗传的全能性。5没有细胞就没有完整的生命。许多实验已经证明，若细胞结构的完整性受到破坏，就不能完成完整的生命活动。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_12","q":"“超级小鼠”（supermouse）的诞生是细胞工程技术最成功的例子。","a":"基因导人或转基因动物技术。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch01_13","q":"细胞生物学研究的常用技术有哪些？","a":"目前细胞生物学研究的常用技术有：①光学显微镜技术：用于观察细胞显微结构；②电子显微镜技术：探索细胞超微结构；③X-衍射技术：研究蛋白质和核酸等生物大分子结构：4细胞融合或杂交技术：用于培养具有新性状的细胞；5离心技术：用于分离细胞内不同形态、大小的细胞器；6细胞培养：用于培养能在体外长期生长的机体细胞；7流式细胞术：可对不同类型细胞进行分类并测其体积、DNA含量等；8放射自显影：利用放射性同位素对细胞中的DNA、RNA或蛋白质进行定位；9核酸分子杂交：可探测基因的缺失、结构、表达等状况；①0层析和电泳：可分离、纯化细胞中大分子物质。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_14","q":"为什么说细胞培养是细胞生物学研究的最基本技术之一？","a":"签在体外模拟体内的生理环境，培养从机体中取出的细胞，并使之生存和生长的技术称为细胞培养技术。细胞培养是细胞生物学研究中最基本的实验技术之一，在理论上如细胞全能性的揭示，细胞周期及其调控，癌机制与细胞衰老，基因表达与调控，细胞融合以及一些细胞工程技术的建立都是与细胞培养技术分不开的。在实验方面，植物细胞培养为植物育种开辟了新途径。动物细胞培养为疫苗生产、药物研制与肿瘤防治等医学实验提供了全新的手段。细胞培养是细胞生物学研究中最有价值的技术。通过细胞培养可获得大量的细胞，也可以通过细胞培养研究细胞的运动、细胞的信号转导、细胞的合成代谢等。突出的特点是在离体条件下观察和研究细胞生命活动的规律。培养中的细胞不受体内复杂环境的影响，可以人为改变培养条件。高等生物是由细胞构成的整体，在整体条件下要研究单个细胞或某一细胞在体内的功能活动是十分困难的。显然，如果把活细胞拿到体外进行培养来观察和研究，则要方便得多。细胞培养往往是进行细胞生物学研究的前提和基础，许多后期实验均建立在细胞培养的基础之上。细胞培养包括原核生物细胞、植物细胞、动物细胞以及与此密切相关的病毒的培养。活细胞离体后要在一定生理条件下才能存活和进行生理活动，特别是高等动植物细胞要求的生存条件极其严格，稍有不适就会死亡。故细胞培养必须注意三个环节：物质营养、生存环境与废物的排除。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_15","q":"什么是模式生物？","a":"举例说明模式生物的使用在细胞生物学研究中的应用。答①病毒：结构简单，基因组小，繁殖快，适合遗传操作。病毒主要用于基因表达调控、生物大分子相互作用、生命物质自组装以及肿瘤的发生与防治等方面的研究。②细菌：基因结构简单，培养方便，生长快，突变株的诱导、分离、鉴定技术成熟，转基因技术成熟，进行基因定位简便易行。是基因表达调控的研究材料。③酵母：是单细胞真核生物的代表，生长迅速并且易于遗传操作。在细胞周期调控、蛋白质的相互作用、膜泡运输、细胞分化与衰老等研究中被运用。4线虫：秀丽隐杆线虫基因组测序已经完成。其生命周期3天，繁殖快，在显微镜下通体透明，共有959个细胞。在发育生物学、遗传学、衰老和基因组学研究方面应用广泛。5拟南芥：十字花科。二年生草本，高7～40cm。拟南芥的优点是植株小（1cm²可种植好几棵）、每代时间短（从发芽到开花不超过6周）结子多（每株植物可产很多粒种子）、生活力强（用普通培养基就可作人工培养）。拟南芥的基因组是目前已知植物基因组中最小的。每个单倍染色体组（n=5）的总长只有7000万个碱基对，即只有小麦染色体组长的1/80，这就使克隆它的有关基因相对说来比较容易。拟南芥是自花授粉植物，基因高度纯合，用理化因素处理突变率很高，容易获得各种代谢功能的缺陷型。例如，用含杀草剂的培养基来筛选，一般获得抗杀草剂的突变率是1/100000。由于有上述这些优点，拟南芥是进行遗传学研究的好材料，被科学家誉为“植物中的果蝇”。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_16","q":"糖脂是细胞膜的重要组分，其中是最简单的糖脂，只有1个葡萄糖或半乳糖残基与相连接。","a":"半乳糖脑苷脂（脑苷脂类）；（鞘氨醇骨架的）伯羟基。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_17","q":"离子通道一般都具有选择性，K+通道允许（）A.K*通过，Na*、Ca²+不通过B.K、Na通过，Ca²+不通过C.K+、Ca²+通过，Na*不通过D.KNa*、Ca通过，C1-不通过","a":"A。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_18","q":"细胞内物质氧化的特点是（）。A.氧化产生的能量主要以热能形式传给细胞B.在常温常压下进行，既不冒烟也不燃烧C.不同代谢过程需要不同的酶催化D.氧化放能是分步、小量和逐渐进行的","a":"B、C、D。","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch01_19","q":"高尔基是细胞内大分子物质运输的主要交通工具。","a":"对。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_20","q":"细胞内能进行蛋白质修饰和分选的细胞器有（）。A.核糖体B.细胞核C.内质网D.高尔基体","a":"D。","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch01_21","q":"如何理解信号系统及其功能？","a":"答细胞表面受体：特异识别胞外信号。转承蛋白：负责信息向下传递。信使蛋白：携带信号从一部分传递到另外一部分。接头蛋白：连接信号蛋白。放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。传感蛋白：负责不同形式信号的转换。分歧蛋白：信号从一条途径传递到另外一条途径。整合蛋白：从多条通路接受信号并向下传递。潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_22","q":"细胞骨架由哪三类成分组成，各有什么主要功能？","a":"细胞骨架由微丝、微管和中间纤维构成。微丝确定细胞表面特征、使细胞能够运动和收缩。微管确定膜性细胞器的位置、帮助染色体分离和作为膜泡运输的导轨。中间纤维使细胞具有张力和抗剪切力。【答案】微管组装：αB微管蛋白形成异二聚体一异二聚体聚合成片状的核心→经过侧面增加异二聚体而使之扩展成13条原纤维丝，即环围成一段微管一新的异二聚体不断加到微管的端部一延长。微管生物学功能：①构成细胞内网状支架：维持形状，固定与支持细胞器；②细胞器位移和细胞运动：染色体移动、纤毛、鞭毛运动；③参与物质运输：颗粒物质沿微管移动；④与某些信息的传递有关。","src":"浙江理工大学，2009年","kp":null},{"id":"jyq_ch01_23","q":"细胞的体积有大小不同，但各种细胞核的大小常悬殊不大。","a":"对。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_24","q":"所有常染色质包含的基因，在任何时候都具有转录活性。","a":"错。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch01_25","q":"fish-trap模型的中央栓呈颗粒状或棒状，推测在过程中起作用。","a":"核质交换。","src":"南开大学，2009年","kp":null},{"id":"jyq_ch01_26","q":"DNA复制是按一定顺序进行的。从DNA分子结构看，一般早复制的部位是（)。A.转录不活跃的常染色质B.高度重复序列C.活性染色质D.卫星DNA","a":"C。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch01_27","q":"果蝇唾腺细胞与小鼠骨髓细胞在染色体结构与细胞核的动态变化上有何区别？","a":"果蝇的唾腺细胞中染色体易形成多线染色体，多线染色体来源于核内有丝分裂，即核内DNA多次复制而细胞不分裂，产生的子染色体并行排列，且体细胞内间源染色体配对，紧密结合在一起从而可阻止染色质纤维的进一步聚缩，形成体积很大的多线染色体。而小鼠骨髓细胞中不小会出现多线染色体。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch01_28","q":"为什么真核细胞被剔除细胞核后不能长期生存，而原核细胞无细胞核却能正常生存和繁殖？","a":"真核细胞剔除细胞核后，失去了遗传信息的载体，与生命活动相关的一些基因及其产物不能正常表达，代谢活动受阻，因而不能长期生存。原核细胞虽然无细胞核，但有类似真核细胞核的拟核，与原核细胞生存和繁殖的信息贮存在里面，它编码的遗传信息执行着与原核细胞相关的生命活动。","src":"武汉大学，2007年","kp":null},{"id":"jyq_ch01_29","q":"概述细胞核的基本结构及其主要功能。","a":"的核被膜，它将细胞核物质同细胞质分开；②似液态的核质，其中含有可溶性的核物质；③一个或多个球形的核仁，这种结构与核糖体的合成有关；④核基质，为细胞核提供骨架网络；5DNA纤维，当它展开存在于细胞核中时称为染色质，组成致密结构时称为染色体。它的功能主要有两个方面，一方面它是遗传信息的主要贮存库，载释臻物率，分：裂对4通过复第十一章细胞核与染色体制将遗传信息传给下一代细胞；另一方面，细胞核是DNA复制和RNA转录场所，进行遗传信息的表达时，合成蛋白质所需要的mRNA、rRNA和tRNA都是来自细胞核，新合成的mRNA、rRNA和核糖体亚单位从核内运输到细胞质，以及蛋白质和能源物质等成分从细胞质转运人核内，需要依靠核被膜的运输，核被膜调节着核-质间的物质交换。总之，细胞核是细胞内DNA贮存、复制和RNA转录中心，也是细胞代谢、生长、分化和繁殖的控制枢纽。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_30","q":"概述核仁的结构及其功能。","a":"答核仁的超微结构包括：纤维中心、致密纤维组分、颗粒组分、核仁相随染色质与核仁基质。核仁的功能主要涉及核糖体的生物发生。这一过程包括rRNA的合成、加工和核糖体亚单位的装配。还涉及mRNA的输出与降解。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch01_31","q":"细胞在有充足营养条件下，从G，期进人M期。","a":"对。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch01_32","q":"酵母细胞“DNA复制是否完成”控制点位于G2期，若DNA复制未完成，则细胞能进人G2期，但不能完成G2期的事件。","a":"错。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_33","q":"各种周期蛋白均含有一段相当保守的氨基酸序列，这段序列称为","a":"周期蛋白框。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch01_34","q":"下面三种关于对“癌细胞是单克隆的”说法的诠释中，哪一种合理（）。A.癌细胞刺激了抗体的产生B.癌细胞起源于某个不确定的细胞的失控繁殖C.癌在个体的一生中只出现一次","a":"B","src":"中山大学，2009年","kp":null},{"id":"jyq_ch01_35","q":"小鼠脑、肾、胸腺、脾、肝组织的DNA分别与小鼠L-细胞的DNA对小鼠胚胎DNA进行竞争杂交，各种组织来源的DNA的竞争结合速率（）。A.不一样B.一样C.有显著差异D.各不相同","a":"B。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch01_36","q":"以植物管状细胞（如导管）的分化为例，说明植物细胞PCD（programmedcelldeath）的过程和特点，它与动物细胞凋亡有何不同。","a":"①植物管状细胞（如导管）的分化过程为典型的PCD过程。②植物细胞PCD（programmedcelldeath）过程和特点：细胞壁增厚一液泡膜破裂一DNA降解一细胞器和内含物分解→自我吸收→细胞壁一无生命的导管。③程序性细胞死亡是指由基因控制的细胞自主的有序性死亡。它涉及一系列基因的激活、表达以及调控等作用。程序性细胞死亡是保证个体发育成熟所必需的，是一个细胞生理功能性概念。动物和植物都发生PCD细胞凋亡多指动物细胞。它是一个形态学概念，指与细胞坏死不同的受到基因控制的细胞死亡形式；其最典型特点是产生凋亡小体，凋亡小体被周围细胞吞噬。但植物细胞PCD不产生凋亡小体，死亡细胞被液泡中的酸性酶分解，吸收。","src":"华中农业大学，2008年","kp":null},{"id":"jyq_ch01_37","q":"各举1例说明植物细胞编程性死亡在植物器官建成和抗逆性中的作用。","a":"①植物器官建成：如筛管，导管发育；花形成等；②植物抗逆性：抗病中的应急反应；抗渍害中的通气组织形成等。【答案】程序性细胞死亡又称为细胞凋亡（apoptosis），是指为维持内环境稳定，由基因控制的细胞自主的有序性的死亡，它涉及一系列基因的激活、表达以及调控等的作用，因而是具有生理性和选择性的。Apoptosis的概念来自于希腊语，原意是指树叶或花的自然凋落，而细胞发生程序性死亡时，就像树叶或花的自然凋落一样，凋亡的细胞散在于正常组织细胞中，无炎症反应，不遗留痕。死亡的细胞碎片很快被巨噬细胞或邻近细胞清除，不影响其他细胞的正常功能细胞程序死亡与细胞坏死是两种完全不同的过程和生物学现象，在形态学、生化代谢改变、分子机制、细胞的结局和意义等方面都有本质的区别。编程死亡与细胞坏死有三个根本的区别，首先是引起死亡的原因不同，如物理性或化学性的损害因子及缺氧与营养不良等均导致细胞坏死，而编程性细胞死亡则是由基因控制的；第二是死亡的过程不同，坏死细胞的胞膜通透性增高，致使细胞肿胀，细胞器变形或肿大，早期核无明显形态学变化，最后细胞破裂。而编程死亡的细胞不会膨胀、破裂，而是收缩并被割裂成膜性小泡后被吞噬；第三是坏死的细胞裂解要释放出内含物，并常引起炎症反应；在愈合过程中常伴随组织器官的纤维化，形成痕。而编程死亡的细胞没有被完全裂解，所以不会引起炎症。","src":"华中农业大学，2009年","kp":null}],"outline":["细胞的发现","细胞学说的建立","原核 vs 真核","模式生物","学科框架"],"outlineMap":[0,0,2,3,3]};